export default "       file=file,\\n        session=session,\\n        current_user=current_user,\\n        storage_service=storage_service,\\n        settings_service=locked_settings,\\n    )\\n\\n    expected_path = f\\\"{current_user.id}/{mcp_file}.json\\\"\\n    assert storage_service._store[expected_path] == content\\n\\n\\n@pytest.mark.asyncio\\nasync def test_mcp_servers_upload_rejects_stdio_under_code_execution_lockdown(session, storage_service, current_user):\\n    \\\"\\\"\\\"The raw MCP config upload cannot bypass the code-execution lockdown.\\\"\\\"\\\"\\n    restricted_settings = SimpleNamespace(\\n        settings=SimpleNamespace(\\n            max_file_size_upload=10,\\n            mcp_servers_locked=False,\\n            allow_custom_components=False,\\n            custom_component_admin_only=False,\\n        )\\n    )\\n    current_user.is_superuser = False\\n\\n    mcp_file_ext = await get_mcp_file(current_user, extension=True)\\n    content = b'{\\\"mcpServers\\\": {\\\"evil\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"attacker-controlled-package\\\"]}}}'\\n    file = UploadFile(filename=mcp_file_ext, file=io.BytesIO(content))\\n    file.size = len(content)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await upload_user_file(\\n            file=file,\\n            session=session,\\n            current_user=current_user,\\n            storage_service=storage_service,\\n            settings_service=restricted_settings,\\n        )\\n\\n    assert exc_info.value.status_code == 403\\n    assert storage_service._store == {}\\n    assert session._db == {}\\n\\n\\n@pytest.mark.asyncio\\nasync def test_mcp_servers_upload_allows_remote_server_under_code_execution_lockdown(\\n    session, storage_service, current_user\\n):\\n    \\\"\\\"\\\"Remote MCP configs remain usable because they do not spawn a local process.\\\"\\\"\\\"\\n    restricted_settings = SimpleNamespace(\\n        settings=SimpleNamespace(\\n            max_file_size_upload=10,\\n            mcp_servers_locked=False,\\n            allow_custom_components=True,\\n            custom_component_admin_only=True,\\n        )\\n    )\\n    current_user.is_superuser = False\\n\\n    mcp_file_ext = await get_mcp_file(current_user, extension=True)\\n    mcp_file = await get_mcp_file(current_user)\\n    content = b'{\\\"mcpServers\\\": {\\\"remote\\\": {\\\"url\\\": \\\"https://mcp.example.com\\\"}}}'\\n    file = UploadFile(filename=mcp_file_ext, file=io.BytesIO(content))\\n    file.size = len(content)\\n\\n    await upload_user_file(\\n        file=file,\\n        session=session,\\n        current_user=current_user,\\n        storage_service=storage_service,\\n        settings_service=restricted_settings,\\n    )\\n\\n    expected_path = f\\\"{current_user.id}/{mcp_file}.json\\\"\\n    assert storage_service._store[expected_path] == content\\n\\n\\n@pytest.mark.asyncio\\nasync def test_mcp_servers_upload_allows_stdio_for_superuser_under_code_execution_lockdown(\\n    session, storage_service, current_user\\n):\\n    \\\"\\\"\\\"Administrators retain access to local MCP processes under admin-only lockdown.\\\"\\\"\\\"\\n    restricted_settings = SimpleNamespace(\\n        settings=SimpleNamespace(\\n            max_file_size_upload=10,\\n            mcp_servers_locked=False,\\n            allow_custom_components=False,\\n            custom_component_admin_only=True,\\n        )\\n    )\\n    current_user.is_superuser = True\\n\\n    mcp_file_ext = await get_mcp_file(current_user, extension=True)\\n    mcp_file = await get_mcp_file(current_user)\\n    content = b'{\\\"mcpServers\\\": {\\\"fetch\\\": {\\\"command\\\": \\\"uvx\\\", \\\"args\\\": [\\\"mcp-server-fetch\\\"]}}}'\\n    file = UploadFile(filename=mcp_file_ext, file=io.BytesIO(content))\\n    file.size = len(content)\\n\\n    await upload_user_file(\\n        file=file,\\n        session=session,\\n        current_user=current_user,\\n        storage_service=storage_service,\\n        settings_service=restricted_settings,\\n    )\\n\\n    expected_path = f\\\"{current_user.id}/{mcp_file}.json\\\"\\n    assert storage_service._store[expected_path] == content\\n\\n\\n@pytest.mark.asyncio\\nasync def test_concurrent_update_server_should_not_lose_servers(tmp_path):\\n    \\\"\\\"\\\"Concurrent update_server() calls must not silently drop servers.\\n\\n    Formerly update_server() did a non-atomic read-modify-write on the MCP config\\n    file; overlapping calls read the same stale config and the last write won,\\n    silently losing a server. MCP servers are now one row per server in the\\n    mcp_server table (unique on (user_id, name)), so concurrent adds of different\\n    servers touch different rows and cannot lose each other \u2014 with no in-process\\n    lock. This is the regression guard for that lost-update bug.\\n    \\\"\\\"\\\"\\n    import asyncio\\n    import uuid as uuid_lib\\n    from unittest.mock import MagicMock, patch\\n\\n    import langflow.services.database.models  # noqa: F401  (register SQLModel tables)\\n    from langflow.api.v2.mcp import get_server_list, update_server\\n    from sqlalchemy import event\\n    from sqlalchemy.ext.asyncio import create_async_engine\\n    from sqlmodel import SQLModel\\n    from sqlmodel.ext.asyncio.session import AsyncSession\\n\\n    # File-backed DB so each concurrent session gets its own connection.\\n    engine = create_async_engine(f\\\"sqlite+aiosqlite:///{tmp_path / 'mcp.db'}\\\", connect_args={\\\"timeout\\\": 30})\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def _pragmas(dbapi_conn, _record):\\n        cur = dbapi_conn.cursor()\\n        cur.execute(\\\"PRAGMA journal_mode=WAL\\\")\\n        cur.execute(\\\"PRAGMA busy_timeout=30000\\\")\\n        cur.close()\\n\\n    async with engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n\\n    user = SimpleNamespace(id=uuid_lib.uuid4())\\n\\n    async def add(name: str, val: str) -> None:\\n        async with AsyncSession(engine, expire_on_commit=False) as session:\\n            await update_server(name, {\\\"command\\\": \\\"echo\\\", \\\"args\\\": [val]}, user, session, None, None)\\n\\n    with patch.multiple(\\n        \\\"langflow.api.v2.mcp\\\",\\n        get_shared_component_cache_service=MagicMock(return_value=SimpleNamespace()),\\n        safe_cache_get=MagicMock(return_value={}),\\n        safe_cache_set=MagicMock(),\\n    ):\\n        await add(\\\"server_a\\\", \\\"a\\\")\\n        await asyncio.gather(add(\\\"server_b\\\", \\\"b\\\"), add(\\\"server_c\\\", \\\"c\\\"))\\n        async with AsyncSession(engine, expire_on_commit=False) as session:\\n            servers = (await get_server_list(user, session, None, None))[\\\"mcpServers\\\"]\\n\\n    await engine.dispose()\\n    assert \\\"server_a\\\" in servers, \\\"server_a was lost due to concurrent update_server race condition\\\"\\n    assert \\\"server_b\\\" in servers, \\\"server_b was lost due to concurrent update_server race condition\\\"\\n    assert \\\"server_c\\\" in servers, \\\"server_c was lost due to concurrent update_server race condition\\\"\\n\\n\\ndef test_enforce_immutable_server_name_rejects_mismatch():\\n    \\\"\\\"\\\"A body name that differs from the URL name is an explicit 422, not a silent no-op.\\\"\\\"\\\"\\n    from langflow.api.v2.mcp import _enforce_immutable_server_name\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        _enforce_immutable_server_name(\\\"old-name\\\", {\\\"name\\\": \\\"new-name\\\", \\\"url\\\": \\\"http://localhost:9000\\\"})\\n\\n    assert exc_info.value.status_code == 422\\n    # The message names both the URL identifier and the rejected body value.\\n    assert \\\"old-name\\\" in exc_info.value.detail\\n    assert \\\"new-name\\\" in exc_info.value.detail\\n\\n\\ndef test_enforce_immutable_server_name_strips_matching_name():\\n    \\\"\\\"\\\"A redundant matching name is dropped so it never pollutes the stored config.\\\"\\\"\\\"\\n    from langflow.api.v2.mcp import _enforce_immutable_server_name\\n\\n    cleaned = _enforce_immutable_server_name(\\\"srv\\\", {\\\"name\\\": \\\"srv\\\", \\\"command\\\": \\\"npx\\\", \\\"args\\\": [\\\"-y\\\", \\\"x\\\"]})\\n\\n    assert cleaned == {\\\"command\\\": \\\"npx\\\", \\\"args\\\": [\\\"-y\\\", \\\"x\\\"]}\\n    assert \\\"name\\\" not in cleaned\\n\\n\\ndef test_enforce_immutable_server_name_passthrough_without_name():\\n    \\\"\\\"\\\"Configs without a name field are returned unchanged.\\\"\\\"\\\"\\n    from langflow.api.v2.mcp import _enforce_immutable_server_name\\n\\n    config = {\\\"command\\\": \\\"npx\\\", \\\"args\\\": [\\\"-y\\\", \\\"x\\\"]}\\n\\n    assert _enforce_immutable_server_name(\\\"srv\\\", config) == config\\n\\n\\n@pytest.mark.asyncio\\nasync def test_patch_server_rejects_name_change(session, storage_service, settings_service, current_user):\\n    \\\"\\\"\\\"PATCH with a body name different from the URL must 422 instead of silently no-op'ing.\\n\\n    Regression: MCPServerConfig allows extra fields, so a ``name`` in the PATCH body was\\n    persisted as stray config and echoed in the 200 response, falsely implying a rename\\n    succeeded while the server stayed keyed under the original (URL) name.\\n    \\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n\\n    from langflow.api.v2.mcp import update_server_endpoint\\n    from langflow.api.v2.schemas import MCPServerConfig\\n\\n    body = MCPServerConfig(name=\\\"new-name\\\", url=\\\"http://localhost:9000\\\")\\n\\n    with (\\n        patch(\\\"langflow.api.v2.mcp.update_server\\\", new=AsyncMock()) as mock_update,\\n        pytest.raises(HTTPException) as exc_info,\\n    ):\\n        await update_server_endpoint(\\n            server_name=\\\"old-name\\\",\\n            server_config=body,\\n            current_user=current_user,\\n            session=session,\\n            storage_service=storage_service,\\n            settings_service=settings_service,\\n        )\\n\\n    assert exc_info.value.status_code == 422\\n    mock_update.assert_not_called()  # guard fires before any write/upsert\\n\\n\\n@pytest.mark.asyncio\\nasync def test_patch_server_strips_matching_name_before_persist(\\n    session, storage_service, settings_service, current_user\\n):\\n    \\\"\\\"\\\"A PATCH body that echoes the URL name must not persist ``name`` as stray config.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n\\n    from langflow.api.v2.mcp import update_server_endpoint\\n    from langflow.api.v2.schemas import MCPServerConfig\\n\\n    body = MCPServerConfig(name=\\\"srv\\\", url=\\\"http://localhost:9000\\\")\\n\\n    with patch(\\\"langflow.api.v2.mcp.update_server\\\", new=AsyncMock(return_value={\\\"ok\\\": True})) as mock_update:\\n        await update_server_endpoint(\\n            server_name=\\\"srv\\\",\\n            server_config=body,\\n            current_user=current_user,\\n            session=session,\\n            storage_service=storage_service,\\n            settings_service=settings_service,\\n        )\\n\\n    # update_server is called positionally as (server_name, server_config_dict, ...).\\n    persisted_config = mock_update.call_args.args[1]\\n    assert persisted_config == {\\\"url\\\": \\\"http://localhost:9000\\\"}\\n    assert \\\"name\\\" not in persisted_config\\n\\n\\n@pytest.mark.asyncio\\nasync def test_post_server_rejects_name_mismatch(session, storage_service, settings_service, current_user):\\n    \\\"\\\"\\\"POST with a body name different from the URL must 422 (same guard as PATCH).\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, patch\\n\\n    from langflow.api.v2.mcp import add_server\\n    from langflow.api.v2.schemas import MCPServerConfig\\n\\n    body = MCPServerConfig(name=\\\"different\\\", url=\\\"http://localhost:9000\\\")\\n\\n    with (\\n        patch(\\\"langflow.api.v2.mcp.update_server\\\", new=AsyncMock()) as mock_update,\\n        pytest.raises(HTTPException) as exc_info,\\n    ):\\n        await add_server(\\n            server_name=\\\"intended-name\\\",\\n            server_config=body,\\n            current_user=current_user,\\n            session=session,\\n            storage_service=storage_service,\\n            settings_service=settings_service,\\n        )\\n\\n    assert exc_info.value.status_code == 422\\n    mock_update.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v2/test_output_event_parity.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"88ff22f8d4ef210c62b49ac7254a0154e68db0902bbf580583d4823f581fc34a\",\"content\":\"\\\"\\\"\\\"Sync/stream parity for per-component outputs.\\n\\nThe ``langflow`` stream emits one ``output`` event per terminal output carrying\\nthe same ``ComponentOutput`` shape sync returns in ``outputs[id]``. These tests\\npin (a) the authoritative metadata the v1 build path ships on ``end_vertex``,\\n(b) the adapter emitting ``output`` only for terminals, and (c) builder parity \u2014\\nthe two result-data forms pass through one builder to the same output. (Real-run\\n``content`` is each mode's own serialization; see the e2e shape test in\\n``test_workflow_agui.py``.)\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom unittest.mock import Mock\\n\\nfrom langflow.api.build import _output_meta_for_vertex\\nfrom lfx.workflow.adapters import StreamAdapterContext\\nfrom lfx.workflow.adapters.langflow import LangflowAdapter\\nfrom lfx.workflow.converters import build_component_output, resolve_output_type\\n\\n\\ndef _adapter() -> LangflowAdapter:\\n    return LangflowAdapter(StreamAdapterContext(run_id=\\\"run-1\\\", thread_id=\\\"thread-1\\\"))\\n\\n\\ndef _end_vertex_data(component_id: str, text: str, *, is_terminal: bool = True, is_output: bool = True) -> dict:\\n    return {\\n        \\\"build_data\\\": {\\\"id\\\": component_id, \\\"valid\\\": True, \\\"data\\\": {\\\"outputs\\\": {\\\"message\\\": {\\\"message\\\": text}}}},\\n        \\\"output_meta\\\": {\\n            \\\"component_id\\\": component_id,\\n            \\\"display_name\\\": \\\"Chat Output\\\",\\n            \\\"vertex_type\\\": \\\"ChatOutput\\\",\\n            \\\"is_output\\\": is_output,\\n            \\\"is_terminal\\\": is_terminal,\\n            \\\"output_types\\\": [\\\"Message\\\"],\\n        },\\n    }\\n\\n\\ndef _result_object(text: str) -> Mock:\\n    \\\"\\\"\\\"Sync-side result data: an object whose ``.outputs`` mirrors the stream dict's ``outputs``.\\\"\\\"\\\"\\n    rd = Mock()\\n    rd.outputs = {\\\"message\\\": {\\\"message\\\": text}}\\n    rd.metadata = {}\\n    return rd\\n\\n\\ndef _vertex(vertex_id: str, *, is_output: bool = True, display_name: str = \\\"Chat Output\\\") -> Mock:\\n    vertex = Mock()\\n    vertex.id = vertex_id\\n    vertex.display_name = display_name\\n    vertex.vertex_type = \\\"ChatOutput\\\"\\n    vertex.is_output = is_output\\n    vertex.outputs = [{\\\"types\\\": [\\\"Message\\\"]}]\\n    return vertex\\n\\n\\ndef _graph(vertices: list[Mock], terminal_ids: list[str]) -> Mock:\\n    graph = Mock()\\n    graph.vertices = vertices\\n    by_id = {v.id: v for v in vertices}\\n    graph.get_vertex = Mock(side_effect=lambda vid: by_id[vid])\\n    graph.get_terminal_nodes = Mock(return_value=terminal_ids)\\n    return graph\\n\\n\\nclass TestOutputMetaForVertex:\\n    \\\"\\\"\\\"The v1 build path ships authoritative vertex metadata as an additive key.\\\"\\\"\\\"\\n\\n    def test_carries_authoritative_vertex_facts(self):\\n        v = _vertex(\\\"ChatOutput-abc\\\")\\n        graph = _graph([v], terminal_ids=[\\\"ChatOutput-abc\\\"])\\n\\n        meta = _output_meta_for_vertex(graph, \\\"ChatOutput-abc\\\")\\n\\n        assert meta[\\\"component_id\\\"] == \\\"ChatOutput-abc\\\"\\n        assert meta[\\\"display_name\\\"] == \\\"Chat Output\\\"\\n        assert meta[\\\"vertex_type\\\"] == \\\"ChatOutput\\\"\\n        assert meta[\\\"is_output\\\"] is True\\n        assert meta[\\\"is_terminal\\\"] is True\\n        assert meta[\\\"output_types\\\"] == [\\\"Message\\\"]\\n\\n    def test_non_terminal_vertex_marked_not_terminal(self):\\n        a = _vertex(\\\"ChatOutput-a\\\")\\n        b = _vertex(\\\"LLM-b\\\", is_output=False, display_name=\\\"LLM\\\")\\n        graph = _graph([a, b], terminal_ids=[\\\"ChatOutput-a\\\"])\\n\\n        meta = _output_meta_for_vertex(graph, \\\"LLM-b\\\")\\n        assert meta[\\\"is_terminal\\\"] is False\\n\\n\\nclass TestLangflowAdapterOutputEvent:\\n    \\\"\\\"\\\"On a terminal end_vertex, the adapter ALSO emits a normalized ``output`` event.\\\"\\\"\\\"\\n\\n    def test_terminal_end_vertex_adds_output_event(self):\\n        events = list(_adapter().translate(\\\"end_vertex\\\", _end_vertex_data(\\\"ChatOutput-abc\\\", \\\"Hi there!\\\")))\\n        types = [e.type for e in events]\\n        # The raw end_vertex passthrough is preserved AND an output event is added.\\n        assert \\\"end_vertex\\\" in types\\n        assert \\\"output\\\" in types\\n\\n        output = next(e for e in events if e.type == \\\"output\\\")\\n        payload = json.loads(output.data_json)\\n        assert payload[\\\"event\\\"] == \\\"output\\\"\\n        data = payload[\\\"data\\\"]\\n        assert data[\\\"component_id\\\"] == \\\"ChatOutput-abc\\\"\\n        assert data[\\\"type\\\"] == \\\"message\\\"\\n        assert data[\\\"display_name\\\"] == \\\"Chat Output\\\"\\n        assert data[\\\"content\\\"] == \\\"Hi there!\\\"\\n        assert data[\\\"status\\\"] == \\\"completed\\\"\\n\\n    def test_non_terminal_end_vertex_is_passthrough_only(self):\\n        events = list(\\n            _adapter().translate(\\\"end_vertex\\\", _end_vertex_data(\\\"LLM-b\\\", \\\"x\\\", is_terminal=False, is_output=False))\\n        )\\n        assert [e.type for e in events] == [\\\"end_vertex\\\"]\\n\\n    def test_other_events_unchanged(self):\\n        events = list(_adapter().translate(\\\"token\\\", {\\\"id\\\": \\\"m1\\\", \\\"chunk\\\": \\\"Hi\\\"}))\\n        assert [e.type for e in events] == [\\\"token\\\"]\\n        assert json.loads(events[0].data_json) == {\\\"event\\\": \\\"token\\\", \\\"data\\\": {\\\"id\\\": \\\"m1\\\", \\\"chunk\\\": \\\"Hi\\\"}}\\n\\n\\nclass TestSyncStreamParity:\\n    \\\"\\\"\\\"Builder parity: equivalent result data (object form vs dict form) builds the same output.\\n\\n    Proves there is NO per-mode logic divergence \u2014 the sync ``ResultData`` object and the\\n    stream ``VertexBuildResponse.data`` dict pass through the SAME ``build_component_output``\\n    to the same ``ComponentOutput``. (When real runs differ, it's because the framework puts\\n    different data in the two sources, not because this code diverges \u2014 see the e2e shape test.)\\n    \\\"\\\"\\\"\\n\\n    def test_object_and_dict_result_data_build_identical_output(self):\\n        component_id = \\\"ChatOutput-abc\\\"\\n\\n        # Sync side builds from an OBJECT result_data (RunResponse ResultData form).\\n        sync_output = build_component_output(\\n            component_id=component_id,\\n            is_output=True,\\n            vertex_type=\\\"ChatOutput\\\",\\n            output_type=resolve_output_type([\\\"Message\\\"], \\\"ChatOutput\\\"),\\n            display_name=\\\"Chat Output\\\",\\n            result_data=_result_object(\\\"Hi there!\\\"),\\n        )\\n\\n        # Stream side builds from the DICT event (VertexBuildResponse.data form).\\n        output = next(\\n            e\\n            for e in _adapter().translate(\\\"end_vertex\\\", _end_vertex_data(component_id, \\\"Hi there!\\\"))\\n            if e.type == \\\"output\\\"\\n        )\\n        stream_data = json.loads(output.data_json)[\\\"data\\\"]\\n\\n        # Identical, except component_id (which sync carries as the dict key).\\n        assert {k: v for k, v in stream_data.items() if k != \\\"component_id\\\"} == sync_output.model_dump(mode=\\\"json\\\")\\n        assert stream_data[\\\"component_id\\\"] == component_id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v2/test_registration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e6f4107b752294827f463e71c04831717b3ae69145f29563c0fa8e44c2b25322\",\"content\":\"import json\\nfrom unittest.mock import MagicMock, mock_open, patch\\n\\nimport pytest\\nfrom fastapi.testclient import TestClient\\nfrom httpx import AsyncClient\\nfrom langflow.api.v2.registration import (\\n    RegisterRequest,\\n    RegisterResponse,\\n    _ensure_registration_file,\\n    load_registration,\\n    router,\\n    save_registration,\\n)\\nfrom langflow.main import create_app\\n\\n\\n@pytest.fixture\\ndef client():\\n    \\\"\\\"\\\"Create test client.\\\"\\\"\\\"\\n    app = create_app()\\n    return TestClient(app)\\n\\n\\n@pytest.fixture\\ndef async_client():\\n    \\\"\\\"\\\"Create async test client.\\\"\\\"\\\"\\n    app = create_app()\\n    return AsyncClient(app=app, base_url=\\\"http://test\\\")\\n\\n\\n@pytest.fixture\\ndef mock_registration_file(tmp_path):\\n    \\\"\\\"\\\"Create temporary registration file for testing.\\\"\\\"\\\"\\n    file_path = tmp_path / \\\"data\\\" / \\\"user\\\" / \\\"registration.json\\\"\\n    file_path.parent.mkdir(parents=True, exist_ok=True)\\n    return file_path\\n\\n\\nclass TestDataModels:\\n    \\\"\\\"\\\"Test Pydantic models.\\\"\\\"\\\"\\n\\n    def test_register_request_valid_email(self):\\n        \\\"\\\"\\\"Test RegisterRequest with valid email.\\\"\\\"\\\"\\n        request = RegisterRequest(email=\\\"test@example.com\\\")\\n        assert request.email == \\\"test@example.com\\\"\\n\\n    def test_register_request_invalid_email(self):\\n        \\\"\\\"\\\"Test RegisterRequest with invalid email.\\\"\\\"\\\"\\n        with pytest.raises(ValueError):  # noqa: PT011\\n            RegisterRequest(email=\\\"invalid-email\\\")\\n\\n    def test_register_response(self):\\n        \\\"\\\"\\\"Test RegisterResponse model.\\\"\\\"\\\"\\n        response = RegisterResponse(success=True, message=\\\"Registration successful\\\", email=\\\"test@example.com\\\")\\n        assert response.email == \\\"test@example.com\\\"\\n\\n\\nclass TestHelperFunctions:\\n    \\\"\\\"\\\"Test helper functions.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    def test_ensure_registration_file_creates_directory(self, mock_file):\\n        \\\"\\\"\\\"Test that _ensure_registration_file creates directory with proper permissions.\\\"\\\"\\\"\\n        mock_parent = MagicMock()\\n        mock_file.parent = mock_parent\\n\\n        _ensure_registration_file()\\n\\n        mock_parent.mkdir.assert_called_once_with(parents=True, exist_ok=True)\\n        mock_parent.chmod.assert_called_once_with(0o700)\\n\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    @patch(\\\"langflow.api.v2.registration.logger\\\")\\n    def test_ensure_registration_file_handles_error(self, mock_logger, mock_file):\\n        \\\"\\\"\\\"Test that _ensure_registration_file handles errors properly.\\\"\\\"\\\"\\n        mock_file.parent.mkdir.side_effect = Exception(\\\"Permission denied\\\")\\n\\n        with pytest.raises(Exception):  # noqa: B017, PT011\\n            _ensure_registration_file()\\n\\n        mock_logger.error.assert_called()\\n\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    def test_load_registration_file_not_exists(self, mock_file):\\n        \\\"\\\"\\\"Test load_registration when file doesn't exist.\\\"\\\"\\\"\\n        mock_file.exists.return_value = False\\n\\n        result = load_registration()\\n\\n        assert result is None\\n\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    def test_load_registration_empty_file(self, mock_file):\\n        \\\"\\\"\\\"Test load_registration with empty file.\\\"\\\"\\\"\\n        mock_file.exists.return_value = True\\n        mock_file.stat.return_value.st_size = 0\\n\\n        result = load_registration()\\n\\n        assert result is None\\n\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    def test_load_registration_valid_file(self, mock_file):\\n        \\\"\\\"\\\"Test load_registration with valid JSON file.\\\"\\\"\\\"\\n        mock_file.exists.return_value = True\\n        mock_file.stat.return_value.st_size = 100\\n\\n        registration_data = {\\\"email\\\": \\\"test@example.com\\\", \\\"registered_at\\\": \\\"2024-01-01T00:00:00Z\\\"}\\n\\n        # Mock the file open operation to return the registration data as JSON\\n        # This simulates reading a valid JSON file containing registration information\\n        mock_file.open.return_value.__enter__ = mock_open(\\n            read_data=json.dumps(registration_data)\\n        ).return_value.__enter__\\n\\n        result = load_registration()\\n\\n        assert result == registration_data\\n\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    @patch(\\\"langflow.api.v2.registration.logger\\\")\\n    def test_load_registration_corrupted_file(self, mock_logger, mock_file):\\n        \\\"\\\"\\\"Test load_registration with corrupted JSON file.\\\"\\\"\\\"\\n        mock_file.exists.return_value = True\\n        mock_file.stat.return_value.st_size = 100\\n        mock_file.open.return_value.__enter__ = mock_open(read_data=\\\"invalid json {\\\").return_value.__enter__\\n\\n        result = load_registration()\\n\\n        assert result is None\\n        mock_logger.error.assert_called()\\n\\n    @patch(\\\"langflow.api.v2.registration._ensure_registration_file\\\")\\n    @patch(\\\"langflow.api.v2.registration.load_registration\\\")\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    @patch(\\\"langflow.api.v2.registration.logger\\\")\\n    def test_save_registration_new(self, mock_logger, mock_file, mock_load, mock_ensure):\\n        \\\"\\\"\\\"Test save_registration with new registration.\\\"\\\"\\\"\\n        mock_load.return_value = None\\n        mock_file_handle = MagicMock()\\n        mock_file.open.return_value.__enter__ = MagicMock(return_value=mock_file_handle)\\n        mock_file.open.return_value.__exit__ = MagicMock()\\n\\n        result = save_registration(\\\"new@example.com\\\")\\n\\n        assert result is True\\n        mock_ensure.assert_called_once()\\n        mock_load.assert_called_once()\\n        mock_logger.info.assert_called_with(\\\"Registration saved: new@example.com\\\")\\n\\n    @patch(\\\"langflow.api.v2.registration._ensure_registration_file\\\")\\n    @patch(\\\"langflow.api.v2.registration.load_registration\\\")\\n    @patch(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\")\\n    @patch(\\\"langflow.api.v2.registration.logger\\\")\\n    def test_save_registration_replace_existing(self, mock_logger, mock_file, mock_load, mock_ensure):  # noqa: ARG002\\n        \\\"\\\"\\\"Test save_registration replacing existing registration.\\\"\\\"\\\"\\n        mock_load.return_value = {\\\"email\\\": \\\"old@example.com\\\", \\\"registered_at\\\": \\\"2024-01-01T00:00:00Z\\\"}\\n        mock_file_handle = MagicMock()\\n        mock_file.open.return_value.__enter__ = MagicMock(return_value=mock_file_handle)\\n        mock_file.open.return_value.__exit__ = MagicMock()\\n\\n        result = save_registration(\\\"new@example.com\\\")\\n\\n        assert result is True\\n        # Check for replacement log\\n        assert any(\\\"Replacing registration\\\" in str(call) for call in mock_logger.info.call_args_list)\\n\\n    @patch(\\\"langflow.api.v2.registration._ensure_registration_file\\\")\\n    @patch(\\\"langflow.api.v2.registration.logger\\\")\\n    def test_save_registration_handles_error(self, mock_logger, mock_ensure):\\n        \\\"\\\"\\\"Test save_registration handles errors properly.\\\"\\\"\\\"\\n        mock_ensure.side_effect = Exception(\\\"Permission denied\\\")\\n\\n        with pytest.raises(Exception) as exc_info:  # noqa: PT011\\n            save_registration(\\\"test@example.com\\\")\\n\\n        assert \\\"Permission denied\\\" in str(exc_info.value)\\n        mock_logger.error.assert_called()\\n\\n\\nclass TestAPIEndpoints:\\n    \\\"\\\"\\\"Test API endpoints.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.save_registration\\\")\\n    async def test_register_user_success(self, mock_save):\\n        \\\"\\\"\\\"Test successful user registration.\\\"\\\"\\\"\\n        mock_save.return_value = True\\n\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n        client = TestClient(app)\\n\\n        response = client.post(\\n            \\\"/registration/\\\",  # Fixed: Added /registration prefix\\n            json={\\\"email\\\": \\\"test@example.com\\\"},\\n        )\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"email\\\"] == \\\"test@example.com\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.save_registration\\\")\\n    async def test_register_user_invalid_email(self, mock_save):  # noqa: ARG002\\n        \\\"\\\"\\\"Test registration with invalid email.\\\"\\\"\\\"\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n        client = TestClient(app)\\n\\n        response = client.post(\\n            \\\"/registration/\\\",  # Fixed: Added /registration prefix\\n            json={\\\"email\\\": \\\"invalid-email\\\"},\\n        )\\n\\n        assert response.status_code == 422  # Validation error\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.save_registration\\\")\\n    async def test_register_user_save_fails(self, mock_save):\\n        \\\"\\\"\\\"Test registration when save fails.\\\"\\\"\\\"\\n        mock_save.side_effect = Exception(\\\"Save failed\\\")\\n\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n        client = TestClient(app)\\n\\n        response = client.post(\\n            \\\"/registration/\\\",  # Fixed: Added /registration prefix\\n            json={\\\"email\\\": \\\"test@example.com\\\"},\\n        )\\n\\n        assert response.status_code == 500\\n        assert \\\"Registration failed\\\" in response.json()[\\\"detail\\\"]\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.save_registration\\\")\\n    async def test_register_user_requires_auth(self, mock_save):\\n        \\\"\\\"\\\"POST /registration/ must require authentication (no anonymous email registration).\\\"\\\"\\\"\\n        from fastapi import FastAPI, HTTPException\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        def _deny():\\n            raise HTTPException(status_code=403, detail=\\\"Not authenticated\\\")\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n        # If the endpoint were missing the auth dependency, this override would\\n        # never run and save_registration would be reached (200/500).\\n        app.dependency_overrides[get_current_active_user] = _deny\\n        client = TestClient(app)\\n\\n        response = client.post(\\\"/registration/\\\", json={\\\"email\\\": \\\"anon@example.com\\\"})\\n\\n        assert response.status_code == 403\\n        mock_save.assert_not_called()\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.load_registration\\\")\\n    async def test_get_registration_exists(self, mock_load):\\n        \\\"\\\"\\\"Test getting existing registration.\\\"\\\"\\\"\\n        mock_load.return_value = {\\\"email\\\": \\\"test@example.com\\\", \\\"registered_at\\\": \\\"2024-01-01T00:00:00Z\\\"}\\n\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n\\n        # Override auth dependency to bypass authentication\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n\\n        client = TestClient(app)\\n\\n        response = client.get(\\\"/registration/\\\")  # Fixed: Added /registration prefix\\n\\n        assert response.status_code == 200\\n        data = response.json()\\n        assert data[\\\"email\\\"] == \\\"test@example.com\\\"\\n        assert data[\\\"registered_at\\\"] == \\\"2024-01-01T00:00:00Z\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.load_registration\\\")\\n    async def test_get_registration_not_exists(self, mock_load):\\n        \\\"\\\"\\\"Test getting registration when none exists.\\\"\\\"\\\"\\n        mock_load.return_value = None\\n\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n\\n        # Override auth dependency to bypass authentication\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n\\n        client = TestClient(app)\\n\\n        response = client.get(\\\"/registration/\\\")  # Fixed: Added /registration prefix\\n\\n        assert response.status_code == 200\\n        assert response.json() == {\\\"message\\\": \\\"No user registered\\\"}\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.api.v2.registration.load_registration\\\")\\n    async def test_get_registration_error(self, mock_load):\\n        \\\"\\\"\\\"Test get registration when load fails.\\\"\\\"\\\"\\n        mock_load.side_effect = Exception(\\\"Load failed\\\")\\n\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n\\n        # Override auth dependency to bypass authentication\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n\\n        client = TestClient(app)\\n\\n        response = client.get(\\\"/registration/\\\")  # Fixed: Added /registration prefix\\n\\n        assert response.status_code == 500\\n        assert \\\"Failed to load registration\\\" in response.json()[\\\"detail\\\"]\\n\\n\\nclass TestIntegration:\\n    \\\"\\\"\\\"Integration tests with actual file operations.\\\"\\\"\\\"\\n\\n    def test_full_registration_flow(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Test complete registration flow with actual file operations.\\\"\\\"\\\"\\n        # Set up temporary file path\\n        test_file = tmp_path / \\\"registration.json\\\"\\n        monkeypatch.setattr(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\", test_file)\\n\\n        # Test save and load\\n        assert save_registration(\\\"test@example.com\\\") is True\\n\\n        loaded = load_registration()\\n        assert loaded is not None\\n        assert loaded[\\\"email\\\"] == \\\"test@example.com\\\"\\n        assert \\\"registered_at\\\" in loaded\\n\\n        # Test replacement\\n        assert save_registration(\\\"new@example.com\\\") is True\\n\\n        loaded = load_registration()\\n        assert loaded[\\\"email\\\"] == \\\"new@example.com\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_api_integration(self, tmp_path, monkeypatch):\\n        \\\"\\\"\\\"Test API endpoints with actual file operations.\\\"\\\"\\\"\\n        from fastapi import FastAPI\\n        from fastapi.testclient import TestClient\\n        from langflow.services.auth.utils import get_current_active_user\\n\\n        # Set up temporary file path\\n        test_file = tmp_path / \\\"registration.json\\\"\\n        monkeypatch.setattr(\\\"langflow.api.v2.registration.REGISTRATION_FILE\\\", test_file)\\n\\n        app = FastAPI()\\n        app.include_router(router)\\n\\n        # Override auth dependency to bypass authentication\\n        app.dependency_overrides[get_current_active_user] = lambda: MagicMock()\\n\\n        client = TestClient(app)\\n\\n        # Test registration\\n        response = client.post(\\\"/registration/\\\", json={\\\"email\\\": \\\"integration@example.com\\\"})\\n        assert response.status_code == 200\\n\\n        # Test get registration\\n        response = client.get(\\\"/registration/\\\")\\n        assert response.status_code == 200\\n        assert response.json()[\\\"email\\\"] == \\\"integration@example.com\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/api/v2/test_resume_route.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0a9e6617bd48fecdbe5275e60acbfe91ee82097caa1b6ef2004c738ee8fda1f\",\"content\":\"\\\"\\\"\\\"HTTP resume route (LE-1450): POST /api/v2/workflows/{job_id}/resume.\\n\\nRoute-level tests against a hand-written SUSPENDED job row (the full HTTP\\nround-trip gates on a real pausing flow): owner-or-superuser auth with\\ndeny-to-404, single-use 409, and accepted-resume 200.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.flow.model import Flow\\nfrom langflow.services.database.models.jobs.model import Job, JobEvent, JobStatus, JobType\\nfrom lfx.services.deps import session_scope\\n\\npytestmark = pytest.mark.usefixtures(\\\"client\\\")\\n\\n\\ndef _headers(api_key) -> dict:\\n    return {\\\"x-api-key\\\": api_key.api_key}\\n\\n\\n@pytest.fixture\\nasync def suspended_job(created_api_key):\\n    \\\"\\\"\\\"A hand-written SUSPENDED workflow job owned by the api-key user, with a real flow.\\\"\\\"\\\"\\n    user_id = created_api_key.user_id\\n    flow_id, job_id = uuid4(), uuid4()\\n    request = {\\\"flow_id\\\": str(flow_id), \\\"mode\\\": \\\"background\\\", \\\"stream_protocol\\\": \\\"langflow\\\", \\\"input_value\\\": \\\"hi\\\"}\\n    async with session_scope() as session:\\n        session.add(Flow(id=flow_id, name=f\\\"f-{flow_id}\\\", data={\\\"nodes\\\": [], \\\"edges\\\": []}, user_id=user_id))\\n        session.add(\\n            Job(\\n                job_id=job_id,\\n                flow_id=flow_id,\\n                user_id=user_id,\\n                type=JobType.WORKFLOW,\\n                status=JobStatus.SUSPENDED,\\n                job_metadata={\\\"pending_request_id\\\": \\\"req-1\\\", \\\"request\\\": request},\\n            )\\n        )\\n        await session.flush()\\n    yield job_id\\n    async with session_scope() as session:\\n        job = await session.get(Job, job_id)\\n        if job:\\n            await session.delete(job)\\n        flow = await session.get(Flow, flow_id)\\n        if flow:\\n            await session.delete(flow)\\n\\n\\nasync def test_resume_owner_accepts_200(client, created_api_key, suspended_job):\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n    resp = await client.post(f\\\"api/v2/workflows/{suspended_job}/resume\\\", json=body, headers=_headers(created_api_key))\\n    assert resp.status_code == 200\\n    assert resp.json()[\\\"status\\\"] == \\\"resuming\\\"\\n\\n\\nasync def test_resume_stale_request_id_409(client, created_api_key, suspended_job):\\n    body = {\\\"request_id\\\": \\\"WRONG\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n    resp = await client.post(f\\\"api/v2/workflows/{suspended_job}/resume\\\", json=body, headers=_headers(created_api_key))\\n    assert resp.status_code == 409\\n\\n\\nasync def test_resume_crypto_unavailable_returns_503_and_preserves_suspension(\\n    client,\\n    created_api_key,\\n    suspended_job,\\n):\\n    \\\"\\\"\\\"Unreadable encrypted overrides fail before resume claims or decision writes.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        job = await session.get(Job, suspended_job)\\n        job.job_metadata = {\\n            **(job.job_metadata or {}),\\n            \\\"request_overrides_format\\\": \\\"fernet-json-v1\\\",\\n            \\\"request_overrides\\\": \\\"authenticated-token-unavailable\\\",\\n        }\\n        session.add(job)\\n        await session.flush()\\n\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n    resp = await client.post(f\\\"api/v2/workflows/{suspended_job}/resume\\\", json=body, headers=_headers(created_api_key))\\n\\n    assert resp.status_code == 503, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"REQUEST_OVERRIDES_UNAVAILABLE\\\"\\n    async with session_scope() as session:\\n        job = await session.get(Job, suspended_job)\\n        assert job.status == JobStatus.SUSPENDED\\n    from langflow.services.deps import get_job_service\\n\\n    assert await get_job_service().unconsumed_signals(suspended_job) == []\\n\\n\\nasync def test_resume_unknown_job_404(client, created_api_key):\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {}}\\n    resp = await client.post(f\\\"api/v2/workflows/{uuid4()}/resume\\\", json=body, headers=_headers(created_api_key))\\n    assert resp.status_code == 404\\n\\n\\nasync def test_resume_non_suspended_job_409(client, created_api_key):\\n    \\\"\\\"\\\"A QUEUED (not suspended) job is not resumable \u2192 409.\\\"\\\"\\\"\\n    user_id = created_api_key.user_id\\n    flow_id, job_id = uuid4(), uuid4()\\n    async with session_scope() as session:\\n        session.add(Flow(id=flow_id, name=f\\\"f-{flow_id}\\\", data={\\\"nodes\\\": [], \\\"edges\\\": []}, user_id=user_id))\\n        session.add(\\n            Job(job_id=job_id, flow_id=flow_id, user_id=user_id, type=JobType.WORKFLOW, status=JobStatus.QUEUED)\\n        )\\n        await session.flush()\\n    try:\\n        body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {}}\\n        resp = await client.post(f\\\"api/v2/workflows/{job_id}/resume\\\", json=body, headers=_headers(created_api_key))\\n        assert resp.status_code == 409\\n    finally:\\n        async with session_scope() as session:\\n            for model, key in ((Job, job_id), (Flow, flow_id)):\\n                row = await session.get(model, key)\\n                if row:\\n                    await session.delete(row)\\n\\n\\nasync def test_resume_invalid_job_id_404(client, created_api_key):\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {}}\\n    resp = await client.post(\\\"api/v2/workflows/not-a-uuid/resume\\\", json=body, headers=_headers(created_api_key))\\n    assert resp.status_code == 404\\n\\n\\n@pytest.fixture\\nasync def suspended_job_with_decisions(created_api_key):\\n    \\\"\\\"\\\"A SUSPENDED job whose pending request constrains the choice to approve/reject.\\\"\\\"\\\"\\n    user_id = created_api_key.user_id\\n    flow_id, job_id = uuid4(), uuid4()\\n    request = {\\\"flow_id\\\": str(flow_id), \\\"mode\\\": \\\"background\\\", \\\"stream_protocol\\\": \\\"langflow\\\", \\\"input_value\\\": \\\"hi\\\"}\\n    async with session_scope() as session:\\n        session.add(Flow(id=flow_id, name=f\\\"f-{flow_id}\\\", data={\\\"nodes\\\": [], \\\"edges\\\": []}, user_id=user_id))\\n        session.add(\\n            Job(\\n                job_id=job_id,\\n                flow_id=flow_id,\\n                user_id=user_id,\\n                type=JobType.WORKFLOW,\\n                status=JobStatus.SUSPENDED,\\n                job_metadata={\\\"pending_request_id\\\": \\\"req-1\\\", \\\"request\\\": request},\\n            )\\n        )\\n        session.add(\\n            JobEvent(\\n                job_id=job_id,\\n                seq=1,\\n                event_type=\\\"human_input_required\\\",\\n                payload={\\\"request_id\\\": \\\"req-1\\\", \\\"allowed_decisions\\\": [\\\"approve\\\", \\\"reject\\\"]},\\n            )\\n        )\\n        await session.flush()\\n    yield job_id\\n    async with session_scope() as session:\\n        job = await session.get(Job, job_id)\\n        if job:\\n            await session.delete(job)\\n        flow = await session.get(Flow, flow_id)\\n        if flow:\\n            await session.delete(flow)\\n\\n\\nasync def test_resume_action_id_not_allowed_422(client, created_api_key, suspended_job_with_decisions):\\n    \\\"\\\"\\\"B1: a decision whose action_id is not in allowed_decisions is rejected with 422.\\\"\\\"\\\"\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"delete_everything\\\"}}\\n    resp = await client.post(\\n        f\\\"api/v2/workflows/{suspended_job_with_decisions}/resume\\\", json=body, headers=_headers(created_api_key)\\n    )\\n    assert resp.status_code == 422, resp.text\\n    assert resp.json()[\\\"detail\\\"][\\\"code\\\"] == \\\"INVALID_DECISION\\\"\\n\\n\\nasync def test_resume_allowed_action_id_accepted_200(client, created_api_key, suspended_job_with_decisions):\\n    \\\"\\\"\\\"B1: a decision whose action_id is in allowed_decisions passes validation.\\\"\\\"\\\"\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n    resp = await client.post(\\n        f\\\"api/v2/workflows/{suspended_job_with_decisions}/resume\\\", json=body, headers=_headers(created_api_key)\\n    )\\n    assert resp.status_code == 200, resp.text\\n\\n\\nasync def test_mark_card_answered_is_noop_without_card_message(client):  # noqa: ARG001\\n    \\\"\\\"\\\"mark_card_answered degrades gracefully when no card message id is recorded.\\\"\\\"\\\"\\n    from langflow.api.v2.hitl import mark_card_answered\\n\\n    # Unknown job \u2192 no job_metadata.card_message_id \u2192 returns without raising.\\n    await mark_card_answered(uuid4(), \\\"req-1\\\", {\\\"action_id\\\": \\\"approve\\\"})\\n\\n\\nasync def test_resume_reenforces_flow_execute_permission(client, created_api_key, suspended_job, monkeypatch):\\n    \\\"\\\"\\\"Resume executes the rest of the flow, so flow:execute is re-checked at resume time.\\n\\n    Job ownership alone must not be enough: shared access revoked while the run was\\n    suspended (a plugin-enforced deny) has to block the decision and keep the job SUSPENDED.\\n    \\\"\\\"\\\"\\n    import langflow.services.authorization as authz\\n    from fastapi import HTTPException\\n\\n    async def _deny(*_args, **_kwargs):\\n        raise HTTPException(status_code=403, detail=\\\"flow:execute denied\\\")\\n\\n    monkeypatch.setattr(authz, \\\"ensure_flow_permission\\\", _deny)\\n    body = {\\\"request_id\\\": \\\"req-1\\\", \\\"decision\\\": {\\\"action_id\\\": \\\"approve\\\"}}\\n    resp = await client.post(f\\\"api/v2/workflows/{suspended_job}/resume\\\", json=body, headers=_headers(created_api_key))\\n    assert resp.status_code == 403, resp.text\\n    async with session_scope() as session:\\n        job = await session.get(Job, suspended_job)\\n        assert job.status == JobStatus.SUSPENDED\\n\\n\\ndef _card_row(flow_id, request_id: str):\\n    from langflow.services.database.models.message.model import MessageTable\\n\\n    return MessageTable(\\n        flow_id=flow_id,\\n        session_id=\\\"sess-cards\\\",\\n        sender=\\\"Machine\\\",\\n        sender_name=\\\"AI\\\",\\n        text=\\\"\\\",\\n        files=[],\\n        category=\\\"message\\\",\\n        content_blocks=[\\n            {\\n                \\\"title\\\": \\\"Human input required\\\",\\n                \\\"contents\\\": [{\\\"type\\\": \\\"human_input\\\", \\\"request_id\\\": request_id, \\\"options\\\": []}],\\n            }\\n        ],\\n    )\\n\\n\\nasync def test_mark_card_answered_stamps_snapshot_card_not_next_pause(client, created_api_key):  # noqa: ARG001\\n    \\\"\\\"\\\"The decision stamps the card captured before resume, never a later pause's card.\\n\\n    Simulates the race: the continuation already reached a second pause and overwrote\\n    job_metadata.card_message_id, but the caller passes the pre-resume snapshot id.\\n    \\\"\\\"\\\"\\n    from langflow.api.v2.hitl import mark_card_answered\\n    from langflow.services.database.models.message.model import MessageTable\\n\\n    user_id = created_api_key.user_id\\n    flow_id, job_id = uuid4(), uuid4()\\n    first_card, second_card = _card_row(flow_id, \\\"req-1\\\"), _card_row(flow_id, \\\"req-2\\\")\\n    async with session_scope() as session:\\n        session.add(Flow(id=flow_id, name=f\\\"f-{flow_id}\\\", data={\\\"nodes\\\": [], \\\"edges\\\": []}, user_id=user_id))\\n        session.add(first_card)\\n        session.add(second_card)\\n        await session.flush()\\n        first_id, second_id = first_card.id, second_card.id\\n        session.add(\\n            Job(\\n                job_id=job_id,\\n                flow_id=flow_id,\\n                user_id=user_id,\\n                type=JobType.WORKFLOW,\\n                status=JobStatus.SUSPENDED,\\n                job_metadata={\\\"card_message_id\\\": str(second_id)},\\n            )\\n        )\\n        await session.flush()\\n    try:\\n        await mark_card_answered(job_id, \\\"req-1\\\", {\\\"action_id\\\": \\\"approve\\\"}, card_message_id=str(first_id))\\n        async with session_scope() as session:\\n            first = await session.get(MessageTable, first_id)\\n            second = await session.get(MessageTable, second_id)\\n            assert first.content_blocks[0][\\\"contents\\\"][0][\\\"submitted_action\\\"] == \\\"approve\\\"\\n            assert \\\"submitted_action\\\" not in second.content_blocks[0][\\\"contents\\\"][0]\\n    finally:\\n        async with session_scope() as session:\\n            for model, key in ((Job, job_id), (MessageTable, first_id), (MessageTable, second_id), (Flow, flow_id)):\\n                row = await session.get(model, key)\\n                if row:\\n                    await session.delete(row)\\n\\n\\nasync def test_mark_card_answered_skips_card_of_a_different_request(client, created_api_key):  # noqa: ARG001\\n    \\\"\\\"\\\"Even a stale card_message_id cannot stamp a card whose request_id differs.\\\"\\\"\\\"\\n    from langflow.api.v2.hitl import mark_card_answered\\n    from langflow.services.database.models.message.model import MessageTable\\n\\n    user_id = created_api_key.user_id\\n    flow_id = uuid4()\\n    other_card = _card_row(flow_id, \\\"req-2\\\")\\n    async with session_scope() as session:\\n        session.add(Flow(id=flow_id, name=f\\\"f-{flow_id}\\\", data={\\\"nodes\\\": [], \\\"edges\\\": []}, user_id=user_id))\\n        session.add(other_card)\\n        await session.flush()\\n        other_id = other_card.id\\n    try:\\n        await mark_card_answered(uuid4(), \\\"req-1\\\", {\\\"action_id\\\": \\\"approve\\\"}, card_message_id=str(other_id))\\n        async with session_scope() as session:\\n            other = await session.get(MessageTable, other_id)\\n            assert \\\"submitted_action\\\" not in other.content_blocks[0][\\\"contents\\\"][0]\\n    finally:\\n        async with session_scope() as session:\\n            for model, key in ((MessageTable, other_id), (Flow, flow_id)):\\n                row = await session.get(model, key)\\n                if row:\\n                    await session.delete(row)\\n\\n\\nasync def test_list_pending_returns_suspended_hitl(client, created_api_key):\\n    \\\"\\\"\\\"GET /workflows/pending surfaces a SUSPENDED HITL job + its pending request.\\\"\\\"\\\"\\n    from sqlmodel import select\\n\\n    user_id = created_api_key.user_id\\n    flow_id, job_id = uuid4(), uuid4()\\n    request = {\\\"flow_id\\\": str(flow_id), \\\"session_id\\\": \\\"sess-pending\\\", \\\"input_value\\\": \\\"hi\\\"}\\n    async with session_scope() as session:\\n        session.add(Flow(id=flow_id, name=f\\\"f-{flow_id}\\\", data={\\\"nodes\\\": [], \\\"edges\\\": []}, user_id=user_id))\\n        session.add(\\n            Job(\\n                job_id=job_id,\\n                flow_id=flow_id,\\n                user_id=user_id,\\n                type=JobType.WORKFLOW,\\n                status=JobStatus.SUSPENDED,\\n                job_metadata={\\\"pending_request_id\\\": \\\"req-1\\\", \\\"request\\\": request},\\n            )\\n        )\\n        session.add(\\n            JobEvent(\\n                job_id=job_id,\\n                seq=1,\\n                event_type=\\\"human_input_required\\\",\\n                payload={\\n                    \\\"request_id\\\": \\\"req-1\\\",\\n                    \\\"prompt\\\": \\\"Approve?\\\",\\n                    \\\"kind\\\": \\\"tool_approval\\\",\\n                    \\\"options\\\": [{\\\"action_id\\\": \\\"approve\\\", \\\"label\\\": \\\"Approve\\\"}],\\n                    \\\"allowed_decisions\\\": [\\\"approve\\\", \\\"reject\\\"],\\n                },\\n            )\\n        )\\n        await session.flush()\\n    try:\\n        resp = await client.get(f\\\"api/v2/workflows/pending?flow_id={flow_id}\\\", headers=_headers(created_api_key))\\n        assert resp.status_code == 200, resp.text\\n        data = resp.json()\\n        assert len(data) == 1\\n        item = data[0]\\n        assert item[\\\"job_id\\\"] == str(job_id)\\n        assert item[\\\"session_id\\\"] == \\\"sess-pending\\\"\\n        assert item[\\\"request_id\\\"] == \\\"req-1\\\"\\n        assert item[\\\"prompt\\\"] == \\\"Approve?\\\"\\n        assert item[\\\"allowed_decisions\\\"] == [\\\"approve\\\", \\\"reject\\\"]\\n    finally:\\n        async with session_scope() as session:\\n            events = (await session.exec(select(JobEvent).where(JobEvent.job_id == job_id))).all()\\n            for event in events:\\n                await session.delete(event)\\n            for model, key in ((Job, job_id), (Flow, flow_id)):\\n                row = await session.get(model, key)\\n                if row:\\n                    await session.delete(row)\\n\\n\\nclass TestRerouteDecisionOnTimeout:\\n    \\\"\\\"\\\"Lazy timeout reroute (no watchdog): a late decision goes to fallback only if defined.\\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _pending(*, seconds_ago: float, timeout_s: int, fallback: str | None):\\n        from datetime import datetime, timedelta, timezone\\n\\n        paused_at = (datetime.now(timezone.utc) - timedelta(seconds=seconds_ago)).isoformat()\\n        return {\\\"timeout_seconds\\\": timeout_s, \\\"fallback_action\\\": fallback, \\\"paused_at\\\": paused_at}\\n\\n    def test_late_decision_reroutes_to_fallback(self):\\n        from langflow.api.v2.hitl import reroute_decision_on_timeout\\n\\n        pending = self._pending(seconds_ago=120, timeout_s=60, fallback=\\\"fallback\\\")\\n        result = reroute_decision_on_timeout(pending, {\\\"action_id\\\": \\\"approve\\\", \\\"values\\\": {}})\\n        assert result[\\\"action_id\\\"] == \\\"fallback\\\"\\n        assert result[\\\"values\\\"] == {}\\n\\n    def test_within_deadline_keeps_decision(self):\\n        from langflow.api.v2.hitl import reroute_decision_on_timeout\\n\\n        pending = self._pending(seconds_ago=5, timeout_s=60, fallback=\\\"fallback\\\")\\n        assert reroute_decision_on_timeout(pending, {\\\"action_id\\\": \\\"approve\\\"})[\\\"action_id\\\"] == \\\"approve\\\"\\n\\n    def test_late_but_no_fallback_expires_decision(self):\\n        \\\"\\\"\\\"A late answer with no fallback expires to a sentinel so no branch is taken.\\\"\\\"\\\"\\n        from langflow.api.v2.hitl import reroute_decision_on_timeout\\n        from lfx.run.hitl import EXPIRED_ACTION\\n\\n        pending = self._pending(seconds_ago=120, timeout_s=60, fallback=None)\\n        assert reroute_decision_on_timeout(pending, {\\\"action_id\\\": \\\"approve\\\"})[\\\"action_id\\\"] == EXPIRED_ACTION\\n\\n    def test_no_timeout_keeps_decision(self):\\n        from langflow.api.v2.hitl import reroute_decision_on_timeout\\n\\n        pending = self._pending(seconds_ago=120, timeout_s=0, fallback=\\\"fallback\\\")\\n        assert reroute_decision_on_timeout(pending, {\\\"action_id\\\": \\\"approve\\\"})[\\\"action_id\\\"] == \\\"approve\\\"\\n\\n\\nclass TestUnwrapPausePayload:\\n    \\\"\\\"\\\"The stored pause payload is the wire frame; consumers need the raw request unwrapped.\\\"\\\"\\\"\\n\\n    def test_flat_payload_passthrough(self):\\n        from langflow.services.jobs.service import _unwrap_pause_payload\\n\\n        flat = {\\\"request_id\\\": \\\"r\\\", \\\"timeout_seconds\\\": 60, \\\"allowed_decisions\\\": [\\\"approve\\\"]}\\n        assert _unwrap_pause_payload(flat) is flat\\n\\n    def test_langflow_envelope_unwrapped(self):\\n        from langflow.services.jobs.service import _unwrap_pause_payload\\n\\n        raw = {\\\"request_id\\\": \\\"r\\\", \\\"timeout_seconds\\\": 60, \\\"fallback_action\\\": \\\"fallback\\\"}\\n        wrapped = {\\\"event\\\": \\\"human_input_required\\\", \\\"data\\\": raw}\\n        assert _unwrap_pause_payload(wrapped) == raw\\n\\n    def test_agui_custom_event_unwrapped(self):\\n        from langflow.services.jobs.service import _unwrap_pause_payload\\n\\n        raw = {\\\"request_id\\\": \\\"r\\\", \\\"timeout_seconds\\\": 60, \\\"fallback_action\\\": \\\"fallback\\\"}\\n        wrapped = {\\\"type\\\": \\\"CUSTOM\\\", \\\"name\\\": \\\"langflow.human_input_required\\\", \\\"value\\\": raw}\\n        assert _unwrap_pause_payload(wrapped) == raw\\n\\n    def test_reroute_reads_timeout_through_agui_envelope(self):\\n        \\\"\\\"\\\"End-to-end: a wrapped AG-UI payload (what production stores) still triggers reroute.\\\"\\\"\\\"\\n        from datetime import datetime, timedelta, timezone\\n\\n        from langflow.api.v2.hitl import reroute_decision_on_timeout\\n        from langflow.services.jobs.service import _unwrap_pause_payload\\n\\n        paused_at = (datetime.now(timezone.utc) - timedelta(seconds=120)).isoformat()\\n        raw = {\\\"request_id\\\": \\\"r\\\", \\\"timeout_seconds\\\": 60, \\\"fallback_action\\\": \\\"fallback\\\", \\\"paused_at\\\": paused_at}\\n        stored = {\\\"type\\\": \\\"CUSTOM\\\", \\\"name\\\": \\\"langflow.human_input_required\\\", \\\"value\\\": raw}\\n        pending = _unwrap_pause_payload(stored)\\n        assert reroute_decision_on_timeout(pending, {\\\"action_id\\\": \\\"approve\\\"})[\\\"action_id\\\"] == \\\"fallback\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/_side_effect_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"837aa0ebc10fbeb02458b44cf99438bcb8a19fb8c0e829f1c83581118fc85baa\",\"content\":\"\\\"\\\"\\\"A REAL Langflow component with one observable side effect, in a real module.\\n\\nCustom components need importable source (``inspect.getsource``), so this lives\\nin a module file rather than being defined inline in a test. ``increment`` bumps\\na process-global counter keyed by ``effect_key`` each time the component builds.\\nThe side-effect-safety proof reads the counter to assert at-most-once (counter\\nstays 1 after a crash + restart that does NOT re-run) vs requeue (counter hits 2).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport threading\\n\\nfrom lfx.custom import Component\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema.message import Message\\n\\n_LOCK = threading.Lock()\\nSIDE_EFFECTS: dict[str, int] = {}\\n\\n\\ndef reset_side_effects() -> None:\\n    with _LOCK:\\n        SIDE_EFFECTS.clear()\\n\\n\\ndef side_effect_count(key: str) -> int:\\n    with _LOCK:\\n        return SIDE_EFFECTS.get(key, 0)\\n\\n\\nclass SideEffectComponent(Component):\\n    \\\"\\\"\\\"Increments an observable counter exactly once per build.\\\"\\\"\\\"\\n\\n    display_name = \\\"Side Effect\\\"\\n    description = \\\"Increments an observable counter exactly once per build.\\\"\\n    icon = \\\"activity\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"effect_key\\\", display_name=\\\"Effect Key\\\"),\\n        MessageTextInput(name=\\\"input_value\\\", display_name=\\\"Input\\\"),\\n    ]\\n    outputs = [Output(display_name=\\\"Output\\\", name=\\\"output\\\", method=\\\"increment\\\")]\\n\\n    def increment(self) -> Message:\\n        key = self.effect_key\\n        with _LOCK:\\n            SIDE_EFFECTS[key] = SIDE_EFFECTS.get(key, 0) + 1\\n            count = SIDE_EFFECTS[key]\\n        return Message(text=f\\\"{key}:{count}\\\")\\n\\n\\ndef build_side_effect_graph(effect_key: str):\\n    \\\"\\\"\\\"A real connected graph: ChatInput -> SideEffect -> ChatOutput.\\\"\\\"\\\"\\n    from lfx.components.input_output import ChatInput, ChatOutput\\n    from lfx.graph import Graph\\n\\n    chat_input = ChatInput(_id=\\\"ChatInput-se\\\")\\n    chat_input.set(input_value=\\\"go\\\")\\n    effect = SideEffectComponent(_id=\\\"SideEffect-se\\\")\\n    effect.set(effect_key=effect_key, input_value=chat_input.message_response)\\n    chat_output = ChatOutput(_id=\\\"ChatOutput-se\\\")\\n    chat_output.set(input_value=effect.increment)\\n    return Graph(start=chat_input, end=chat_output)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ec9ab86f394cfebe310d997794a0f6df77fc9c549b0495a103419ad4c78cf98d\",\"content\":\"\\\"\\\"\\\"Real-instance fixtures for the background-execution real-service tier.\\n\\nThese fixtures back ``@pytest.mark.real_services`` tests with REAL engines, never\\nfakes:\\n\\n- ``real_services_db_url`` parametrizes over real SQLite (always) and real Postgres\\n  (only when ``LANGFLOW_TEST_DATABASE_URI`` is set; CI always sets it).\\n- ``real_services_redis_url`` yields a real Redis URL from ``LANGFLOW_TEST_REDIS_URL``\\n  (skips when unset), flushed clean before and after each test.\\n- ``real_services_job_service`` runs the real Alembic migrations against\\n  ``real_services_db_url`` and binds ``session_scope()`` to it, so store methods are\\n  exercised on both real SQLite and real Postgres.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport contextlib\\nimport os\\nimport tempfile\\nfrom pathlib import Path\\nfrom typing import TYPE_CHECKING\\n\\nimport pytest\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncGenerator\\n\\n    from langflow.services.jobs.service import JobService\\n\\n\\ndef _async_pg_url(raw: str) -> str:\\n    \\\"\\\"\\\"Normalize a Postgres URL to the async psycopg dialect.\\n\\n    psycopg (v3) is what ``--extra postgresql`` installs and what\\n    ``DatabaseService`` picks for async Postgres, so the harness exercises the\\n    same driver production does. A bare ``postgresql://`` would otherwise\\n    default to asyncpg, which is not a dependency of this project.\\n    \\\"\\\"\\\"\\n    if \\\"+asyncpg\\\" in raw or \\\"+psycopg\\\" in raw:\\n        return raw\\n    if raw.startswith(\\\"postgresql://\\\"):\\n        return raw.replace(\\\"postgresql://\\\", \\\"postgresql+psycopg://\\\", 1)\\n    if raw.startswith(\\\"postgres://\\\"):\\n        return raw.replace(\\\"postgres://\\\", \\\"postgresql+psycopg://\\\", 1)\\n    return raw\\n\\n\\n@pytest.fixture(params=[\\\"sqlite\\\", \\\"postgres\\\"])\\nasync def real_services_db_url(request: pytest.FixtureRequest) -> AsyncGenerator[str, None]:\\n    \\\"\\\"\\\"Yield a real, connectable async DB URL.\\n\\n    - sqlite: a real temp-file SQLite database (always runs).\\n    - postgres: the database behind ``LANGFLOW_TEST_DATABASE_URI`` normalized to\\n      the async psycopg dialect; skipped when the env var is unset (CI always sets it).\\n    \\\"\\\"\\\"\\n    if request.param == \\\"sqlite\\\":\\n        with tempfile.NamedTemporaryFile(suffix=\\\".db\\\", delete=False) as tmp:\\n            db_path = tmp.name\\n        try:\\n            yield f\\\"sqlite+aiosqlite:///{db_path}\\\"\\n        finally:\\n            for suffix in (\\\"\\\", \\\"-wal\\\", \\\"-shm\\\", \\\"-journal\\\"):\\n                Path(db_path + suffix).unlink(missing_ok=True)\\n    else:\\n        raw = os.environ.get(\\\"LANGFLOW_TEST_DATABASE_URI\\\")\\n        if not raw:\\n            pytest.skip(\\\"LANGFLOW_TEST_DATABASE_URI not set\\\")\\n        yield _async_pg_url(raw)\\n\\n\\n@pytest.fixture\\nasync def real_services_job_service(real_services_db_url: str) -> AsyncGenerator[JobService, None]:\\n    \\\"\\\"\\\"Yield a JobService whose ``session_scope()`` is bound to a real, migrated DB.\\n\\n    Runs the real Alembic migrations against ``real_services_db_url`` (sqlite + postgres)\\n    through the production ``DatabaseService`` path, then swaps that service into the\\n    service manager so ``JobService``'s ``session_scope()`` resolves to it. This proves\\n    the store methods on BOTH real SQLite and real Postgres, and that the migrations\\n    themselves apply on both engines.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.factory import DatabaseServiceFactory\\n    from langflow.services.deps import get_settings_service\\n    from langflow.services.jobs.service import JobService\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n\\n    manager = get_service_manager()\\n    settings_service = get_settings_service()\\n    original_url = settings_service.settings.database_url\\n    original_db_service = manager.services.pop(ServiceType.DATABASE_SERVICE, None)\\n\\n    settings_service.settings.database_url = real_services_db_url\\n    db_service = DatabaseServiceFactory().create(settings_service)\\n    manager.services[ServiceType.DATABASE_SERVICE] = db_service\\n\\n    try:\\n        await db_service.run_migrations()\\n        yield JobService()\\n    finally:\\n        manager.services.pop(ServiceType.DATABASE_SERVICE, None)\\n        with contextlib.suppress(Exception):\\n            await db_service.teardown()\\n        settings_service.settings.database_url = original_url\\n        if original_db_service is not None:\\n            manager.services[ServiceType.DATABASE_SERVICE] = original_db_service\\n\\n\\n@pytest.fixture\\nasync def real_services_redis_url() -> AsyncGenerator[str, None]:\\n    \\\"\\\"\\\"Yield a real Redis URL from ``LANGFLOW_TEST_REDIS_URL``, flushed clean.\\n\\n    Skips when ``LANGFLOW_TEST_REDIS_URL`` is unset (CI sets it via the redis:7\\n    service). Uses the same ``redis.asyncio`` client ``RedisJobQueueService`` uses,\\n    so this exercises the real driver, not fakeredis.\\n    \\\"\\\"\\\"\\n    url = os.environ.get(\\\"LANGFLOW_TEST_REDIS_URL\\\")\\n    if not url:\\n        pytest.skip(\\\"LANGFLOW_TEST_REDIS_URL not set\\\")\\n\\n    from redis.asyncio import StrictRedis\\n\\n    client = StrictRedis.from_url(url)\\n    try:\\n        await client.flushdb()\\n        yield url\\n    finally:\\n        with contextlib.suppress(Exception):\\n            await client.flushdb()\\n        await client.aclose()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_agui_replay_byte_identical.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0954439cfb8590b933752d674f1dffaf592545ee29f6d371553429093c5cf3cb\",\"content\":\"\\\"\\\"\\\"AG-UI durable replay must be byte-identical to the live frame.\\n\\nThe AG-UI live path serializes each event with pydantic ``model_dump_json`` \u2014\\ncompact separators (``{\\\"type\\\":\\\"RUN_STARTED\\\",...}``). The durable replay re-frames\\nthe persisted payload dict; if it used Python's default ``json.dumps`` (spaced\\nseparators ``{\\\"type\\\": \\\"RUN_STARTED\\\", ...}``) the replayed bytes would differ from\\nlive, contradicting the byte-compatible reattach claim. This drives the REAL\\nAG-UI adapter to produce a live frame, persists the same payload the runner would\\n(parsed dict), and asserts the facade's replay bytes equal the live bytes for the\\nagui protocol \u2014 and that langflow stays byte-identical too (spaced separators).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\n\\nimport pytest\\nfrom fastapi.sse import format_sse_event\\nfrom langflow.services.background_execution.service import BackgroundExecutionService\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\npytestmark = pytest.mark.real_services\\n\\n\\ndef _live_agui_run_started_bytes(seq: int) -> bytes:\\n    adapter = get_stream_adapter(\\\"agui\\\", StreamAdapterContext(run_id=\\\"r1\\\", thread_id=\\\"t1\\\"))\\n    events = list(adapter.initial_events())\\n    # RUN_STARTED is the first initial event.\\n    run_started = events[0]\\n    return format_sse_event(data_str=run_started.data_json, id=str(seq))\\n\\n\\ndef _row(seq: int, payload: dict):\\n    return type(\\\"JobEvent\\\", (), {\\\"seq\\\": seq, \\\"payload\\\": payload})()\\n\\n\\ndef test_agui_replay_bytes_equal_live_bytes():\\n    \\\"\\\"\\\"The agui replay frame equals the live frame byte-for-byte.\\\"\\\"\\\"\\n    seq = 1\\n    live = _live_agui_run_started_bytes(seq)\\n\\n    # The runner persists the parsed dict (json.loads of the live data_json).\\n    live_data_json = live.decode(\\\"utf-8\\\").split(\\\"data: \\\", 1)[1].split(\\\"\\\\n\\\", 1)[0]\\n    persisted_payload = json.loads(live_data_json)\\n\\n    replay = BackgroundExecutionService._row_to_frame(_row(seq, persisted_payload), protocol=\\\"agui\\\")\\n    assert replay == live, f\\\"agui replay not byte-identical:\\\\n live  ={live!r}\\\\n replay={replay!r}\\\"\\n\\n\\ndef test_langflow_replay_bytes_equal_live_bytes():\\n    \\\"\\\"\\\"The langflow replay frame stays byte-identical (spaced separators).\\\"\\\"\\\"\\n    seq = 3\\n    payload = {\\\"event\\\": \\\"build_start\\\", \\\"data\\\": {\\\"id\\\": \\\"n1\\\"}}\\n    live = format_sse_event(data_str=json.dumps(payload, default=str), id=str(seq))\\n\\n    persisted_payload = json.loads(json.dumps(payload, default=str))\\n    replay = BackgroundExecutionService._row_to_frame(_row(seq, persisted_payload), protocol=\\\"langflow\\\")\\n    assert replay == live, f\\\"langflow replay not byte-identical:\\\\n live  ={live!r}\\\\n replay={replay!r}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_bounded_concurrency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3a4219174f157e4c8e85eec654db8ccdbe68ee149e5396addc5b6433f9291c7c\",\"content\":\"\\\"\\\"\\\"BOUNDED-CONCURRENCY real service.\\n\\nSubmit N+k jobs to the real ``InProcessExecutor`` configured for max concurrency\\nN. A barrier holds every started job so the peak in-flight count is observable;\\nthe executor must never run more than N at once, the extra k stay queued, and the\\nwhole backlog drains to completion once the barrier releases. Every wait is\\nbounded so a regression fails loudly.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport threading\\n\\nimport pytest\\nfrom langflow.services.background_execution.executor import InProcessExecutor\\n\\npytestmark = pytest.mark.real_services\\n\\n\\nclass _Probe:\\n    def __init__(self) -> None:\\n        self._lock = threading.Lock()\\n        self.current = 0\\n        self.peak = 0\\n        self.completed = 0\\n\\n    def enter(self) -> None:\\n        with self._lock:\\n            self.current += 1\\n            self.peak = max(self.peak, self.current)\\n\\n    def exit(self, *, completed: bool) -> None:\\n        with self._lock:\\n            self.current -= 1\\n            if completed:\\n                self.completed += 1\\n\\n\\nasync def test_executor_never_exceeds_max_concurrency_and_drains():\\n    \\\"\\\"\\\"N+k submitted at cap N: peak == N, k wait, then the whole backlog drains.\\\"\\\"\\\"\\n    n = 3\\n    k = 2\\n    probe = _Probe()\\n    release = asyncio.Event()\\n\\n    async def _slow_job() -> None:\\n        probe.enter()\\n        completed = False\\n        try:\\n            # Hold the slot until the test confirms the cap, so the peak is real.\\n            await asyncio.wait_for(release.wait(), timeout=10)\\n            completed = True\\n        finally:\\n            probe.exit(completed=completed)\\n\\n    executor = InProcessExecutor(max_concurrency=n)\\n    await executor.start()\\n    try:\\n        for i in range(n + k):\\n            await executor.submit(f\\\"job-{i}\\\", _slow_job)\\n\\n        # Let the pool saturate. Peak must reach exactly N, never N+1. Bounded\\n        # poll (a fixed iteration budget, not an open-ended wait) so a regression\\n        # fails loudly instead of hanging.\\n        for _ in range(500):  # ~5s budget\\n            if probe.current >= n:\\n                break\\n            await asyncio.sleep(0.01)\\n        await asyncio.sleep(0.3)  # would expose any over-admission\\n        assert probe.peak == n, f\\\"executor ran {probe.peak} concurrently, cap was {n}\\\"\\n        assert probe.current == n, f\\\"{probe.current} in-flight, expected exactly the cap {n}\\\"\\n\\n        # Release: the backlog of k waiting jobs drains and everything finishes.\\n        release.set()\\n\\n        for _ in range(500):  # ~10s budget\\n            if probe.completed >= n + k:\\n                break\\n            await asyncio.sleep(0.02)\\n        assert probe.completed == n + k, f\\\"only {probe.completed}/{n + k} jobs drained\\\"\\n        # The cap held across the whole run, even as the backlog drained.\\n        assert probe.peak == n, f\\\"cap breached during drain: peak={probe.peak}\\\"\\n        print(  # noqa: T201\\n            f\\\"PROOF[concurrency]: submitted {n + k} at cap {n} -> peak in-flight={probe.peak} \\\"\\n            f\\\"(never {n + 1}); all {probe.completed} drained after the barrier released\\\"\\n        )\\n    finally:\\n        release.set()\\n        await executor.stop()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_durable_checkpoint_store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"43e15a9ebb8ed52e658426d062d076a93de582e84a012d809ac67b49903ea73f\",\"content\":\"\\\"\\\"\\\"Durable checkpoint persistence (LE-1441) against REAL SQLite and REAL Postgres.\\n\\nSlice 1 \u2014 the encoding-agnostic ``JobService`` checkpoint helper. The blob is\\nalready-serialized text the helper never parses, so a graph-kind (JSON) and an\\nagent-kind (base64) payload both round-trip byte-for-byte through the same API.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timedelta, timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom lfx.graph.checkpoint.schema import GraphCheckpoint\\nfrom lfx.graph.checkpoint.store import CheckpointStore\\n\\n\\ndef _checkpoint(job_id, *, run_id=None, session_id=\\\"sess-1\\\", **overrides) -> GraphCheckpoint:\\n    base = {\\n        \\\"run_id\\\": run_id or str(job_id),\\n        \\\"flow_id\\\": \\\"flow-1\\\",\\n        \\\"session_id\\\": session_id,\\n        \\\"job_id\\\": str(job_id),\\n        \\\"flow_payload\\\": {\\\"nodes\\\": [], \\\"edges\\\": []},\\n        \\\"vertices_to_run\\\": {\\\"a\\\", \\\"b\\\"},\\n        \\\"ran_at_least_once\\\": {\\\"a\\\"},\\n    }\\n    base.update(overrides)\\n    return GraphCheckpoint(**base)\\n\\n\\nasync def _new_job(service):\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    return job_id\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_save_and_load_checkpoint_round_trips_opaque_blob(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    blob = '{\\\"checkpoint_id\\\": \\\"abc\\\", \\\"run_id\\\": \\\"r1\\\"}'\\n    await service.save_checkpoint(job_id, \\\"graph\\\", blob)\\n\\n    assert await service.load_checkpoint(job_id, \\\"graph\\\") == blob\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_load_checkpoint_returns_none_when_absent(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.load_checkpoint(job_id, \\\"graph\\\") is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_save_checkpoint_upserts_single_row_per_kind(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.save_checkpoint(job_id, \\\"graph\\\", \\\"first\\\")\\n    await service.save_checkpoint(job_id, \\\"graph\\\", \\\"second\\\")\\n\\n    assert await service.load_checkpoint(job_id, \\\"graph\\\") == \\\"second\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_concurrent_first_save_does_not_raise_integrity_error(real_services_job_service) -> None:\\n    \\\"\\\"\\\"Racing savers of the first checkpoint must not hit UNIQUE \u2014 the loser retries into update.\\\"\\\"\\\"\\n    import asyncio\\n\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await asyncio.gather(*[service.save_checkpoint(job_id, \\\"graph\\\", f\\\"blob-{i}\\\") for i in range(8)])\\n\\n    assert (await service.load_checkpoint(job_id, \\\"graph\\\")).startswith(\\\"blob-\\\")\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_kinds_are_isolated_per_job(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    graph_blob = '{\\\"kind\\\": \\\"graph\\\"}'\\n    agent_blob = \\\"gqFhAaFiAg==\\\"  # stand-in for base64(msgpack) \u2014 raw bytes can't sit in JSON\\n\\n    await service.save_checkpoint(job_id, \\\"graph\\\", graph_blob)\\n    await service.save_checkpoint(job_id, \\\"agent\\\", agent_blob)\\n\\n    assert await service.load_checkpoint(job_id, \\\"graph\\\") == graph_blob\\n    assert await service.load_checkpoint(job_id, \\\"agent\\\") == agent_blob\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_delete_checkpoint_removes_row(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.save_checkpoint(job_id, \\\"graph\\\", \\\"blob\\\")\\n    await service.delete_checkpoint(job_id, \\\"graph\\\")\\n\\n    assert await service.load_checkpoint(job_id, \\\"graph\\\") is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_delete_checkpoint_is_noop_when_absent(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.delete_checkpoint(job_id, \\\"graph\\\")  # must not raise\\n\\n    assert await service.load_checkpoint(job_id, \\\"graph\\\") is None\\n\\n\\ndef _store(job_service):\\n    from langflow.services.checkpoint.store import JobScopedCheckpointStore\\n\\n    return JobScopedCheckpointStore(job_service)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\ndef test_durable_store_is_a_checkpoint_store() -> None:\\n    from langflow.services.checkpoint.store import JobScopedCheckpointStore\\n\\n    assert issubclass(JobScopedCheckpointStore, CheckpointStore)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_save_then_load_by_run_id_returns_same_checkpoint(real_services_job_service) -> None:\\n    store = _store(real_services_job_service)\\n    job_id = await _new_job(real_services_job_service)\\n    cp = _checkpoint(job_id)\\n\\n    await store.save(cp)\\n    loaded = await store.load_by_run_id(str(job_id))\\n\\n    assert loaded is not None\\n    assert loaded.checkpoint_id == cp.checkpoint_id\\n    assert loaded.run_id == cp.run_id\\n    assert loaded.vertices_to_run == {\\\"a\\\", \\\"b\\\"}  # set field survives JSON round-trip\\n    assert loaded.ran_at_least_once == {\\\"a\\\"}\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_scan_based_lookups_raise_not_implemented(real_services_job_service) -> None:\\n    # The durable store is job-scoped; load/delete by checkpoint id and list_by_session would scan\\n    # across all jobs/users. They fail loud so a future caller can't trigger a silent cross-user scan.\\n    store = _store(real_services_job_service)\\n    with pytest.raises(NotImplementedError):\\n        await store.load(\\\"any-checkpoint-id\\\")\\n    with pytest.raises(NotImplementedError):\\n        await store.delete(\\\"any-checkpoint-id\\\")\\n    with pytest.raises(NotImplementedError):\\n        await store.list_by_session(\\\"any-session\\\")\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_load_by_run_id_returns_latest_save(real_services_job_service) -> None:\\n    store = _store(real_services_job_service)\\n    job_id = await _new_job(real_services_job_service)\\n    first = _checkpoint(job_id, call_order=[\\\"v1\\\"])\\n    second = _checkpoint(job_id, call_order=[\\\"v1\\\", \\\"v2\\\"])\\n\\n    await store.save(first)\\n    await store.save(second)\\n\\n    loaded = await store.load_by_run_id(str(job_id))\\n    assert loaded is not None\\n    assert loaded.call_order == [\\\"v1\\\", \\\"v2\\\"]\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_load_by_run_id_missing_returns_none(real_services_job_service) -> None:\\n    store = _store(real_services_job_service)\\n    assert await store.load_by_run_id(\\\"ghost\\\") is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_load_by_run_id_honors_expiry(real_services_job_service) -> None:\\n    store = _store(real_services_job_service)\\n    job_id = await _new_job(real_services_job_service)\\n    cp = _checkpoint(job_id, expires_at=datetime.now(timezone.utc) - timedelta(seconds=1))\\n\\n    await store.save(cp)\\n\\n    assert await store.load_by_run_id(str(job_id)) is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_checkpoint_survives_a_fresh_store_on_same_db(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A second store + JobService on the SAME DB returns the saved checkpoint field-for-field.\\\"\\\"\\\"\\n    from langflow.services.jobs.service import JobService\\n\\n    store_1 = _store(real_services_job_service)\\n    job_id = await _new_job(real_services_job_service)\\n    cp = _checkpoint(job_id, run_map={\\\"a\\\": [\\\"b\\\"]})\\n    await store_1.save(cp)\\n\\n    store_2 = _store(JobService())\\n    loaded = await store_2.load_by_run_id(str(job_id))\\n\\n    assert loaded is not None\\n    assert loaded.checkpoint_id == cp.checkpoint_id\\n    assert loaded.run_map == {\\\"a\\\": [\\\"b\\\"]}\\n    assert loaded.vertices_to_run == {\\\"a\\\", \\\"b\\\"}\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_checkpoint_factory_registers_durable_store() -> None:\\n    \\\"\\\"\\\"In-app, the registered CHECKPOINT_SERVICE resolves to the durable store.\\\"\\\"\\\"\\n    from langflow.services.checkpoint.factory import CheckpointServiceFactory\\n    from langflow.services.checkpoint.store import JobScopedCheckpointStore\\n    from lfx.services.deps import get_checkpoint_service\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n\\n    manager = get_service_manager()\\n    saved = manager.services.pop(ServiceType.CHECKPOINT_SERVICE, None)\\n    try:\\n        manager.register_factory(CheckpointServiceFactory())\\n        resolved = get_checkpoint_service()\\n        assert isinstance(resolved, JobScopedCheckpointStore)\\n    finally:\\n        manager.services.pop(ServiceType.CHECKPOINT_SERVICE, None)\\n        if saved is not None:\\n            manager.services[ServiceType.CHECKPOINT_SERVICE] = saved\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_standalone_checkpoint_service_is_in_memory() -> None:\\n    \\\"\\\"\\\"With no registered service, the lfx accessor falls back to the in-memory store.\\\"\\\"\\\"\\n    from lfx.graph.checkpoint.store import InMemoryCheckpointStore\\n    from lfx.services.deps import get_checkpoint_service\\n    from lfx.services.manager import get_service_manager\\n    from lfx.services.schema import ServiceType\\n\\n    manager = get_service_manager()\\n    saved = manager.services.pop(ServiceType.CHECKPOINT_SERVICE, None)\\n    saved_factory = manager.factories.pop(ServiceType.CHECKPOINT_SERVICE, None)\\n    try:\\n        assert isinstance(get_checkpoint_service(), InMemoryCheckpointStore)\\n    finally:\\n        if saved is not None:\\n            manager.services[ServiceType.CHECKPOINT_SERVICE] = saved\\n        if saved_factory is not None:\\n            manager.factories[ServiceType.CHECKPOINT_SERVICE] = saved_factory\\n\\n\\ndef _runnable_graph(job_id, *, store=None, probe=None):\\n    \\\"\\\"\\\"Real ChatInput\u2192ChatOutput graph; run_id carries the job_id so resume resolves it.\\\"\\\"\\\"\\n    from lfx.components.input_output import ChatInput, ChatOutput\\n    from lfx.graph import Graph\\n\\n    chat_input = ChatInput(_id=\\\"chat_input\\\", input_value=\\\"hello\\\")\\n    chat_input.set(should_store_message=False)\\n    chat_output = ChatOutput(_id=\\\"chat_output\\\")\\n    chat_output.set(input_value=chat_input.message_response, should_store_message=False)\\n    graph = Graph(chat_input, chat_output)\\n    graph.session_id = \\\"sess-1\\\"\\n    graph.set_run_id(str(job_id))\\n    graph.job_id = str(job_id)\\n    if store is not None:\\n        graph.checkpointing_enabled = True\\n        graph.checkpoint_store = store\\n    if probe is not None:\\n        graph.pause_probe = probe\\n    return graph\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_e2e_save_restart_resume_matches_never_paused_control(real_services_job_service) -> None:\\n    from langflow.services.jobs.service import JobService\\n    from lfx.graph import Graph\\n    from lfx.graph.exceptions import GraphPausedException\\n\\n    control = _runnable_graph(uuid4())\\n    await control.process(fallback_to_env_vars=False)\\n    control_text = control.get_vertex(\\\"chat_output\\\").results[\\\"message\\\"].text\\n\\n    job_id = await _new_job(real_services_job_service)\\n    durable = _store(real_services_job_service)\\n    calls = {\\\"n\\\": 0}\\n\\n    async def probe(_job_id: str) -> str:\\n        calls[\\\"n\\\"] += 1\\n        return \\\"run\\\" if calls[\\\"n\\\"] == 1 else \\\"pause\\\"  # build chat_input, then pause before chat_output\\n\\n    paused = _runnable_graph(job_id, store=durable, probe=probe)\\n    with pytest.raises(GraphPausedException):\\n        await paused.process(fallback_to_env_vars=False)\\n    assert paused.get_vertex(\\\"chat_input\\\").built is True\\n    assert paused.get_vertex(\\\"chat_output\\\").built is False\\n\\n    # Restart: a fresh store + JobService on the SAME DB, no shared in-process state.\\n    fresh = _store(JobService())\\n    checkpoint = await fresh.load_by_run_id(str(job_id))\\n    assert checkpoint is not None\\n\\n    resumed = Graph.resume_from_checkpoint(checkpoint, checkpoint_store=fresh)\\n    assert resumed.get_vertex(\\\"chat_input\\\").built is True\\n    # The already-built input is not re-queued: only the remaining layer runs.\\n    assert resumed.resume_first_layer() == [\\\"chat_output\\\"]\\n\\n    await resumed.process(fallback_to_env_vars=False)\\n\\n    output_vertex = resumed.get_vertex(\\\"chat_output\\\")\\n    assert output_vertex.built is True\\n    assert output_vertex.results[\\\"message\\\"].text == control_text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_execution_timeout_scope.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a6b4b0dbb31c592ebdbbd716c7948ff584ffaead7a05db12c2ae0fe112fb413a\",\"content\":\"\\\"\\\"\\\"The sync HTTP ceiling must not bound a background run; JobRunner must.\\n\\nBefore the fix, ``_stream_event_frames`` always applied ``workflow_execution_timeout``,\\nso it nested inside the runner's ``asyncio.wait_for`` and won. That capped every\\nbackground job at the sync ceiling and made the documented\\n``background_job_timeout=None`` (\\\"no timeout\\\") unreachable.\\n\\nReal JobService, real migrated SQLite, real dispatcher, real runner. Only the ceiling\\nand the work duration are shrunk so the tests stay fast.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport time\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.api.v2 import workflow_execution as wf_exec\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\nfrom lfx.workflow.converters import ParsedWorkflowRun\\n\\n\\ndef _source(adapter, *, mode: str, background: bool):\\n    \\\"\\\"\\\"Drive the real dispatcher.\\n\\n    ``background=True`` mirrors the production background call site, which passes\\n    ``execution_timeout=None``.\\n\\n    ``expose_error_details=True`` mirrors a flow owner running their own flow, which is\\n    what the production call sites pass for that case. Without it the terminal error is\\n    replaced with the generic client-facing string, and the ceiling assertion below could\\n    no longer tell a timeout apart from any other failure.\\n    \\\"\\\"\\\"\\n    extra = {\\\"execution_timeout\\\": None} if background else {}\\n\\n    async def _run(**_kwargs):\\n        async for frame, event_type in wf_exec._stream_event_frames(\\n            adapter=adapter,\\n            flow_id=uuid4(),\\n            flow_name=\\\"flow\\\",\\n            background_tasks=SimpleNamespace(add_task=lambda *_a, **_k: None),\\n            parsed=ParsedWorkflowRun(flow_id=str(uuid4()), input_value=\\\"hi\\\", mode=mode),\\n            current_user=SimpleNamespace(id=uuid4()),\\n            protocol=\\\"v2.background\\\" if background else \\\"v2\\\",\\n            expose_error_details=True,\\n            **extra,\\n        ):\\n            yield frame, event_type\\n\\n    return _run\\n\\n\\ndef _slow_build(work_s: float):\\n    async def _build(**kwargs):\\n        await asyncio.sleep(work_s)\\n        queue = kwargs[\\\"event_manager\\\"].queue\\n        queue.put_nowait((\\\"end\\\", json.dumps({\\\"event\\\": \\\"end\\\", \\\"data\\\": {}}).encode(), time.time()))\\n        await queue.put((None, None, time.time()))\\n\\n    return _build\\n\\n\\nasync def _run_job(job_service, *, ceiling, work, job_timeout, monkeypatch, background=True, mode=\\\"background\\\"):\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    monkeypatch.setattr(wf_exec, \\\"_resolve_execution_timeout\\\", lambda: ceiling)\\n    monkeypatch.setattr(wf_exec, \\\"generate_flow_events\\\", _slow_build(work))\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=adapter,\\n        frame_source=_source(adapter, mode=mode, background=background),\\n        job_timeout=job_timeout,\\n    )\\n    await runner.run(job_id=job_id, source_kwargs={\\\"job_id\\\": job_id})\\n    return await job_service.get_job_by_job_id(job_id)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_background_run_outlives_the_sync_ceiling(real_services_job_service, monkeypatch) -> None:\\n    \\\"\\\"\\\"background_job_timeout=None means no timeout, even past the sync ceiling.\\\"\\\"\\\"\\n    job = await _run_job(real_services_job_service, ceiling=0.05, work=0.5, job_timeout=None, monkeypatch=monkeypatch)\\n    assert job.status == JobStatus.COMPLETED\\n    assert job.error is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_background_job_timeout_now_governs(real_services_job_service, monkeypatch) -> None:\\n    \\\"\\\"\\\"With background_job_timeout set, the runner bounds the run and marks it TIMED_OUT.\\\"\\\"\\\"\\n    job = await _run_job(real_services_job_service, ceiling=60.0, work=5.0, job_timeout=0.05, monkeypatch=monkeypatch)\\n    assert job.status == JobStatus.TIMED_OUT\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_stream_mode_still_enforces_the_ceiling(real_services_job_service, monkeypatch) -> None:\\n    \\\"\\\"\\\"Regression guard: a caller that does NOT opt out still gets the settings ceiling.\\\"\\\"\\\"\\n    job = await _run_job(\\n        real_services_job_service,\\n        ceiling=0.05,\\n        work=5.0,\\n        job_timeout=None,\\n        monkeypatch=monkeypatch,\\n        background=False,\\n        mode=\\\"stream\\\",\\n    )\\n    assert job.status == JobStatus.FAILED\\n    assert \\\"timed out\\\" in str(job.error).lower()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_executor_real_services.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8fdac77a72b3363d94d0304202e22f13459baf9ea17c536439c00b88b0bfefcb\",\"content\":\"\\\"\\\"\\\"Verify the in-process executor's worker resilience.\\n\\nThese tests drive the REAL ``InProcessExecutor`` (no mocks of our logic) and\\nassert the worker pool survives the two ways a job can end abnormally:\\n\\n* a job cancelled via ``cancel(key)`` must NOT take its worker down \u2014 the pool\\n  must keep accepting and completing later jobs (this is the path that broke on\\n  Python 3.10 where ``Task.cancelling()`` does not exist);\\n* a job that raises a non-``CancelledError`` exception must be caught and not\\n  kill the worker either.\\n\\nBoth are run with ``max_concurrency=1`` so a single dead worker is immediately\\nobservable: if the only worker dies, the next submitted job hangs QUEUED and the\\n``asyncio.wait_for`` guard fails the test rather than hanging the suite.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\n\\nimport pytest\\nfrom langflow.services.background_execution.executor import InProcessExecutor\\n\\npytestmark = pytest.mark.real_services\\n\\n\\nasync def test_pool_survives_repeated_job_cancellation(monkeypatch):\\n    \\\"\\\"\\\"Cancelling N jobs in a row must not kill the (single) worker.\\n\\n    With one worker, each ``cancel(key)`` cancels the in-flight task. The worker\\n    must absorb that cancel, keep looping, and remain able to run a fresh job.\\n\\n    The project supports Python 3.10, where ``asyncio.Task.cancelling()`` does\\n    NOT exist. The old worker used ``cancelling()`` to tell a job-cancel apart\\n    from a worker-cancel; on 3.10 that raised ``AttributeError`` inside the\\n    cancel handler and permanently killed the worker, so the final \\\"fresh job\\n    completes\\\" assertion would hang. We pin the 3.10 condition by wrapping the\\n    worker's ``current_task()`` in a proxy that has no ``cancelling`` so the test\\n    catches the bug on every interpreter (>=3.11 included), not just on a real\\n    3.10.\\n    \\\"\\\"\\\"\\n    # Simulate Python 3.10: ``asyncio.current_task()`` returns a Task without a\\n    # ``cancelling`` method. We can't delete the attribute off the immutable C\\n    # ``_asyncio.Task`` type, so we wrap the real task in a proxy that exposes\\n    # everything EXCEPT ``cancelling`` \u2014 touching ``.cancelling`` raises\\n    # ``AttributeError`` exactly as it does on a real 3.10 interpreter. Patched\\n    # in the executor's namespace so only the worker sees the 3.10-shaped task.\\n    import langflow.services.background_execution.executor as executor_mod\\n\\n    real_current_task = asyncio.current_task\\n\\n    class _Py310TaskProxy:\\n        def __init__(self, task):\\n            object.__setattr__(self, \\\"_task\\\", task)\\n\\n        def __getattr__(self, name):\\n            if name == \\\"cancelling\\\":\\n                msg = \\\"'_asyncio.Task' object has no attribute 'cancelling'\\\"\\n                raise AttributeError(msg)\\n            return getattr(self._task, name)\\n\\n    def _fake_current_task():\\n        task = real_current_task()\\n        return _Py310TaskProxy(task) if task is not None else None\\n\\n    monkeypatch.setattr(executor_mod.asyncio, \\\"current_task\\\", _fake_current_task)\\n\\n    executor = InProcessExecutor(max_concurrency=1)\\n    await executor.start()\\n    try:\\n        for i in range(5):\\n            started = asyncio.Event()\\n            key = f\\\"job-{i}\\\"\\n\\n            async def _blocker(ev=started) -> None:\\n                ev.set()\\n                await asyncio.sleep(3600)  # block until cancelled\\n\\n            await executor.submit(key, _blocker)\\n            await asyncio.wait_for(started.wait(), timeout=2.0)\\n            assert await executor.cancel(key) is True\\n\\n        # The pool must still serve work after 5 cancellations.\\n        done = asyncio.Event()\\n\\n        async def _quick() -> None:\\n            done.set()\\n\\n        await executor.submit(\\\"fresh\\\", _quick)\\n        # If the worker died, this hangs and wait_for fails the test.\\n        await asyncio.wait_for(done.wait(), timeout=2.0)\\n    finally:\\n        await executor.stop()\\n\\n\\nasync def test_stop_awaits_in_flight_tasks():\\n    \\\"\\\"\\\"``stop()`` leaves every in-flight task ``done()`` when it returns.\\n\\n    A real job cancelled mid-flight reconciles its terminal status inside a\\n    shielded ``finally`` (a DB write). ``stop()`` cancels the in-flight tasks and\\n    then ``gather``s them so that work finishes before teardown, rather than\\n    racing a closing DB engine and leaving a \\\"Task was destroyed but it is\\n    pending\\\" warning. We capture the in-flight task handle and assert it (and its\\n    multi-turn shielded finalizer) is done the instant ``stop()`` returns \u2014 the\\n    awaited-teardown contract the gather guarantees.\\n    \\\"\\\"\\\"\\n    running = asyncio.Event()\\n    finalized = asyncio.Event()\\n\\n    async def _job() -> None:\\n        try:\\n            running.set()\\n            await asyncio.sleep(3600)  # block until cancelled\\n        finally:\\n            # The runner's terminal reconcile is a shielded await (a DB write)\\n            # that spans several event-loop turns. Model it so the task only\\n            # finishes after a real awaited finalizer, not the instant the\\n            # cancel is delivered.\\n            for _ in range(10):\\n                await asyncio.shield(asyncio.sleep(0.02))\\n            finalized.set()\\n\\n    executor = InProcessExecutor(max_concurrency=1)\\n    await executor.start()\\n    await executor.submit(\\\"job\\\", _job)\\n    await asyncio.wait_for(running.wait(), timeout=2.0)\\n\\n    # Capture the in-flight task before stop() clears the registry.\\n    in_flight = executor._in_flight[\\\"job\\\"]\\n\\n    await executor.stop()\\n\\n    # If stop() awaited the in-flight task, it (and its shielded finalizer) are\\n    # done the moment stop() returns. A non-awaiting stop() leaves it pending.\\n    assert in_flight.done(), \\\"stop() returned without awaiting the in-flight task\\\"\\n    assert finalized.is_set(), \\\"shielded finalizer did not complete before stop() returned\\\"\\n\\n\\nasync def test_pool_survives_job_exception():\\n    \\\"\\\"\\\"A job raising a non-CancelledError must not kill the worker.\\\"\\\"\\\"\\n    executor = InProcessExecutor(max_concurrency=1)\\n    await executor.start()\\n    try:\\n\\n        async def _boom() -> None:\\n            msg = \\\"intentional job failure\\\"\\n            raise RuntimeError(msg)\\n\\n        await executor.submit(\\\"boom\\\", _boom)\\n        # Give the worker a beat to pick up and fail the bad job.\\n        await asyncio.sleep(0.1)\\n\\n        done = asyncio.Event()\\n\\n        async def _quick() -> None:\\n            done.set()\\n\\n        await executor.submit(\\\"after-boom\\\", _quick)\\n        await asyncio.wait_for(done.wait(), timeout=2.0)\\n    finally:\\n        await executor.stop()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_facade_real_services.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f01c3adb1cc01d1e9df62562a585e8a59893af49239f586a0b02354dd8ddbee\",\"content\":\"\\\"\\\"\\\"Verify the durable background path on real SQLite AND real Postgres.\\n\\nThe Runner + InMemoryLiveBus + facade durable replay all sit on ``JobService``,\\nwhose ``session_scope()`` the ``real_services_job_service`` fixture binds to a real,\\nmigrated DB parametrized over sqlite and postgres. These tests drive the real\\nRunner with a scripted frame source (legitimate test input, not a mock of our\\nlogic) and assert durable persistence, ordering, terminal state, reattach replay,\\nand the orphan sweep on BOTH engines.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom types import SimpleNamespace\\nfrom typing import TYPE_CHECKING\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus, LiveFrame\\nfrom langflow.services.background_execution.runner import JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus, SignalType\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n\\npytestmark = pytest.mark.real_services\\n\\n\\ndef _frame(event_type: str, data: dict) -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(\\\"utf-8\\\"), event_type)\\n\\n\\ndef _runner(job_service, bus, job_id, source) -> JobRunner:\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    return JobRunner(job_service=job_service, live_bus=bus, adapter=adapter, frame_source=source)\\n\\n\\nasync def test_durable_persistence_and_terminal_state(real_services_job_service):\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"token\\\", {\\\"chunk\\\": \\\"x\\\"})  # ephemeral\\n        yield _frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.COMPLETED\\n    assert job.result is not None\\n\\n    events = await job_service.read_events(job_id, after_seq=0)\\n    types = [e.event_type for e in events]\\n    assert \\\"token\\\" not in types  # ephemeral not persisted\\n    assert types == [\\\"build_start\\\", \\\"end_vertex\\\", \\\"end\\\"]\\n    assert [e.seq for e in events] == [1, 2, 3]  # contiguous, monotonic\\n\\n\\nasync def test_reattach_replays_durable_after_completion(real_services_job_service):\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    # Reattach from 0 after completion: durable rows replay in order, no gap.\\n    async def read_durable(after_seq: int) -> list[LiveFrame]:\\n        rows = await job_service.read_events(job_id, after_seq=after_seq)\\n        return [LiveFrame(seq=r.seq, data=json.dumps(r.payload).encode(\\\"utf-8\\\")) for r in rows]\\n\\n    seqs = []\\n    bodies = b\\\"\\\"\\n    async for frame in bus.reattach(str(job_id), last_seq=0, read_durable=read_durable):\\n        seqs.append(frame.seq)\\n        bodies += frame.data\\n    assert seqs == [1, 2, 3]\\n    assert b\\\"build_start\\\" in bodies\\n    assert b\\\"end_vertex\\\" in bodies\\n\\n\\nasync def test_reattach_from_midpoint_has_no_gap(real_services_job_service):\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    async def read_durable(after_seq: int) -> list[LiveFrame]:\\n        rows = await job_service.read_events(job_id, after_seq=after_seq)\\n        return [LiveFrame(seq=r.seq, data=json.dumps(r.payload).encode(\\\"utf-8\\\")) for r in rows]\\n\\n    # Reattach from last_seq=1: must replay only seq 2,3 (no gap, no overlap).\\n    seqs = [frame.seq async for frame in bus.reattach(str(job_id), last_seq=1, read_durable=read_durable)]\\n    assert seqs == [2, 3]\\n\\n\\nasync def test_stop_signal_cancels_run(real_services_job_service):\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    # A STOP written before the run makes the first boundary poll cancel it.\\n    await job_service.write_signal(job_id, SignalType.STOP)\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.CANCELLED\\n\\n\\nasync def test_sweep_orphans_fails_in_progress(real_services_job_service):\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await job_service.update_job_status(job_id, JobStatus.IN_PROGRESS)\\n\\n    failed = await job_service.sweep_orphans()\\n    assert job_id in failed\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.FAILED\\n    assert job.error is not None\\n    assert job.error.get(\\\"type\\\") == \\\"worker_lost\\\"\\n\\n\\nasync def test_redis_fallback_watchdog_reconciles_orphans_without_restart(real_services_job_service):\\n    \\\"\\\"\\\"A steady Redis-configured fleet must reap a dead owner's stale job.\\\"\\\"\\\"\\n    import asyncio\\n    from datetime import datetime, timedelta, timezone\\n    from types import SimpleNamespace\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    settings = get_settings_service().settings.model_copy(\\n        update={\\n            \\\"job_queue_type\\\": \\\"redis\\\",\\n            \\\"background_lease_ttl_s\\\": 0.02,\\n            \\\"background_watchdog_interval_s\\\": 0.01,\\n        }\\n    )\\n    service = BackgroundExecutionService(settings_service=SimpleNamespace(settings=settings))\\n    await service.start()\\n    try:\\n        job_id = uuid4()\\n        await real_services_job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n        await real_services_job_service.update_job_status(job_id, JobStatus.IN_PROGRESS)\\n        stale_heartbeat = (datetime.now(timezone.utc) - timedelta(seconds=60)).isoformat()\\n        await real_services_job_service.update_job_metadata(\\n            job_id,\\n            {\\\"owner\\\": \\\"dead-replica\\\", \\\"heartbeat_at\\\": stale_heartbeat},\\n        )\\n\\n        job = None\\n        for _ in range(100):\\n            job = await real_services_job_service.get_job_by_job_id(job_id)\\n            if job.status == JobStatus.FAILED:\\n                break\\n            await asyncio.sleep(0.01)\\n\\n        assert job is not None\\n        assert job.status == JobStatus.FAILED\\n        assert job.error == {\\\"type\\\": \\\"worker_lost\\\"}\\n        assert job.finished_timestamp is not None\\n    finally:\\n        await service.stop()\\n\\n\\ndef _echo_input_factory(*, request, **_kwargs):\\n    \\\"\\\"\\\"Frame source that echoes ``request['input_value']`` into a durable event.\\n\\n    Proves the re-enqueued QUEUED job replays its ORIGINAL inputs: the input it\\n    actually runs with shows up in the durable ``job_events`` log, so a restart\\n    that lost the in-memory request body would surface a different (defaulted)\\n    value here.\\n    \\\"\\\"\\\"\\n    input_value = request.get(\\\"input_value\\\")\\n\\n    async def _source(**_kw):\\n        # ``add_message`` is a durable langflow event, so it lands in job_events\\n        # and survives for the post-run assertion.\\n        yield _frame(\\\"add_message\\\", {\\\"input_value\\\": input_value})\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\nclass _RecordingBackend:\\n    \\\"\\\"\\\"Scaled-backend stand-in that records durable job ids without running them.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self.enqueued: list[str] = []\\n\\n    async def enqueue(self, job_id: str) -> None:\\n        self.enqueued.append(job_id)\\n\\n\\ndef _capture_request_factory(captured: list[dict]):\\n    \\\"\\\"\\\"Record the request a fresh worker hydrates without persisting its secrets.\\\"\\\"\\\"\\n\\n    def _factory(*, request, **_kwargs):\\n        captured.append(request)\\n\\n        async def _source(**_kw):\\n            yield _frame(\\\"end\\\", {})\\n\\n        return _source\\n\\n    return _factory\\n\\n\\nasync def test_submit_persists_request_for_faithful_requeue(real_services_job_service):\\n    \\\"\\\"\\\"``submit`` persists only replay-safe request fields on job_metadata.request.\\n\\n    The startup sweep needs the original non-secret inputs, but caller tweaks may\\n    contain credentials and must live outside the plaintext request in an encrypted\\n    envelope. Proven on both real SQLite and real Postgres. The executor is stopped\\n    right after submit so no run interferes with reading the persisted row.\\n    \\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    original_input = f\\\"original-input-{uuid4()}\\\"\\n    flow_id = uuid4()\\n\\n    svc = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n    )\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": original_input,\\n        \\\"session_id\\\": \\\"thread-restart\\\",\\n        \\\"tweaks\\\": {\\\"ChatInput-x\\\": {\\\"foo\\\": \\\"bar\\\"}},\\n    }\\n    job_id = await svc.submit(flow_id=flow_id, request=request, user=_StubUser(uuid4()))\\n    await svc.stop()\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.job_metadata is not None\\n    persisted = job.job_metadata.get(\\\"request\\\")\\n    assert persisted == {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": original_input,\\n        \\\"session_id\\\": \\\"thread-restart\\\",\\n    }\\n    assert job.job_metadata.get(\\\"request_overrides_format\\\") == \\\"fernet-json-v1\\\"\\n    assert isinstance(job.job_metadata.get(\\\"request_overrides\\\"), str)\\n    hydrated = svc._reconstruct_request(job)\\n    assert hydrated == request\\n    # Redaction must not mutate the live request passed to the in-memory run.\\n    assert request[\\\"tweaks\\\"] == {\\\"ChatInput-x\\\": {\\\"foo\\\": \\\"bar\\\"}}\\n\\n\\nasync def test_submit_redacts_inline_overrides_from_persisted_request(real_services_job_service):\\n    \\\"\\\"\\\"Inline ``globals`` and ``tweaks`` must NOT land plaintext on the row.\\n\\n    Both request shapes can carry API keys. Storing either plaintext in the durable\\n    ``job`` table widens the blast radius of any DB read (backup, ops access, a\\n    SQL-injection elsewhere). The persisted plaintext request must omit both while\\n    authenticated decryption restores them for replay. Real SQLite and Postgres.\\n    \\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    flow_id = uuid4()\\n    secret = f\\\"sk-secret-{uuid4()}\\\"\\n\\n    svc = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n    )\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"hi\\\",\\n        \\\"globals\\\": {\\\"OPENAI_API_KEY\\\": secret},\\n        \\\"tweaks\\\": {\\\"LanguageModelComponent-x\\\": {\\\"api_key\\\": secret}},\\n    }\\n    job_id = await svc.submit(flow_id=flow_id, request=request, user=_StubUser(uuid4()))\\n    await svc.stop()\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    persisted = job.job_metadata.get(\\\"request\\\") or {}\\n    # Neither secret-bearing override shape may appear in the persisted blob.\\n    assert \\\"globals\\\" not in persisted, \\\"inline globals persisted plaintext on the job row\\\"\\n    assert \\\"tweaks\\\" not in persisted, \\\"inline tweaks persisted plaintext on the job row\\\"\\n    assert secret not in json.dumps(job.job_metadata), \\\"inline secret leaked into job_metadata\\\"\\n    assert svc._reconstruct_request(job) == request\\n    # The caller's original request dict is not mutated as a side effect.\\n    assert request[\\\"globals\\\"] == {\\\"OPENAI_API_KEY\\\": secret}\\n    assert request[\\\"tweaks\\\"] == {\\\"LanguageModelComponent-x\\\": {\\\"api_key\\\": secret}}\\n\\n\\nasync def test_submit_writes_request_and_encrypted_overrides_atomically(real_services_job_service, monkeypatch):\\n    \\\"\\\"\\\"Submit must not expose a QUEUED row before its durable replay payload exists.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    backend = _RecordingBackend()\\n    flow_id = uuid4()\\n\\n    async def _unexpected_metadata_update(*_args, **_kwargs):\\n        pytest.fail(\\\"submit persisted replay metadata in a second transaction\\\")\\n\\n    monkeypatch.setattr(job_service, \\\"update_job_metadata\\\", _unexpected_metadata_update)\\n    svc = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n        backend=backend,\\n    )\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"atomic\\\",\\n        \\\"tweaks\\\": {\\\"LanguageModelComponent-x\\\": {\\\"api_key\\\": \\\"secret-atomic\\\"}},  # pragma: allowlist secret\\n    }\\n    job_id = await svc.submit(flow_id=flow_id, request=request, user=_StubUser(uuid4()))\\n\\n    assert backend.enqueued == [str(job_id)]\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.job_metadata.get(\\\"request\\\") == {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"atomic\\\",\\n    }\\n    assert \\\"secret-atomic\\\" not in json.dumps(job.job_metadata)\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"field\\\", \\\"invalid_case\\\"),\\n    [\\n        (\\\"tweaks\\\", \\\"nan\\\"),\\n        (\\\"tweaks\\\", \\\"infinity\\\"),\\n        (\\\"tweaks\\\", \\\"non-string-key\\\"),\\n        (\\\"tweaks\\\", \\\"unsupported-value\\\"),\\n        (\\\"tweaks\\\", \\\"cycle\\\"),\\n        (\\\"tweaks\\\", \\\"too-deep\\\"),\\n        (\\\"tweaks\\\", \\\"lone-surrogate\\\"),\\n        (\\\"tweaks\\\", \\\"lone-surrogate-key\\\"),\\n        (\\\"tweaks\\\", \\\"oversized-integer\\\"),\\n        (\\\"tweaks\\\", \\\"top-level-shape\\\"),\\n        (\\\"globals\\\", \\\"top-level-shape\\\"),\\n    ],\\n)\\nasync def test_submit_rejects_invalid_override_grammar_before_creating_job(\\n    real_services_job_service,\\n    field,\\n    invalid_case,\\n):\\n    \\\"\\\"\\\"Caller validation failures identify the field and never persist a job.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import (\\n        BackgroundExecutionService,\\n        InvalidRequestOverridesError,\\n    )\\n    from langflow.services.deps import get_settings_service\\n\\n    if invalid_case == \\\"nan\\\":\\n        invalid_value = {\\\"Node-x\\\": {\\\"value\\\": float(\\\"nan\\\")}}\\n    elif invalid_case == \\\"infinity\\\":\\n        invalid_value = {\\\"Node-x\\\": {\\\"value\\\": float(\\\"inf\\\")}}\\n    elif invalid_case == \\\"non-string-key\\\":\\n        invalid_value = {\\\"Node-x\\\": {1: \\\"value\\\"}}\\n    elif invalid_case == \\\"unsupported-value\\\":\\n        invalid_value = {\\\"Node-x\\\": {\\\"value\\\": object()}}\\n    elif invalid_case == \\\"cycle\\\":\\n        cyclic: dict = {}\\n        cyclic[\\\"self\\\"] = cyclic\\n        invalid_value = {\\\"Node-x\\\": cyclic}\\n    elif invalid_case == \\\"too-deep\\\":\\n        nested: object = \\\"leaf\\\"\\n        for _ in range(66):\\n            nested = [nested]\\n        invalid_value = {\\\"Node-x\\\": {\\\"value\\\": nested}}\\n    elif invalid_case == \\\"lone-surrogate\\\":\\n        invalid_value = {\\\"Node-x\\\": {\\\"value\\\": \\\"\\\\ud800\\\"}}\\n    elif invalid_case == \\\"lone-surrogate-key\\\":\\n        invalid_value = {\\\"Node-x\\\": {\\\"\\\\ud800\\\": \\\"value\\\"}}\\n    elif invalid_case == \\\"oversized-integer\\\":\\n        invalid_value = {\\\"Node-x\\\": {\\\"value\\\": 10**5000}}\\n    else:\\n        invalid_value = [\\\"not-a-mapping\\\"]\\n\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    service = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n        backend=_RecordingBackend(),\\n    )\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"invalid-overrides\\\",\\n        field: invalid_value,\\n    }\\n\\n    with pytest.raises(InvalidRequestOverridesError) as exc_info:\\n        await service.submit(flow_id=flow_id, request=request, user=_StubUser(user_id))\\n\\n    assert exc_info.value.field == field\\n    assert await job_service.get_jobs_by_flow_id(flow_id, user_id) == []\\n\\n\\nasync def test_submit_crypto_unavailable_creates_no_job(real_services_job_service, monkeypatch):\\n    \\\"\\\"\\\"Server-side encryption failure is retryable and precedes durable creation.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import (\\n        BackgroundExecutionService,\\n        RequestOverridesUnavailableError,\\n    )\\n    from langflow.services.deps import get_settings_service\\n\\n    def _unavailable_fernet(_settings_service):\\n        raise RuntimeError\\n\\n    monkeypatch.setattr(\\\"langflow.services.auth.utils.get_fernet\\\", _unavailable_fernet)\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    service = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n        backend=_RecordingBackend(),\\n    )\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"crypto-unavailable\\\",\\n        \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"never-persisted\\\"}},  # pragma: allowlist secret\\n    }\\n\\n    with pytest.raises(RequestOverridesUnavailableError):\\n        await service.submit(flow_id=flow_id, request=request, user=_StubUser(user_id))\\n\\n    assert await job_service.get_jobs_by_flow_id(flow_id, user_id) == []\\n\\n\\nasync def test_submit_serialization_resource_unavailable_creates_no_job(real_services_job_service, monkeypatch):\\n    \\\"\\\"\\\"Transient JSON serialization resource failures use the retryable server error.\\\"\\\"\\\"\\n    from types import SimpleNamespace\\n\\n    from langflow.services.background_execution import service as background_service\\n    from langflow.services.background_execution.service import (\\n        BackgroundExecutionService,\\n        RequestOverridesUnavailableError,\\n    )\\n    from langflow.services.deps import get_settings_service\\n\\n    def _unavailable_dumps(*_args, **_kwargs):\\n        raise MemoryError\\n\\n    monkeypatch.setattr(\\n        background_service,\\n        \\\"json\\\",\\n        SimpleNamespace(dumps=_unavailable_dumps, loads=json.loads),\\n    )\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    service = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n        backend=_RecordingBackend(),\\n    )\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"value\\\": \\\"retry-after-resource-recovery\\\"}},\\n    }\\n\\n    with pytest.raises(RequestOverridesUnavailableError):\\n        await service.submit(flow_id=flow_id, request=request, user=_StubUser(user_id))\\n\\n    assert await job_service.get_jobs_by_flow_id(flow_id, user_id) == []\\n\\n\\n@pytest.mark.parametrize(\\\"new_owner\\\", [\\\"old-owner\\\", \\\"new-owner\\\"])\\nasync def test_release_queued_lease_never_clears_an_updated_claim(real_services_job_service, new_owner):\\n    \\\"\\\"\\\"A stale recovery cannot release a claim whose owner or heartbeat advanced.\\\"\\\"\\\"\\n    from datetime import datetime, timezone\\n\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    old_heartbeat = datetime.now(timezone.utc).isoformat()\\n    assert await job_service.claim_queued_lease(\\n        job_id,\\n        owner=\\\"old-owner\\\",\\n        lease_ttl_s=0,\\n        heartbeat_at=old_heartbeat,\\n    )\\n    new_heartbeat = datetime.now(timezone.utc).isoformat()\\n    await job_service.update_job_metadata(job_id, {\\\"owner\\\": new_owner, \\\"heartbeat_at\\\": new_heartbeat})\\n\\n    released = await job_service.release_queued_lease(\\n        job_id,\\n        owner=\\\"old-owner\\\",\\n        heartbeat_at=old_heartbeat,\\n    )\\n\\n    assert released is False\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert (job.job_metadata or {}).get(\\\"owner\\\") == new_owner\\n    assert (job.job_metadata or {}).get(\\\"heartbeat_at\\\") == new_heartbeat\\n    await job_service.update_job_status(job_id, JobStatus.CANCELLED, finished_timestamp=True)\\n\\n\\nasync def test_fail_queued_job_never_terminalizes_a_replaced_claim(real_services_job_service):\\n    \\\"\\\"\\\"A stale recovery cannot fail a QUEUED row after another owner replaces its claim.\\\"\\\"\\\"\\n    from datetime import datetime, timezone\\n\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    old_heartbeat = datetime.now(timezone.utc).isoformat()\\n    assert await job_service.claim_queued_lease(\\n        job_id,\\n        owner=\\\"old-owner\\\",\\n        lease_ttl_s=0,\\n        heartbeat_at=old_heartbeat,\\n    )\\n    new_heartbeat = datetime.now(timezone.utc).isoformat()\\n    await job_service.update_job_metadata(job_id, {\\\"owner\\\": \\\"new-owner\\\", \\\"heartbeat_at\\\": new_heartbeat})\\n\\n    failed = await job_service.fail_queued_job(\\n        job_id,\\n        owner=\\\"old-owner\\\",\\n        heartbeat_at=old_heartbeat,\\n        error={\\\"type\\\": \\\"request_overrides_unavailable\\\"},\\n        event_type=\\\"run_failed\\\",\\n    )\\n\\n    assert failed is False\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.QUEUED\\n    assert job.error is None\\n    assert (job.job_metadata or {}).get(\\\"owner\\\") == \\\"new-owner\\\"\\n    assert (job.job_metadata or {}).get(\\\"heartbeat_at\\\") == new_heartbeat\\n    assert await job_service.read_events(job_id, after_seq=0) == []\\n    await job_service.update_job_status(job_id, JobStatus.CANCELLED, finished_timestamp=True)\\n\\n\\nasync def test_fail_queued_job_retries_event_sequence_collision_atomically(real_services_job_service, monkeypatch):\\n    \\\"\\\"\\\"A colliding event insert rolls back the status CAS before retrying the whole transaction.\\\"\\\"\\\"\\n    from datetime import datetime, timezone\\n\\n    from langflow.services.database.models.jobs.model import JobEvent\\n    from langflow.services.jobs import service as jobs_service_module\\n    from sqlalchemy.exc import IntegrityError\\n\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    heartbeat = datetime.now(timezone.utc).isoformat()\\n    assert await job_service.claim_queued_lease(\\n        job_id,\\n        owner=\\\"recovery-owner\\\",\\n        lease_ttl_s=0,\\n        heartbeat_at=heartbeat,\\n    )\\n    await job_service.append_event(job_id, \\\"queued\\\", {})\\n\\n    calls = 0\\n\\n    class _CollidingJobEvent:\\n        job_id = JobEvent.job_id\\n        seq = JobEvent.seq\\n\\n        def __new__(cls, *args, **kwargs):\\n            nonlocal calls\\n            calls += 1\\n            if calls == 1:\\n                collision = \\\"forced event sequence collision\\\"\\n                raise IntegrityError(collision, None, RuntimeError())\\n            return JobEvent(*args, **kwargs)\\n\\n    monkeypatch.setattr(jobs_service_module, \\\"JobEvent\\\", _CollidingJobEvent)\\n\\n    failed = await job_service.fail_queued_job(\\n        job_id,\\n        owner=\\\"recovery-owner\\\",\\n        heartbeat_at=heartbeat,\\n        error={\\\"type\\\": \\\"request_overrides_unavailable\\\"},\\n        event_type=\\\"run_failed\\\",\\n    )\\n    monkeypatch.setattr(jobs_service_module, \\\"JobEvent\\\", JobEvent)\\n\\n    assert failed is True\\n    assert calls == 2\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.FAILED\\n    assert job.error == {\\\"type\\\": \\\"request_overrides_unavailable\\\"}\\n    assert [(event.seq, event.event_type) for event in await job_service.read_events(job_id, after_seq=0)] == [\\n        (1, \\\"queued\\\"),\\n        (2, \\\"run_failed\\\"),\\n    ]\\n\\n\\nasync def test_restart_and_scaled_hydration_restore_encrypted_overrides(real_services_job_service):\\n    \\\"\\\"\\\"A job-id-only handoff and a fresh startup both replay the original overrides.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    backend = _RecordingBackend()\\n    flow_id = uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"restart-with-overrides\\\",\\n        \\\"globals\\\": {\\\"MODEL_API_KEY\\\": \\\"restart-secret\\\"},  # pragma: allowlist secret\\n        \\\"tweaks\\\": {  # pragma: allowlist secret\\n            \\\"LanguageModelComponent-x\\\": {  # pragma: allowlist secret\\n                \\\"api_key\\\": \\\"restart-secret\\\",  # pragma: allowlist secret\\n                \\\"temperature\\\": 0.2,\\n            }\\n        },\\n    }\\n    submitter = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n        backend=backend,\\n    )\\n    job_id = await submitter.submit(flow_id=flow_id, request=request, user=_StubUser(uuid4()))\\n    assert backend.enqueued == [str(job_id)]\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    # This is the worker/scaled hydration seam: only the queued job id crosses the bus.\\n    assert submitter._reconstruct_request(job) == request\\n\\n    captured: list[dict] = []\\n    restart = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_capture_request_factory(captured),\\n    )\\n    await restart.start()\\n    try:\\n        await restart.sweep_orphans_on_startup()\\n        for _ in range(100):\\n            recovered = await job_service.get_job_by_job_id(job_id)\\n            if recovered.status == JobStatus.COMPLETED:\\n                break\\n            await asyncio.sleep(0.05)\\n    finally:\\n        await restart.stop()\\n\\n    # The shared real-services DB may contain other QUEUED fixtures; this target\\n    # must still hydrate exactly once with its full authenticated request.\\n    assert captured.count(request) == 1\\n    assert recovered.status == JobStatus.COMPLETED\\n\\n\\n@pytest.mark.parametrize(\\\"damage\\\", [\\\"missing\\\", \\\"null\\\"])\\nasync def test_startup_terminalizes_unavailable_encrypted_overrides(real_services_job_service, damage):\\n    \\\"\\\"\\\"Malformed marker/ciphertext pairs terminalize without running downgraded.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    backend = _RecordingBackend()\\n    flow_id = uuid4()\\n    settings_service = get_settings_service()\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_echo_input_factory,\\n        backend=backend,\\n    )\\n    job_id = await submitter.submit(\\n        flow_id=flow_id,\\n        request={\\n            \\\"flow_id\\\": str(flow_id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": \\\"langflow\\\",\\n            \\\"input_value\\\": \\\"must-not-run\\\",\\n            \\\"tweaks\\\": {  # pragma: allowlist secret\\n                \\\"LanguageModelComponent-x\\\": {\\\"api_key\\\": \\\"tamper-secret\\\"}  # pragma: allowlist secret\\n            },\\n        },\\n        user=_StubUser(uuid4()),\\n    )\\n    job = await job_service.get_job_by_job_id(job_id)\\n    metadata = dict(job.job_metadata)\\n    if damage == \\\"missing\\\":\\n        metadata.pop(\\\"request_overrides\\\")\\n    elif damage == \\\"null\\\":\\n        metadata[\\\"request_overrides\\\"] = None\\n    await job_service.update_job_metadata(job_id, metadata, replace=True)\\n\\n    ran: list[dict] = []\\n    restart = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_capture_request_factory(ran),\\n    )\\n    await restart.sweep_orphans_on_startup()\\n    await restart.stop()\\n\\n    failed = await job_service.get_job_by_job_id(job_id)\\n    assert ran == []\\n    assert failed.status == JobStatus.FAILED\\n    assert failed.error == {\\\"type\\\": \\\"request_overrides_unavailable\\\"}\\n    assert \\\"tamper-secret\\\" not in json.dumps(failed.error)\\n    events = await job_service.read_events(job_id, after_seq=0)\\n    assert [(event.event_type, event.payload) for event in events] == [\\n        (\\\"run_failed\\\", {\\\"type\\\": \\\"request_overrides_unavailable\\\"})\\n    ]\\n\\n\\n@pytest.mark.parametrize(\\\"failure\\\", [\\\"wrong-key\\\", \\\"auth-failure\\\"])\\nasync def test_startup_keeps_ambiguous_crypto_failures_queued_and_replays_after_recovery(\\n    real_services_job_service,\\n    failure,\\n):\\n    \\\"\\\"\\\"Unreadable Fernet tokens remain retryable because key loss and tampering are indistinguishable.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from cryptography.fernet import Fernet\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n    from pydantic import SecretStr\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    backend = _RecordingBackend()\\n    flow_id, user_id = uuid4(), uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": f\\\"recover-{failure}\\\",\\n        \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"recoverable-secret\\\"}},  # pragma: allowlist secret\\n    }\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_echo_input_factory,\\n        backend=backend,\\n    )\\n    job_id = await submitter.submit(flow_id=flow_id, request=request, user=_StubUser(user_id))\\n    original = await job_service.get_job_by_job_id(job_id)\\n    original_metadata = dict(original.job_metadata)\\n\\n    recovery_settings = settings_service\\n    if failure == \\\"wrong-key\\\":\\n        wrong_auth = settings_service.auth_settings.model_copy(\\n            update={\\\"SECRET_KEY\\\": SecretStr(Fernet.generate_key().decode())}\\n        )\\n        recovery_settings = SimpleNamespace(settings=settings_service.settings, auth_settings=wrong_auth)\\n    else:\\n        damaged = dict(original_metadata)\\n        token = damaged[\\\"request_overrides\\\"]\\n        damaged[\\\"request_overrides\\\"] = f\\\"{token[:-1]}{'A' if token[-1] != 'A' else 'B'}\\\"\\n        await job_service.update_job_metadata(job_id, damaged, replace=True)\\n\\n    ran: list[dict] = []\\n    unavailable = BackgroundExecutionService(\\n        settings_service=recovery_settings,\\n        frame_source_factory=_capture_request_factory(ran),\\n    )\\n    await unavailable.sweep_orphans_on_startup()\\n    await unavailable.stop()\\n\\n    queued = await job_service.get_job_by_job_id(job_id)\\n    assert ran == []\\n    assert queued.status == JobStatus.QUEUED\\n    assert queued.error is None\\n    assert (queued.job_metadata or {}).get(\\\"owner\\\") is None\\n    assert (queued.job_metadata or {}).get(\\\"heartbeat_at\\\") is None\\n    assert await job_service.read_events(job_id, after_seq=0) == []\\n\\n    if failure == \\\"auth-failure\\\":\\n        await job_service.update_job_metadata(job_id, original_metadata, replace=True)\\n\\n    captured: list[dict] = []\\n    restored = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_capture_request_factory(captured),\\n    )\\n    await restored.start()\\n    try:\\n        await restored.sweep_orphans_on_startup()\\n        for _ in range(100):\\n            replayed = await job_service.get_job_by_job_id(job_id)\\n            if replayed.status == JobStatus.COMPLETED:\\n                break\\n            await asyncio.sleep(0.05)\\n    finally:\\n        await restored.stop()\\n\\n    assert replayed.status == JobStatus.COMPLETED\\n    assert captured.count(request) == 1\\n\\n\\nasync def test_startup_terminalizes_authenticated_malformed_override_payload(real_services_job_service):\\n    \\\"\\\"\\\"Authenticated payload corruption is distinct from ambiguous Fernet authentication failure.\\\"\\\"\\\"\\n    from langflow.services.auth.utils import get_fernet\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    flow_id, user_id = uuid4(), uuid4()\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_echo_input_factory,\\n        backend=_RecordingBackend(),\\n    )\\n    job_id = await submitter.submit(\\n        flow_id=flow_id,\\n        request={\\n            \\\"flow_id\\\": str(flow_id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": \\\"langflow\\\",\\n            \\\"input_value\\\": \\\"authenticated-corruption\\\",\\n            \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"corrupt-secret\\\"}},  # pragma: allowlist secret\\n        },\\n        user=_StubUser(user_id),\\n    )\\n    job = await job_service.get_job_by_job_id(job_id)\\n    metadata = dict(job.job_metadata)\\n    malformed = {\\n        \\\"version\\\": 1,\\n        \\\"job_id\\\": str(job_id),\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"overrides\\\": {\\\"tweaks\\\": [\\\"not-a-mapping\\\"]},\\n    }\\n    metadata[\\\"request_overrides\\\"] = get_fernet(settings_service).encrypt(json.dumps(malformed).encode()).decode()\\n    await job_service.update_job_metadata(job_id, metadata, replace=True)\\n\\n    ran: list[dict] = []\\n    restart = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_capture_request_factory(ran),\\n    )\\n    await restart.sweep_orphans_on_startup()\\n    await restart.stop()\\n\\n    failed = await job_service.get_job_by_job_id(job_id)\\n    assert ran == []\\n    assert failed.status == JobStatus.FAILED\\n    assert failed.error == {\\\"type\\\": \\\"request_overrides_unavailable\\\"}\\n\\n\\nasync def test_startup_terminalizes_non_ascii_override_ciphertext(real_services_job_service):\\n    \\\"\\\"\\\"A non-ASCII Fernet token is structural corruption, not an ambiguous authentication failure.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    flow_id, user_id = uuid4(), uuid4()\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_echo_input_factory,\\n        backend=_RecordingBackend(),\\n    )\\n    job_id = await submitter.submit(\\n        flow_id=flow_id,\\n        request={\\n            \\\"flow_id\\\": str(flow_id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": \\\"langflow\\\",\\n            \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"value\\\": \\\"never-run\\\"}},\\n        },\\n        user=_StubUser(user_id),\\n    )\\n    job = await job_service.get_job_by_job_id(job_id)\\n    metadata = dict(job.job_metadata)\\n    metadata[\\\"request_overrides\\\"] = \\\"not-a-fernet-token-\\\\N{SNOWMAN}\\\"\\n    await job_service.update_job_metadata(job_id, metadata, replace=True)\\n\\n    ran: list[dict] = []\\n    restart = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_capture_request_factory(ran),\\n    )\\n    await restart.sweep_orphans_on_startup()\\n    await restart.stop()\\n\\n    failed = await job_service.get_job_by_job_id(job_id)\\n    assert all(captured.get(\\\"flow_id\\\") != str(flow_id) for captured in ran)\\n    assert failed.status == JobStatus.FAILED\\n    assert failed.error == {\\\"type\\\": \\\"request_overrides_unavailable\\\"}\\n    assert [(event.event_type, event.payload) for event in await job_service.read_events(job_id, after_seq=0)] == [\\n        (\\\"run_failed\\\", {\\\"type\\\": \\\"request_overrides_unavailable\\\"})\\n    ]\\n\\n\\nasync def test_startup_terminalizes_authenticated_unparseable_override_payload(real_services_job_service):\\n    \\\"\\\"\\\"Authenticated JSON parser-limit failures cannot abort the startup sweep or retain its lease.\\\"\\\"\\\"\\n    from langflow.services.auth.utils import get_fernet\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    flow_id, job_id = uuid4(), uuid4()\\n    plaintext = (\\n        '{\\\"version\\\":1,\\\"job_id\\\":\\\"'\\n        + str(job_id)\\n        + '\\\",\\\"flow_id\\\":\\\"'\\n        + str(flow_id)\\n        + '\\\",\\\"overrides\\\":{\\\"tweaks\\\":{\\\"Node-x\\\":{\\\"value\\\":'\\n        + \\\"9\\\" * 5000\\n        + \\\"}}}}\\\"\\n    )\\n    ciphertext = get_fernet(settings_service).encrypt(plaintext.encode()).decode()\\n    await job_service.create_job(\\n        job_id=job_id,\\n        flow_id=flow_id,\\n        user_id=uuid4(),\\n        initial_metadata={\\n            \\\"request\\\": {\\n                \\\"flow_id\\\": str(flow_id),\\n                \\\"mode\\\": \\\"background\\\",\\n                \\\"stream_protocol\\\": \\\"langflow\\\",\\n            },\\n            \\\"request_overrides_format\\\": \\\"fernet-json-v1\\\",\\n            \\\"request_overrides\\\": ciphertext,\\n        },\\n    )\\n\\n    restart = BackgroundExecutionService(settings_service=settings_service, frame_source_factory=_echo_input_factory)\\n    await restart.sweep_orphans_on_startup()\\n    await restart.stop()\\n\\n    failed = await job_service.get_job_by_job_id(job_id)\\n    assert failed.status == JobStatus.FAILED\\n    assert failed.error == {\\\"type\\\": \\\"request_overrides_unavailable\\\"}\\n    assert failed.finished_timestamp is not None\\n    assert [(event.event_type, event.payload) for event in await job_service.read_events(job_id, after_seq=0)] == [\\n        (\\\"run_failed\\\", {\\\"type\\\": \\\"request_overrides_unavailable\\\"})\\n    ]\\n\\n\\nasync def test_startup_releases_lease_for_transient_authenticated_parser_failure(\\n    real_services_job_service, monkeypatch\\n):\\n    \\\"\\\"\\\"Transient parser resource failures keep an authenticated job queued for retry.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    flow_id, user_id = uuid4(), uuid4()\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_echo_input_factory,\\n        backend=_RecordingBackend(),\\n    )\\n    job_id = await submitter.submit(\\n        flow_id=flow_id,\\n        request={\\n            \\\"flow_id\\\": str(flow_id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": \\\"langflow\\\",\\n            \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"value\\\": \\\"retry-after-resource-recovery\\\"}},\\n        },\\n        user=_StubUser(user_id),\\n    )\\n    monkeypatch.setattr(\\n        \\\"langflow.services.background_execution.service.json.loads\\\",\\n        lambda _plaintext: (_ for _ in ()).throw(MemoryError),\\n    )\\n\\n    ran: list[dict] = []\\n    restart = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_capture_request_factory(ran),\\n    )\\n    await restart.sweep_orphans_on_startup()\\n    await restart.stop()\\n\\n    queued = await job_service.get_job_by_job_id(job_id)\\n    assert ran == []\\n    assert queued.status == JobStatus.QUEUED\\n    assert queued.error is None\\n    assert queued.finished_timestamp is None\\n    assert (queued.job_metadata or {}).get(\\\"owner\\\") is None\\n    assert (queued.job_metadata or {}).get(\\\"heartbeat_at\\\") is None\\n    assert await job_service.read_events(job_id, after_seq=0) == []\\n\\n\\nasync def test_wrong_key_cross_job_and_null_envelopes_fail_closed(real_services_job_service):\\n    \\\"\\\"\\\"Worker hydration rejects wrong-key, cross-job, and nulled ciphertext.\\\"\\\"\\\"\\n    from cryptography.fernet import Fernet\\n    from langflow.services.background_execution.service import (\\n        BackgroundExecutionService,\\n        RequestOverridesUnavailableError,\\n    )\\n    from langflow.services.deps import get_settings_service\\n    from pydantic import SecretStr\\n\\n    job_service = real_services_job_service\\n    backend = _RecordingBackend()\\n    settings_service = get_settings_service()\\n    flow_id = uuid4()\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_echo_input_factory,\\n        backend=backend,\\n    )\\n    job_id = await submitter.submit(\\n        flow_id=flow_id,\\n        request={\\n            \\\"flow_id\\\": str(flow_id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": \\\"langflow\\\",\\n            \\\"input_value\\\": \\\"bound\\\",\\n            \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"bound-secret\\\"}},  # pragma: allowlist secret\\n        },\\n        user=_StubUser(uuid4()),\\n    )\\n    job = await job_service.get_job_by_job_id(job_id)\\n\\n    wrong_auth = settings_service.auth_settings.model_copy(\\n        update={\\\"SECRET_KEY\\\": SecretStr(Fernet.generate_key().decode())}\\n    )\\n    wrong_key_service = BackgroundExecutionService(\\n        settings_service=SimpleNamespace(settings=settings_service.settings, auth_settings=wrong_auth),\\n        frame_source_factory=_echo_input_factory,\\n    )\\n    with pytest.raises(RequestOverridesUnavailableError, match=\\\"Background request overrides are unavailable\\\"):\\n        wrong_key_service._reconstruct_request(job)\\n\\n    other_job_id = uuid4()\\n    await job_service.create_job(\\n        job_id=other_job_id,\\n        flow_id=uuid4(),\\n        user_id=uuid4(),\\n        initial_metadata=job.job_metadata,\\n    )\\n    other_job = await job_service.get_job_by_job_id(other_job_id)\\n    with pytest.raises(RequestOverridesUnavailableError, match=\\\"Background request overrides are unavailable\\\"):\\n        submitter._reconstruct_request(other_job)\\n\\n    null_metadata = dict(job.job_metadata)\\n    null_metadata[\\\"request_overrides\\\"] = None\\n    await job_service.update_job_metadata(job_id, null_metadata, replace=True)\\n    null_job = await job_service.get_job_by_job_id(job_id)\\n    with pytest.raises(RequestOverridesUnavailableError, match=\\\"Background request overrides are unavailable\\\"):\\n        submitter._reconstruct_request(null_job)\\n\\n\\nasync def test_no_overrides_and_safe_legacy_rows_remain_replayable(real_services_job_service):\\n    \\\"\\\"\\\"New empty envelopes and old rows without overrides preserve compatibility.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    backend = _RecordingBackend()\\n    flow_id = uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"no-overrides\\\",\\n        # API model defaults: these must not create an envelope for an ordinary run.\\n        \\\"globals\\\": {},\\n        \\\"tweaks\\\": {},\\n    }\\n    svc = BackgroundExecutionService(\\n        settings_service=get_settings_service(), frame_source_factory=_echo_input_factory, backend=backend\\n    )\\n    job_id = await svc.submit(flow_id=flow_id, request=request, user=_StubUser(uuid4()))\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert \\\"request_overrides_format\\\" not in job.job_metadata\\n    assert \\\"request_overrides\\\" not in job.job_metadata\\n    safe_request = {key: value for key, value in request.items() if key not in {\\\"globals\\\", \\\"tweaks\\\"}}\\n    assert svc._reconstruct_request(job) == safe_request\\n\\n    legacy_id = uuid4()\\n    legacy_request = {**safe_request, \\\"globals\\\": {}, \\\"tweaks\\\": {}}\\n    await job_service.create_job(\\n        job_id=legacy_id,\\n        flow_id=flow_id,\\n        user_id=uuid4(),\\n        initial_metadata={\\\"request\\\": legacy_request},\\n    )\\n    legacy = await job_service.get_job_by_job_id(legacy_id)\\n    assert svc._reconstruct_request(legacy) == safe_request\\n\\n\\nasync def test_legacy_empty_overrides_restart_safely(real_services_job_service):\\n    \\\"\\\"\\\"A queued pre-fix v2 row with empty override defaults remains recoverable.\\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    flow_id, job_id = uuid4(), uuid4()\\n    safe_request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"legacy-empty-restart\\\",\\n    }\\n    await job_service.create_job(\\n        job_id=job_id,\\n        flow_id=flow_id,\\n        user_id=uuid4(),\\n        initial_metadata={\\\"request\\\": {**safe_request, \\\"globals\\\": {}, \\\"tweaks\\\": {}}},\\n    )\\n\\n    captured: list[dict] = []\\n    restart = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_capture_request_factory(captured),\\n    )\\n    await restart.start()\\n    try:\\n        await restart.sweep_orphans_on_startup()\\n        for _ in range(100):\\n            recovered = await job_service.get_job_by_job_id(job_id)\\n            if recovered.status in {JobStatus.COMPLETED, JobStatus.FAILED}:\\n                break\\n            await asyncio.sleep(0.05)\\n    finally:\\n        await restart.stop()\\n\\n    assert captured.count(safe_request) == 1\\n    assert recovered.status == JobStatus.COMPLETED\\n\\n\\nasync def test_legacy_plaintext_overrides_are_not_replayed(real_services_job_service):\\n    \\\"\\\"\\\"A pre-fix plaintext override row cannot bypass the encrypted envelope contract.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import (\\n        BackgroundExecutionService,\\n        RequestOverridesUnavailableError,\\n    )\\n    from langflow.services.deps import get_settings_service\\n\\n    flow_id = uuid4()\\n    job_id = uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"legacy\\\",\\n        \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"legacy-plaintext-secret\\\"}},  # pragma: allowlist secret\\n    }\\n    await real_services_job_service.create_job(\\n        job_id=job_id,\\n        flow_id=flow_id,\\n        user_id=uuid4(),\\n        initial_metadata={\\\"request\\\": request},\\n    )\\n    svc = BackgroundExecutionService(settings_service=get_settings_service(), frame_source_factory=_echo_input_factory)\\n    job = await real_services_job_service.get_job_by_job_id(job_id)\\n    with pytest.raises(RequestOverridesUnavailableError, match=\\\"Background request overrides are unavailable\\\"):\\n        svc._reconstruct_request(job)\\n\\n\\nasync def test_requeued_queued_job_replays_original_input(real_services_job_service):\\n    \\\"\\\"\\\"A QUEUED job that survives a restart re-runs with its ORIGINAL input.\\n\\n    Models \\\"queued, never started, then the process died\\\": the durable row is\\n    QUEUED with the request persisted exactly as ``submit`` writes it (create_job\\n    + update_job_metadata(request)). A *fresh* facade (empty in-memory state, as\\n    after a restart) sweeps and re-enqueues, and the run replays the ORIGINAL\\n    ``input_value`` \u2014 visible in the durable ``job_events`` log. On both real\\n    SQLite and real Postgres.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    original_input = f\\\"original-input-{uuid4()}\\\"\\n    user_id = uuid4()\\n    flow_id = uuid4()\\n    job_id = uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": original_input,\\n        \\\"session_id\\\": \\\"thread-restart\\\",\\n    }\\n    # Durable state a restart finds: a QUEUED row carrying the persisted request,\\n    # written exactly the way ``submit`` writes it.\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    await job_service.update_job_metadata(job_id, {\\\"request\\\": request})\\n\\n    # Restart: a brand-new facade with empty in-memory state sweeps + re-enqueues.\\n    restart_svc = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_echo_input_factory,\\n    )\\n    await restart_svc.start()\\n    try:\\n        await restart_svc.sweep_orphans_on_startup()\\n        job = None\\n        for _ in range(100):\\n            job = await job_service.get_job_by_job_id(job_id)\\n            if job.status == JobStatus.COMPLETED:\\n                break\\n            await asyncio.sleep(0.05)\\n        assert job.status == JobStatus.COMPLETED\\n    finally:\\n        await restart_svc.stop()\\n\\n    # The re-enqueued run replayed the ORIGINAL input, not a default.\\n    events = await job_service.read_events(job_id, after_seq=0)\\n    echoed = [e.payload.get(\\\"data\\\", {}).get(\\\"input_value\\\") for e in events if e.event_type == \\\"add_message\\\"]\\n    assert echoed == [original_input]\\n\\n\\nasync def test_job_timeout_marks_timed_out(real_services_job_service):\\n    \\\"\\\"\\\"A run that overruns ``background_job_timeout`` ends TIMED_OUT.\\n\\n    The runner wraps the drive in ``asyncio.wait_for(timeout=...)``;\\n    ``execute_with_status`` maps ``asyncio.TimeoutError`` to TIMED_OUT. We use a\\n    scripted source that sleeps far longer than the short configured timeout, so\\n    the timeout fires deterministically without any LLM call. The durable log\\n    must carry a terminal milestone too. Real SQLite and real Postgres.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    async def slow_source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        # Overrun the configured timeout by a wide margin.\\n        await asyncio.sleep(30)\\n        yield _frame(\\\"end\\\", {})\\n\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=adapter,\\n        frame_source=slow_source,\\n        job_timeout=0.2,\\n    )\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.TIMED_OUT\\n\\n\\nasync def test_events_reattach_after_restart_returns_on_terminal_job(real_services_job_service):\\n    \\\"\\\"\\\"Reattaching to an already-terminal job after a restart MUST NOT hang.\\n\\n    Models a process restart: a job runs to COMPLETED, persisting durable\\n    milestones, then the process dies. A brand-new facade (fresh in-memory live\\n    bus, empty ``_closed`` markers) is created bound to the SAME DB and a client\\n    reattaches via ``events()``. The facade must consult the DURABLE job status,\\n    see it is terminal, replay the durable milestones, and RETURN \u2014 not block on\\n    ``while True: queue.get()`` waiting for a live tail that will never come.\\n\\n    The ``asyncio.wait_for`` guard turns the hang into a test failure rather than\\n    a hung suite. Proven on real SQLite and real Postgres.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id = uuid4()\\n    flow_id = uuid4()\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    # Run to terminal on a first bus (the \\\"pre-restart\\\" process).\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.COMPLETED\\n\\n    # Restart: a fresh facade with an empty in-memory bus, bound to the same DB.\\n    restart_svc = BackgroundExecutionService(settings_service=get_settings_service())\\n    user = _StubUser(user_id)\\n\\n    async def _collect() -> list[bytes]:\\n        return [frame async for frame in restart_svc.events(job_id, None, user)]\\n\\n    # A hang here (the bug) is caught by wait_for instead of stalling the suite.\\n    frames = await asyncio.wait_for(_collect(), timeout=5.0)\\n\\n    body = b\\\"\\\".join(frames)\\n    assert b\\\"build_start\\\" in body\\n    assert b\\\"end_vertex\\\" in body\\n    assert b\\\"end\\\" in body\\n\\n\\nasync def test_events_replay_frames_are_sse_framed(real_services_job_service):\\n    \\\"\\\"\\\"Durable replay must emit SSE-framed bytes byte-compatible with live frames.\\n\\n    Live frames are pre-SSE-framed with a ``data:`` line followed by an ``id:``\\n    line. A reattach to a terminal job replays durable rows; those replayed bytes\\n    must be the SAME wire shape so a client's ``Last-Event-ID`` resume works and\\n    the frames are not a different (bare-JSON) format. We assert each replayed\\n    frame starts with ``data:`` and carries ``id: <seq>``. Real SQLite and real\\n    Postgres.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id = uuid4()\\n    flow_id = uuid4()\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service())\\n    user = _StubUser(user_id)\\n\\n    async def _collect() -> list[bytes]:\\n        return [frame async for frame in svc.events(job_id, None, user)]\\n\\n    frames = await asyncio.wait_for(_collect(), timeout=5.0)\\n    assert len(frames) == 3\\n    for seq, frame in enumerate(frames, start=1):\\n        assert frame.startswith(b\\\"data:\\\"), f\\\"replayed frame not SSE-framed: {frame!r}\\\"\\n        assert f\\\"id: {seq}\\\".encode() in frame, f\\\"replayed frame missing id: {frame!r}\\\"\\n\\n\\nasync def test_executor_stop_applies_terminal_reconcile(real_services_job_service):\\n    \\\"\\\"\\\"``executor.stop()`` lets an in-flight stopped job's reconcile land.\\n\\n    Drives the REAL runner on the executor. The job blocks mid-run; a STOP signal\\n    is written, then ``executor.stop()`` tears the pool down. stop() cancels and\\n    gathers the in-flight task so the runner's shielded terminal reconcile applies\\n    BEFORE it returns, and the durable row reads CANCELLED. The job swallows its\\n    cancellation (user-stop path): stop() cancels the job task directly and\\n    gathers it rather than waiting on the worker's absorbed-cancel ``await``,\\n    which leaves the worker in cancellation limbo and stalls teardown. The\\n    ``wait_for`` budget plus pytest-timeout turn that stall into a failure. Real\\n    SQLite and Postgres.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.executor import InProcessExecutor\\n\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    started = asyncio.Event()\\n    release = asyncio.Event()\\n\\n    async def blocking_source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        started.set()\\n        await release.wait()  # block until cancelled\\n        yield _frame(\\\"end\\\", {})  # unreachable\\n\\n    bus = InMemoryLiveBus()\\n    runner = _runner(job_service, bus, job_id, blocking_source)\\n    executor = InProcessExecutor(max_concurrency=1)\\n    await executor.start()\\n\\n    async def _coro() -> None:\\n        await runner.run(job_id=job_id, source_kwargs={})\\n\\n    await executor.submit(str(job_id), _coro)\\n    await asyncio.wait_for(started.wait(), timeout=5.0)\\n\\n    await job_service.write_signal(job_id, SignalType.STOP)\\n    # The fixed stop() (cancel+gather job tasks first) returns in well under a\\n    # second. The original ordering (await workers first) leaves the worker in\\n    # cancellation limbo behind the job's swallowed cancel and only unblocks once\\n    # the reconcile's DB writes drain through lock backoff (many seconds), so a\\n    # tight budget here reliably distinguishes the two.\\n    await asyncio.wait_for(executor.stop(), timeout=5.0)\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.CANCELLED\\n\\n\\nasync def test_stop_poll_only_on_durable_frames(real_services_job_service):\\n    \\\"\\\"\\\"The runner polls the STOP signal only on DURABLE frames, not every token.\\n\\n    Polling ``unconsumed_signals`` (a DB read) on every ephemeral token is wasted\\n    work \u2014 a stop is only honored at vertex/milestone boundaries anyway. We count\\n    real ``unconsumed_signals`` DB calls (a thin instrumented subclass that still\\n    hits the real DB) while driving a source with many ephemeral tokens and a few\\n    durable frames, and assert the poll count tracks the durable frames, not the\\n    token flood. Real SQLite and Postgres.\\n    \\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    class _CountingJobService(type(job_service)):\\n        poll_count = 0\\n\\n        async def unconsumed_signals(self, jid):\\n            type(self).poll_count += 1\\n            return await super().unconsumed_signals(jid)\\n\\n    counting = _CountingJobService()\\n\\n    n_tokens = 20\\n    n_durable = 3  # build_start, end_vertex, end\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        for i in range(n_tokens):\\n            yield _frame(\\\"token\\\", {\\\"chunk\\\": str(i)})  # ephemeral\\n        yield _frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(counting, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.COMPLETED\\n    # Polls must not scale with the token flood. Allow the durable-frame polls\\n    # plus the runner's final post-loop / reconcile checks, but never one-per-token.\\n    assert _CountingJobService.poll_count <= n_durable + 3, (\\n        f\\\"stop polled {_CountingJobService.poll_count} times for {n_tokens} tokens (per-token poll)\\\"\\n    )\\n\\n\\nasync def test_stop_signal_is_marked_consumed(real_services_job_service):\\n    \\\"\\\"\\\"When the runner acts on a STOP, the signal row is stamped ``consumed_at``.\\n\\n    Otherwise the execution_signals table grows unbounded and, worse, a\\n    re-enqueued job self-cancels off the stale STOP. We assert two things:\\n    (1) after a stopped run the STOP row has ``consumed_at`` set, and\\n    (2) a fresh run of the SAME job_id afterwards does NOT instantly cancel \u2014\\n    it completes, because the stale STOP was consumed. Real SQLite and Postgres.\\n    \\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await job_service.write_signal(job_id, SignalType.STOP)\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus = InMemoryLiveBus()\\n    await _runner(job_service, bus, job_id, source).run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.CANCELLED\\n\\n    # The STOP signal must now be consumed (no unconsumed rows remain).\\n    remaining = await job_service.unconsumed_signals(job_id)\\n    assert remaining == [], \\\"STOP signal was not stamped consumed_at\\\"\\n\\n    # Re-enqueue path: bring the row back to QUEUED and re-run. A stale STOP would\\n    # instantly cancel it; since it was consumed, the fresh run completes.\\n    await job_service.update_job_status(job_id, JobStatus.QUEUED)\\n\\n    async def source2(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        yield _frame(\\\"build_start\\\", {})\\n        yield _frame(\\\"end\\\", {})\\n\\n    bus2 = InMemoryLiveBus()\\n    await _runner(job_service, bus2, job_id, source2).run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.COMPLETED, \\\"re-run self-cancelled off a stale STOP\\\"\\n\\n\\ndef _side_effect_factory(*, request, **_kwargs):  # noqa: ARG001\\n    \\\"\\\"\\\"Frame source that emits exactly one durable ``add_message`` side effect.\\n\\n    Counting the durable ``add_message`` rows for the job is an exactly-once\\n    probe: if two sweepers both re-enqueue the same QUEUED job, the run fires\\n    twice and two rows land; a single-flight claim leaves exactly one.\\n    \\\"\\\"\\\"\\n\\n    async def _source(**_kw):\\n        yield _frame(\\\"add_message\\\", {\\\"marker\\\": \\\"ran\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\nasync def test_concurrent_sweep_runs_queued_job_exactly_once(real_services_job_service):\\n    \\\"\\\"\\\"Two startup sweepers sharing one DB must run a QUEUED job EXACTLY once.\\n\\n    Models two uvicorn workers booting against the same database, each calling\\n    ``sweep_orphans_on_startup`` concurrently on the same QUEUED row. Without a\\n    single-flight claim both re-enqueue the row and the non-idempotent flow runs\\n    twice (two durable side-effect rows). The per-row conditional claim\\n    (UPDATE ... WHERE status='QUEUED') lets exactly one sweeper win, so the side\\n    effect happens exactly once. Real SQLite and real Postgres.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id = uuid4()\\n    flow_id = uuid4()\\n    job_id = uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"x\\\",\\n        \\\"session_id\\\": \\\"thread-restart\\\",\\n    }\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    await job_service.update_job_metadata(job_id, {\\\"request\\\": request})\\n\\n    svc_a = BackgroundExecutionService(\\n        settings_service=get_settings_service(), frame_source_factory=_side_effect_factory\\n    )\\n    svc_b = BackgroundExecutionService(\\n        settings_service=get_settings_service(), frame_source_factory=_side_effect_factory\\n    )\\n    await svc_a.start()\\n    await svc_b.start()\\n    try:\\n        # Both sweep at once: only one may claim and run the QUEUED row.\\n        await asyncio.gather(svc_a.sweep_orphans_on_startup(), svc_b.sweep_orphans_on_startup())\\n\\n        job = None\\n        for _ in range(100):\\n            job = await job_service.get_job_by_job_id(job_id)\\n            if job.status == JobStatus.COMPLETED:\\n                break\\n            await asyncio.sleep(0.05)\\n        assert job.status == JobStatus.COMPLETED\\n    finally:\\n        await svc_a.stop()\\n        await svc_b.stop()\\n\\n    events = await job_service.read_events(job_id, after_seq=0)\\n    markers = [e for e in events if e.event_type == \\\"add_message\\\"]\\n    assert len(markers) == 1, f\\\"QUEUED job ran {len(markers)} times, expected exactly 1\\\"\\n\\n\\nclass _StubUser:\\n    \\\"\\\"\\\"Minimal user carrying only ``id`` (all the facade submit path reads).\\\"\\\"\\\"\\n\\n    def __init__(self, user_id):\\n        self.id = user_id\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_head_to_head_deltas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b2b8ba12eefb8b0621eb2fc6e2f5dbb3beee73ac37d6335fec29afa20f97c24d\",\"content\":\"\\\"\\\"\\\"HEAD-TO-HEAD failure reproductions: each safeguard OFF reproduces the failure.\\n\\nPer the \\\"reproduce the failure with the safeguard OFF, then assert the delta with\\nit ON\\\" rule, each test runs the SAME scenario twice \u2014 once with the safeguard\\ndisabled (the pre-fix behavior, which must exhibit the BAD outcome) and once with\\nit enabled (the GOOD outcome). The proof is the measured delta, not a lone green\\ncheck.\\n\\nThree safeguards:\\n\\n1. Bounded executor pool. OFF (unbounded fan-out) -> peak in-flight == load;\\n   ON (``InProcessExecutor(max_concurrency=N)``) -> peak == N.\\n2. Durable submit. OFF (request never persisted) -> a restart finds no QUEUED row\\n   to recover, so the job is LOST; ON (request persisted on the row) -> a fresh\\n   facade recovers and re-runs it.\\n3. Single-flight sweep claim. OFF (unconditional re-enqueue) -> two startup\\n   sweepers both run a QUEUED job, DOUBLE side effect; ON\\n   (``claim_queued_job`` conditional UPDATE) -> exactly once.\\n\\nReal ``InProcessExecutor`` and real ``JobService`` on real SQLite + Postgres.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport threading\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.executor import InProcessExecutor\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\npytestmark = pytest.mark.real_services\\n\\n\\n# --------------------------------------------------------------------------- #\\n# 1. Bounded executor pool: OFF swamps; ON caps at N.\\n# --------------------------------------------------------------------------- #\\n\\n\\nclass _PeakProbe:\\n    \\\"\\\"\\\"Thread/loop-safe peak in-flight tracker.\\\"\\\"\\\"\\n\\n    def __init__(self) -> None:\\n        self._lock = threading.Lock()\\n        self.current = 0\\n        self.peak = 0\\n\\n    def enter(self) -> None:\\n        with self._lock:\\n            self.current += 1\\n            self.peak = max(self.peak, self.current)\\n\\n    def exit(self) -> None:\\n        with self._lock:\\n            self.current -= 1\\n\\n\\nasync def _run_load_unbounded(load: int, probe: _PeakProbe, release: asyncio.Event) -> None:\\n    \\\"\\\"\\\"The pre-fix behavior: every submitted job gets its own task immediately.\\\"\\\"\\\"\\n\\n    async def _job() -> None:\\n        probe.enter()\\n        try:\\n            await asyncio.wait_for(release.wait(), timeout=10)\\n        finally:\\n            probe.exit()\\n\\n    tasks = [asyncio.create_task(_job()) for _ in range(load)]\\n    # Let them all reach the barrier.\\n    for _ in range(100):\\n        if probe.peak >= load:\\n            break\\n        await asyncio.sleep(0.01)\\n    release.set()\\n    await asyncio.gather(*tasks, return_exceptions=True)\\n\\n\\nasync def _run_load_bounded(load: int, concurrency: int, probe: _PeakProbe, release: asyncio.Event) -> None:\\n    \\\"\\\"\\\"The fix: the bounded ``InProcessExecutor`` caps in-flight at ``concurrency``.\\\"\\\"\\\"\\n    executor = InProcessExecutor(max_concurrency=concurrency)\\n    await executor.start()\\n\\n    async def _job() -> None:\\n        probe.enter()\\n        try:\\n            await asyncio.wait_for(release.wait(), timeout=10)\\n        finally:\\n            probe.exit()\\n\\n    try:\\n        for i in range(load):\\n            await executor.submit(f\\\"job-{i}\\\", _job)\\n        # Give the pool time to saturate; peak must never exceed the cap.\\n        for _ in range(100):\\n            if probe.current >= concurrency:\\n                break\\n            await asyncio.sleep(0.01)\\n        await asyncio.sleep(0.3)\\n        release.set()\\n    finally:\\n        release.set()\\n        await executor.stop()\\n\\n\\nasync def test_bounded_pool_delta_off_swamps_on_caps():\\n    \\\"\\\"\\\"Bounded pool OFF: peak == load (swamped). ON: peak == N (capped). Measured delta.\\\"\\\"\\\"\\n    n = 3\\n    load = 9\\n\\n    off_probe = _PeakProbe()\\n    await _run_load_unbounded(load, off_probe, asyncio.Event())\\n\\n    on_probe = _PeakProbe()\\n    await _run_load_bounded(load, n, on_probe, asyncio.Event())\\n\\n    # BAD (safeguard off): unbounded fan-out runs every job at once.\\n    assert off_probe.peak == load, f\\\"unbounded peak should be {load}, got {off_probe.peak}\\\"\\n    # GOOD (safeguard on): the bounded pool never exceeds the cap.\\n    assert on_probe.peak == n, f\\\"bounded peak should be {n}, got {on_probe.peak}\\\"\\n    assert off_probe.peak > on_probe.peak, \\\"no delta between unbounded and bounded\\\"\\n    print(  # noqa: T201\\n        f\\\"PROOF[h2h/bounded-pool]: OFF peak={off_probe.peak} (==load {load}, swamped) vs \\\"\\n        f\\\"ON peak={on_probe.peak} (==cap {n}); DELTA={off_probe.peak - on_probe.peak} fewer concurrent\\\"\\n    )\\n\\n\\n# --------------------------------------------------------------------------- #\\n# 2. Durable submit: OFF loses the job on restart; ON recovers it.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _echo_factory(*, request, **_kwargs):\\n    \\\"\\\"\\\"A frame source that echoes the request's input into a durable add_message.\\\"\\\"\\\"\\n    input_value = request.get(\\\"input_value\\\")\\n\\n    async def _source(**_kw):\\n        import json\\n\\n        yield (json.dumps({\\\"event\\\": \\\"add_message\\\", \\\"data\\\": {\\\"input_value\\\": input_value}}).encode(), \\\"add_message\\\")\\n        yield (json.dumps({\\\"event\\\": \\\"end\\\", \\\"data\\\": {}}).encode(), \\\"end\\\")\\n\\n    return _source\\n\\n\\nasync def test_durability_delta_off_loses_job_on_restart_on_recovers(real_services_job_service):\\n    \\\"\\\"\\\"Durability OFF: a restart finds NO recoverable row -> job lost. ON: recovered + re-run.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n\\n    # --- OFF: the in-memory-only path (pre-fix). The submit never wrote a durable\\n    #     QUEUED row \u2014 the job lived only in the dead process's executor queue. A\\n    #     restart's startup sweep has NOTHING to find, so the job is fully LOST:\\n    #     no row, no run, no events. We model this by simply not persisting the\\n    #     job at all, then booting a fresh facade and showing recovery is a no-op.\\n    off_job = uuid4()\\n    restart_off = BackgroundExecutionService(\\n        settings_service=get_settings_service(), frame_source_factory=_echo_factory\\n    )\\n    await restart_off.start()\\n    try:\\n        await restart_off.sweep_orphans_on_startup()\\n        await asyncio.sleep(0.3)  # give any (wrongly) recovered run a chance to fire\\n    finally:\\n        await restart_off.stop()\\n    # BAD: no durable row exists, so the job never recovers and never runs.\\n    off_job_row = await job_service.get_job_by_job_id(off_job)\\n    assert off_job_row is None, \\\"durability-off job should have no durable row to recover\\\"\\n    off_events = await job_service.read_events(off_job, after_seq=0)\\n    assert off_events == [], f\\\"durability-off job should produce no events on restart, got {off_events}\\\"\\n\\n    # --- ON: submit WITH the request persisted (the fix). A restart recovers and\\n    #     re-runs with the ORIGINAL input.\\n    on_input = f\\\"on-{uuid4()}\\\"\\n    on_job, on_flow, on_user = uuid4(), uuid4(), uuid4()\\n    request = {\\\"flow_id\\\": str(on_flow), \\\"stream_protocol\\\": \\\"langflow\\\", \\\"input_value\\\": on_input}\\n    await job_service.create_job(job_id=on_job, flow_id=on_flow, user_id=on_user)\\n    await job_service.update_job_metadata(on_job, {\\\"request\\\": request})  # durability ON\\n\\n    restart_on = BackgroundExecutionService(settings_service=get_settings_service(), frame_source_factory=_echo_factory)\\n    await restart_on.start()\\n    try:\\n        await restart_on.sweep_orphans_on_startup()\\n        job = None\\n        for _ in range(100):\\n            job = await job_service.get_job_by_job_id(on_job)\\n            if job.status == JobStatus.COMPLETED:\\n                break\\n            await asyncio.sleep(0.05)\\n        assert job.status == JobStatus.COMPLETED\\n    finally:\\n        await restart_on.stop()\\n    on_events = await job_service.read_events(on_job, after_seq=0)\\n    on_echoed = [e.payload.get(\\\"data\\\", {}).get(\\\"input_value\\\") for e in on_events if e.event_type == \\\"add_message\\\"]\\n    # GOOD: the original input survived and re-ran.\\n    assert on_echoed == [on_input], f\\\"recovered run did not replay original input: {on_echoed}\\\"\\n    print(  # noqa: T201\\n        f\\\"PROOF[h2h/durability]: OFF job LOST on restart (no durable row, 0 events) vs \\\"\\n        f\\\"ON recovered+replayed original ({on_echoed}); DELTA = job survives restart only when persisted\\\"\\n    )\\n\\n\\n# --------------------------------------------------------------------------- #\\n# 3. Single-flight sweep claim: OFF double-runs; ON runs exactly once.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _frame(event_type, data):\\n    import json\\n\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(), event_type)\\n\\n\\ndef _side_effect_factory(*, request, **_kwargs):  # noqa: ARG001\\n    async def _source(**_kw):\\n        yield _frame(\\\"add_message\\\", {\\\"marker\\\": \\\"ran\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\ndef _runner(job_service, job_id, source):\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    return JobRunner(job_service=job_service, live_bus=InMemoryLiveBus(), adapter=adapter, frame_source=source)\\n\\n\\nasync def test_sweep_claim_delta_off_double_runs_on_exactly_once(real_services_job_service):\\n    \\\"\\\"\\\"Sweep claim OFF: two sweepers both run a QUEUED job (double). ON: exactly once.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n\\n    # --- OFF: the pre-fix unconditional re-enqueue. Two sweepers each run the job\\n    #     because neither claims it first. We reproduce by running the runner twice\\n    #     against the SAME job_id, as two unconditional sweepers would.\\n    off_job, off_flow = uuid4(), uuid4()\\n    await job_service.create_job(job_id=off_job, flow_id=off_flow, user_id=uuid4())\\n    src1 = _side_effect_factory(request={})\\n    src2 = _side_effect_factory(request={})\\n    # Unconditional: neither call claims, both run.\\n    await _runner(job_service, off_job, src1).run(job_id=off_job, source_kwargs={})\\n    await job_service.update_job_status(off_job, JobStatus.QUEUED)  # second sweeper sees it QUEUED again\\n    await _runner(job_service, off_job, src2).run(job_id=off_job, source_kwargs={})\\n    off_events = await job_service.read_events(off_job, after_seq=0)\\n    off_markers = [e for e in off_events if e.event_type == \\\"add_message\\\"]\\n    # BAD: the non-idempotent side effect ran twice.\\n    assert len(off_markers) == 2, f\\\"unconditional re-enqueue should double-run, got {len(off_markers)}\\\"\\n\\n    # --- ON: the conditional claim. Two concurrent sweepers race; only the claim\\n    #     winner runs. Exactly once.\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    on_job, on_flow, on_user = uuid4(), uuid4(), uuid4()\\n    request = {\\\"flow_id\\\": str(on_flow), \\\"stream_protocol\\\": \\\"langflow\\\", \\\"input_value\\\": \\\"x\\\"}\\n    await job_service.create_job(job_id=on_job, flow_id=on_flow, user_id=on_user)\\n    await job_service.update_job_metadata(on_job, {\\\"request\\\": request})\\n\\n    svc_a = BackgroundExecutionService(\\n        settings_service=get_settings_service(), frame_source_factory=_side_effect_factory\\n    )\\n    svc_b = BackgroundExecutionService(\\n        settings_service=get_settings_service(), frame_source_factory=_side_effect_factory\\n    )\\n    await svc_a.start()\\n    await svc_b.start()\\n    try:\\n        await asyncio.gather(svc_a.sweep_orphans_on_startup(), svc_b.sweep_orphans_on_startup())\\n        job = None\\n        for _ in range(100):\\n            job = await job_service.get_job_by_job_id(on_job)\\n            if job.status == JobStatus.COMPLETED:\\n                break\\n            await asyncio.sleep(0.05)\\n        assert job.status == JobStatus.COMPLETED\\n    finally:\\n        await svc_a.stop()\\n        await svc_b.stop()\\n    on_events = await job_service.read_events(on_job, after_seq=0)\\n    on_markers = [e for e in on_events if e.event_type == \\\"add_message\\\"]\\n    # GOOD: exactly one run.\\n    assert len(on_markers) == 1, f\\\"single-flight claim should run exactly once, got {len(on_markers)}\\\"\\n    print(  # noqa: T201\\n        f\\\"PROOF[h2h/sweep-claim]: OFF ran {len(off_markers)}x (double side effect) vs \\\"\\n        f\\\"ON ran {len(on_markers)}x (claim single-flight); DELTA = {len(off_markers) - len(on_markers)} avoided re-run\\\"\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_hitl_pre_pause_outputs.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bd124a86db07ea6ecf6767dff4c827c3f5536fbfe30935b611c4e77a781fc523\",\"content\":\"\\\"\\\"\\\"Pre-pause terminal outputs survive a HITL resume (Claim 1 fix).\\n\\nA run that produces a terminal output on one branch, then pauses for human input\\non another, must NOT lose that output. On suspend the runner stashes the pre-pause\\ncaptures in ``job_metadata``; on resume it pre-seeds the (otherwise fresh) capture\\nlist from that stash, so the completed-run ``Job.result`` carries both the pre- and\\npost-pause outputs. A resumed pass that re-emits a branch overwrites the stale entry\\nrather than duplicating it (dedup by ``component_id``, resumed pass wins).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import HUMAN_INPUT_REQUIRED_EVENT, JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus, SignalType\\nfrom lfx.graph.checkpoint.schema import GraphCheckpoint\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\nfrom lfx.workflow.adapters.langflow import WORKFLOW_OUTPUT_CAPTURE_EVENT\\n\\n\\ndef _capture_frame(component_id: str, content: str) -> tuple[bytes, str]:\\n    \\\"\\\"\\\"A terminal-output capture frame (off-wire OutputEvent carrying a component id).\\\"\\\"\\\"\\n    payload = {\\\"data\\\": {\\\"component_id\\\": component_id, \\\"type\\\": \\\"message\\\", \\\"content\\\": content}}\\n    return (json.dumps(payload).encode(), WORKFLOW_OUTPUT_CAPTURE_EVENT)\\n\\n\\ndef _pause_frame(payload: dict) -> tuple[bytes, str]:\\n    return (json.dumps(payload).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n\\ndef _end_frame() -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": \\\"end\\\", \\\"data\\\": {}}).encode(), \\\"end\\\")\\n\\n\\ndef _adapter(job_id):\\n    return get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n\\n\\ndef _durable_store(job_service):\\n    from langflow.services.checkpoint.store import JobScopedCheckpointStore\\n\\n    return JobScopedCheckpointStore(job_service)\\n\\n\\ndef _branch_a_then_pause(payload: dict):\\n    \\\"\\\"\\\"Branch A emits a terminal output, then the run pauses for human input.\\\"\\\"\\\"\\n\\n    async def _source(**_kwargs):\\n        yield _capture_frame(\\\"comp-A\\\", \\\"branch A output\\\")\\n        yield _pause_frame(payload)\\n\\n    return _source\\n\\n\\nasync def _noop_hook(_checkpoint, _decision):\\n    return None\\n\\n\\nasync def _suspend_with_branch_a(job_service, job_id, *, request_id=\\\"req-1\\\"):\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": request_id, \\\"options\\\": [\\\"approve\\\"]}\\n    runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=_adapter(job_id),\\n        frame_source=_branch_a_then_pause(payload),\\n    )\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n\\nasync def _arm_resume(job_service, job_id, *, request_id=\\\"req-1\\\"):\\n    store = _durable_store(job_service)\\n    await store.save(\\n        GraphCheckpoint(\\n            run_id=str(job_id),\\n            job_id=str(job_id),\\n            flow_id=\\\"flow-1\\\",\\n            session_id=\\\"sess-1\\\",\\n            flow_payload={\\\"nodes\\\": [], \\\"edges\\\": []},\\n            vertices_to_run={\\\"comp-B\\\"},\\n        )\\n    )\\n    await job_service.write_signal(\\n        job_id, SignalType.RESUME, {\\\"decision\\\": {\\\"choice\\\": \\\"approve\\\"}, \\\"request_id\\\": request_id}\\n    )\\n    return store\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_stashes_pre_pause_outputs(real_services_job_service) -> None:\\n    \\\"\\\"\\\"The suspend path records the pre-pause terminal outputs in job_metadata.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    await _suspend_with_branch_a(job_service, job_id)\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    assert job.result is None  # not finalized\\n    stash = (job.job_metadata or {}).get(\\\"pre_pause_outputs\\\")\\n    assert stash is not None\\n    assert [e[\\\"component_id\\\"] for e in stash] == [\\\"comp-A\\\"]\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_pre_pause_output_survives_into_completed_result(real_services_job_service) -> None:\\n    \\\"\\\"\\\"After resume completes, Job.result carries BOTH the pre-pause and post-pause outputs.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    await _suspend_with_branch_a(job_service, job_id)\\n    store = await _arm_resume(job_service, job_id)\\n\\n    def _branch_b_then_end():\\n        async def _source(**_kwargs):\\n            yield _capture_frame(\\\"comp-B\\\", \\\"branch B output\\\")\\n            yield _end_frame()\\n\\n        return _source\\n\\n    resume_runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=_adapter(job_id),\\n        frame_source=_branch_b_then_end(),\\n        resume_hook=_noop_hook,\\n        checkpoint_store=store,\\n    )\\n    await resume_runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.COMPLETED\\n    outputs = job.result[\\\"outputs\\\"]\\n    # Branch A preserved and ahead of branch B (first-seen position, no loss).\\n    assert [o[\\\"component_id\\\"] for o in outputs] == [\\\"comp-A\\\", \\\"comp-B\\\"]\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resumed_reemit_overwrites_stale_entry_without_duplicate(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A vertex re-emitted after resume overwrites its pre-pause value \u2014 no duplicate row.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    await _suspend_with_branch_a(job_service, job_id)\\n    store = await _arm_resume(job_service, job_id)\\n\\n    def _reemit_a_then_b():\\n        async def _source(**_kwargs):\\n            yield _capture_frame(\\\"comp-A\\\", \\\"branch A RE-EMITTED\\\")\\n            yield _capture_frame(\\\"comp-B\\\", \\\"branch B output\\\")\\n            yield _end_frame()\\n\\n        return _source\\n\\n    resume_runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=_adapter(job_id),\\n        frame_source=_reemit_a_then_b(),\\n        resume_hook=_noop_hook,\\n        checkpoint_store=store,\\n    )\\n    await resume_runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    outputs = job.result[\\\"outputs\\\"]\\n    assert [o[\\\"component_id\\\"] for o in outputs] == [\\\"comp-A\\\", \\\"comp-B\\\"]  # no duplicate comp-A\\n    comp_a = next(o for o in outputs if o[\\\"component_id\\\"] == \\\"comp-A\\\")\\n    assert comp_a[\\\"content\\\"] == \\\"branch A RE-EMITTED\\\"  # resumed pass wins\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_hitl_suspended_signals.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"502fc6a5a4c3538eb2a32a097094e3944a0502dea1abf2971fe3d20da1a9a9f8\",\"content\":\"\\\"\\\"\\\"HITL substrate enums: SUSPENDED job status + PAUSE/RESUME signals (LE-1438).\\n\\nSlice 1 (unit): the enum members exist on both the langflow models and the lfx\\nmirror, so the later suspend/resume features have values to write and consume.\\n\\nSlice 2 (real_services, load-bearing): a real INSERT of a ``suspended`` job and\\n``pause``/``resume`` signals against a REAL migrated DB commits and reads back\\nequal on BOTH SQLite and Postgres. A Python enum-membership check passes even if\\nthe Postgres ``ALTER TYPE ... ADD VALUE`` never ran, so only a real insert\\nagainst the native enum types proves the migration added the values.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.jobs.model import JobStatus, SignalType\\n\\n\\ndef test_should_expose_suspended_when_reading_job_status_enum() -> None:\\n    assert JobStatus.SUSPENDED.value == \\\"suspended\\\"\\n\\n\\ndef test_should_expose_pause_and_resume_when_reading_signal_type_enum() -> None:\\n    assert SignalType.PAUSE.value == \\\"pause\\\"\\n    assert SignalType.RESUME.value == \\\"resume\\\"\\n\\n\\ndef test_should_keep_prior_members_when_adding_hitl_values() -> None:\\n    assert SignalType.STOP.value == \\\"stop\\\"\\n    assert {s.value for s in JobStatus} >= {\\n        \\\"queued\\\",\\n        \\\"in_progress\\\",\\n        \\\"completed\\\",\\n        \\\"failed\\\",\\n        \\\"cancelled\\\",\\n        \\\"timed_out\\\",\\n        \\\"suspended\\\",\\n    }\\n\\n\\ndef test_should_mirror_suspended_in_lfx_job_status_copy() -> None:\\n    from lfx.schema.workflow import JobStatus as LfxJobStatus\\n\\n    assert LfxJobStatus.SUSPENDED.value == \\\"suspended\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_should_persist_suspended_status_when_inserted_into_migrated_db(\\n    real_services_job_service,\\n) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.update_job_status(job_id, JobStatus.SUSPENDED)\\n\\n    fetched = await service.get_job_by_job_id(job_id)\\n    assert fetched.status == JobStatus.SUSPENDED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_should_persist_pause_and_resume_signals_when_inserted_into_migrated_db(\\n    real_services_job_service,\\n) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.write_signal(job_id, SignalType.PAUSE, {\\\"request_id\\\": \\\"r1\\\"})\\n    await service.write_signal(job_id, SignalType.RESUME, {\\\"request_id\\\": \\\"r1\\\", \\\"decision\\\": \\\"approve\\\"})\\n\\n    signals = await service.unconsumed_signals(job_id)\\n    by_type = {s.signal_type: s.data for s in signals}\\n    assert by_type[SignalType.PAUSE] == {\\\"request_id\\\": \\\"r1\\\"}\\n    assert by_type[SignalType.RESUME] == {\\\"request_id\\\": \\\"r1\\\", \\\"decision\\\": \\\"approve\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_input_deadline.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"37cc28fe81990156c6e72fe71994cb374b00ef1d993f8673a0ff952311ef6fa3\",\"content\":\"\\\"\\\"\\\"Input deadline for suspended HITL runs (LE-1452) against a real JobService.\\n\\nTwo independent halves: (1) paused time never counts against the compute timeout \u2014\\na run resumed after sitting suspended still completes; (2) an optional\\n``background_input_deadline_s`` budget that the sweep enforces by FAILing overdue\\nSUSPENDED rows with ``input_timed_out`` (terminal status + durable event + closed bus).\\n\\nThe deadline is simulated deterministically (no sleeps) by stamping the run with a\\nnegative budget so its ``input_deadline_at`` is already in the past.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import HUMAN_INPUT_REQUIRED_EVENT, JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\n\\ndef _frame(event_type: str, data: dict) -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(), event_type)\\n\\n\\ndef _pause_source(payload: dict):\\n    async def _source(**_kwargs):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"working\u2026\\\"})\\n        yield (json.dumps(payload).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n    return _source\\n\\n\\ndef _runner(job_service, job_id, source, *, input_deadline_s=None):\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    return JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=adapter,\\n        frame_source=source,\\n        input_deadline_s=input_deadline_s,\\n    )\\n\\n\\nasync def _suspend_a_job(job_service, *, request_id=\\\"req-1\\\", input_deadline_s=None):\\n    user_id, flow_id, job_id = uuid4(), uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    await job_service.update_job_metadata(job_id, {\\\"request\\\": {\\\"flow_id\\\": str(flow_id), \\\"stream_protocol\\\": \\\"langflow\\\"}})\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": request_id, \\\"options\\\": [\\\"approve\\\", \\\"reject\\\"]}\\n    await _runner(job_service, job_id, _pause_source(payload), input_deadline_s=input_deadline_s).run(\\n        job_id=job_id, source_kwargs={}\\n    )\\n    return user_id, job_id\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_stamps_input_deadline_when_budget_set(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, input_deadline_s=3600)\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    assert (job.job_metadata or {}).get(\\\"input_deadline_at\\\")\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_does_not_stamp_when_budget_disabled(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, input_deadline_s=None)\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert (job.job_metadata or {}).get(\\\"input_deadline_at\\\") is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_sweep_fails_overdue_suspended_run(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, input_deadline_s=-1)\\n\\n    failed = await job_service.sweep_input_deadlines()\\n\\n    assert job_id in failed\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.FAILED\\n    assert job.error == {\\\"type\\\": \\\"input_timed_out\\\"}\\n    assert job.finished_timestamp is not None\\n    events = await job_service.read_events(job_id)\\n    assert any(e.event_type == \\\"input_timed_out\\\" for e in events)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_sweep_leaves_not_yet_due_run_suspended(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, input_deadline_s=3600)\\n\\n    failed = await job_service.sweep_input_deadlines()\\n\\n    assert job_id not in failed\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_sweep_ignores_run_without_deadline(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, input_deadline_s=None)\\n\\n    failed = await job_service.sweep_input_deadlines()\\n\\n    assert job_id not in failed\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_orphan_and_deadline_sweeps_both_spare_a_fresh_suspended_row(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, input_deadline_s=3600)\\n\\n    await job_service.sweep_orphans()\\n    await job_service.sweep_input_deadlines()\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n\\n\\nclass _StubUser:\\n    def __init__(self, user_id):\\n        self.id = user_id\\n\\n\\ndef _completing_factory(**_kwargs):\\n    async def _source(**_kw):\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\nasync def _wait_for_status(job_service, job_id, target, *, attempts=100):\\n    import asyncio\\n\\n    for _ in range(attempts):\\n        job = await job_service.get_job_by_job_id(job_id)\\n        if job is not None and job.status == target:\\n            return job\\n        await asyncio.sleep(0.05)\\n    return await job_service.get_job_by_job_id(job_id)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_paused_time_does_not_count_against_compute_timeout(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A run resumed after sitting suspended still completes.\\n\\n    The compute timeout never accrues across the suspend window (resume re-enqueues a\\n    fresh pass), so a small ``background_job_timeout`` does not kill a resumed run.\\n    \\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-pause\\\", input_deadline_s=None)\\n\\n    settings = get_settings_service().settings\\n    original = settings.background_job_timeout\\n    settings.background_job_timeout = 1.0\\n    svc = BackgroundExecutionService(settings_service=get_settings_service(), frame_source_factory=_completing_factory)\\n    await svc.start()\\n    try:\\n        accepted = await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-pause\\\", decision={\\\"choice\\\": \\\"go\\\"})\\n        assert accepted\\n        job = await _wait_for_status(job_service, job_id, JobStatus.COMPLETED)\\n    finally:\\n        settings.background_job_timeout = original\\n        await svc.stop()\\n\\n    assert job.status == JobStatus.COMPLETED\\n\\n\\ndef test_input_deadline_setting_defaults_none_and_is_independent_of_compute_timeout() -> None:\\n    from lfx.services.settings.groups.runtime import RuntimeSettings\\n\\n    assert RuntimeSettings().background_input_deadline_s is None\\n    configured = RuntimeSettings(background_input_deadline_s=600)\\n    assert configured.background_input_deadline_s == 600.0\\n    assert configured.background_job_timeout is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_input_deadline_races.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"37e70392cf2929d334a312f1c59d8be17f64db206023b61378e7ac6ad8975c47\",\"content\":\"\\\"\\\"\\\"A stale timeout scan must not overwrite a newer HITL decision or deadline.\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timedelta, timezone\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\n@pytest.mark.parametrize(\\\"transition\\\", [\\\"resume\\\", \\\"complete\\\", \\\"cancel\\\", \\\"new_deadline\\\", \\\"other_sweep\\\"])\\nasync def test_stale_input_deadline_scan_preserves_winning_transition(\\n    real_services_job_service, monkeypatch, transition\\n):\\n    \\\"\\\"\\\"Interleave another real transaction after the sweep reads its candidates.\\\"\\\"\\\"\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(job_id, JobStatus.SUSPENDED)\\n    await service.update_job_metadata(\\n        job_id,\\n        {\\\"input_deadline_at\\\": (datetime.now(timezone.utc) - timedelta(seconds=1)).isoformat()},\\n    )\\n    await service.save_checkpoint(job_id, \\\"graph\\\", \\\"saved checkpoint\\\")\\n\\n    original_exec = AsyncSession.exec\\n    scan_read = False\\n\\n    async def exec_with_concurrent_transition(session, statement, *args, **kwargs):\\n        nonlocal scan_read\\n        result = await original_exec(session, statement, *args, **kwargs)\\n        if not scan_read:\\n            scan_read = True\\n            # The first statement is the sweep's SELECT. Its ORM objects remain\\n            # stale while the competing worker commits through a separate session.\\n            if transition == \\\"resume\\\":\\n                assert await service.claim_suspended_for_resume(job_id, owner=\\\"resuming-worker\\\")\\n            elif transition == \\\"complete\\\":\\n                await service.update_job_status(job_id, JobStatus.COMPLETED, finished_timestamp=True)\\n            elif transition == \\\"cancel\\\":\\n                assert await service.claim_suspended_for_cancel(job_id)\\n            elif transition == \\\"new_deadline\\\":\\n                await service.update_job_metadata(\\n                    job_id,\\n                    {\\\"input_deadline_at\\\": (datetime.now(timezone.utc) + timedelta(hours=1)).isoformat()},\\n                )\\n            else:\\n                assert await service.sweep_input_deadlines() == [job_id]\\n        return result\\n\\n    with monkeypatch.context() as context:\\n        context.setattr(AsyncSession, \\\"exec\\\", exec_with_concurrent_transition)\\n        expired = await service.sweep_input_deadlines()\\n\\n    assert expired == []\\n    job = await service.get_job_by_job_id(job_id)\\n    expected_status = {\\n        \\\"resume\\\": JobStatus.IN_PROGRESS,\\n        \\\"complete\\\": JobStatus.COMPLETED,\\n        \\\"cancel\\\": JobStatus.CANCELLED,\\n        \\\"new_deadline\\\": JobStatus.SUSPENDED,\\n        \\\"other_sweep\\\": JobStatus.FAILED,\\n    }[transition]\\n    assert job.status == expected_status\\n    events = await service.read_events(job_id)\\n    timeout_events = [event for event in events if event.event_type == \\\"input_timed_out\\\"]\\n    assert len(timeout_events) == (1 if transition == \\\"other_sweep\\\" else 0)\\n    checkpoint = await service.load_checkpoint(job_id, \\\"graph\\\")\\n    assert checkpoint == (None if transition == \\\"other_sweep\\\" else \\\"saved checkpoint\\\")\\n    if transition != \\\"other_sweep\\\":\\n        assert job.error is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_job_status_enum_consistency.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8fdd45bd57d04bed7ce7981605e02316e42614a94577630a1320497a451ea6bf\",\"content\":\"\\\"\\\"\\\"Drift guard for the JobStatus enum, which is defined in three places.\\n\\n``JobStatus`` is intentionally mirrored across:\\n  - ``lfx.schema.workflow`` \u2014 the public workflow schema,\\n  - ``lfx.services.durable.models`` \u2014 the durable substrate's row models,\\n  - ``langflow.services.database.models.jobs.model`` \u2014 the SQLAlchemy-bound\\n    model whose values persist to the ``job_status_enum`` column.\\n\\nThey compare by value (all are ``str`` enums), but membership / set-building /\\n``isinstance`` checks diverge the moment one copy gains or loses a member. A run\\nsuspended by one runtime must read the same vocabulary when resumed through\\nanother, so the three MUST stay identical. If a future change adds a status to\\none and not the others (as almost happened when ``SUSPENDED`` landed), this test\\nfails in CI instead of silently mistreating a resumable job as terminal.\\n\\nIf/when the three are consolidated into a single canonical enum, delete this test.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom langflow.services.database.models.jobs.model import JobStatus as DbJobStatus\\nfrom lfx.schema.workflow import JobStatus as SchemaJobStatus\\nfrom lfx.services.durable.models import JobStatus as DurableJobStatus\\n\\n\\ndef _members(enum_cls) -> set[tuple[str, str]]:\\n    return {(member.name, member.value) for member in enum_cls}\\n\\n\\ndef test_all_job_status_definitions_have_identical_members():\\n    schema = _members(SchemaJobStatus)\\n    durable = _members(DurableJobStatus)\\n    db = _members(DbJobStatus)\\n\\n    assert schema == durable, (\\n        f\\\"JobStatus drift between lfx.schema.workflow and lfx.services.durable.models: {schema ^ durable}\\\"\\n    )\\n    assert schema == db, (\\n        \\\"JobStatus drift between lfx.schema.workflow and the DB model \\\"\\n        \\\"(langflow.services.database.models.jobs.model): \\\"\\n        f\\\"{schema ^ db}\\\"\\n    )\\n\\n\\ndef test_suspended_is_present_in_every_definition():\\n    \\\"\\\"\\\"The HITL state that motivated this guard must exist everywhere.\\\"\\\"\\\"\\n    for enum_cls in (SchemaJobStatus, DurableJobStatus, DbJobStatus):\\n        assert \\\"suspended\\\" in {m.value for m in enum_cls}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_last_event_id_contract.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"44f3a619c288be3d6ff3258074bcb272c655fb36ebc428720fb5da10c8fb4aeb\",\"content\":\"\\\"\\\"\\\"Last-Event-ID reattach contract: live id: and durable replay share ONE namespace.\\n\\nThe live SSE stream tags every frame with an ``id:`` line. A client that\\ndisconnects mid-run reconnects with ``Last-Event-ID: <that id>``; the facade then\\nresumes from ``read_events(after_seq=<that id>)``. For that resume to be correct,\\nthe ``id:`` the client saw live MUST be the same namespace as the durable\\n``job_events.seq`` the replay filters on.\\n\\nThe realistic frame source (``_stream_event_frames``) bakes its OWN per-frame\\ncounter into the ``id:`` line \u2014 counting initial/ephemeral/durable frames alike \u2014\\nso a naive runner that passes those bytes through publishes a DIFFERENT id\\nnamespace than the durable seq. A reattach with a live id then gaps or duplicates\\nmilestones. These tests drive the REAL runner + REAL facade with a source shaped\\nexactly like ``_stream_event_frames`` (baked stream-seq ids, a token between two\\nmilestones) and assert the continuation after a mid-run Last-Event-ID starts\\nexactly at the next milestone \u2014 no miss, no repeat \u2014 on real SQLite and Postgres.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom fastapi.sse import format_sse_event\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import JobRunner\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n\\npytestmark = pytest.mark.real_services\\n\\n\\nclass _StubUser:\\n    \\\"\\\"\\\"Minimal user carrying only ``id`` (all the facade reads on validate).\\\"\\\"\\\"\\n\\n    def __init__(self, user_id) -> None:\\n        self.id = user_id\\n\\n\\ndef _stream_seq_frame(event_type: str, data: dict, stream_seq: int) -> tuple[bytes, str]:\\n    \\\"\\\"\\\"Mimic ``_stream_event_frames``: bake a STREAM-seq id into the frame bytes.\\n\\n    The stream seq counts every yielded frame (initial, ephemeral, durable),\\n    so it deliberately diverges from the durable ``job_events.seq`` namespace.\\n    \\\"\\\"\\\"\\n    import json\\n\\n    body = json.dumps({\\\"event\\\": event_type, \\\"data\\\": data})\\n    return (format_sse_event(data_str=body, id=str(stream_seq)), event_type)\\n\\n\\ndef _id_line(frame: bytes) -> int:\\n    for line in frame.decode(\\\"utf-8\\\").splitlines():\\n        if line.startswith(\\\"id:\\\"):\\n            return int(line[len(\\\"id:\\\") :].strip())\\n    msg = f\\\"frame has no id: line: {frame!r}\\\"\\n    raise AssertionError(msg)\\n\\n\\ndef _milestone_ids(frames: list[bytes]) -> dict[str, int]:\\n    \\\"\\\"\\\"Map each durable milestone event_type -> the id: the client saw live.\\\"\\\"\\\"\\n    import json\\n\\n    out: dict[str, int] = {}\\n    for frame in frames:\\n        for line in frame.decode(\\\"utf-8\\\").splitlines():\\n            if line.startswith(\\\"data:\\\"):\\n                payload = json.loads(line[len(\\\"data:\\\") :].strip())\\n                evt = payload.get(\\\"event\\\")\\n                if evt in {\\\"build_start\\\", \\\"vertices_sorted\\\", \\\"end_vertex\\\", \\\"output\\\", \\\"end\\\"}:\\n                    out[evt] = _id_line(frame)\\n    return out\\n\\n\\nasync def _run_token_flow(job_service, job_id, bus) -> None:\\n    \\\"\\\"\\\"A run that emits a token BETWEEN two milestones so stream-seq != durable-seq.\\\"\\\"\\\"\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        # stream-seq baked in; durable seq advances only on durable frames.\\n        yield _stream_seq_frame(\\\"build_start\\\", {}, 0)  # durable -> db seq 1\\n        yield _stream_seq_frame(\\\"vertices_sorted\\\", {\\\"ids\\\": [\\\"n1\\\"]}, 1)  # durable -> db seq 2\\n        yield _stream_seq_frame(\\\"token\\\", {\\\"chunk\\\": \\\"a\\\"}, 2)  # ephemeral\\n        yield _stream_seq_frame(\\\"token\\\", {\\\"chunk\\\": \\\"b\\\"}, 3)  # ephemeral\\n        yield _stream_seq_frame(\\\"end_vertex\\\", {\\\"id\\\": \\\"n1\\\"}, 4)  # durable -> db seq 3\\n        yield _stream_seq_frame(\\\"end\\\", {}, 5)  # durable -> db seq 4\\n\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    runner = JobRunner(job_service=job_service, live_bus=bus, adapter=adapter, frame_source=source)\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n\\nasync def test_live_id_matches_durable_seq_default(real_services_job_service):\\n    \\\"\\\"\\\"The live id: a client sees == the durable seq the replay resumes after.\\n\\n    Drives the real runner (default in-memory bus), captures the live frames, then\\n    proves that for EACH milestone the live id equals the durable job_events.seq.\\n    Pre-fix the live id is the stream-seq (0,1,4,5) while the durable seq is\\n    (1,2,3,4), so they diverge and a Last-Event-ID resume is wrong.\\n    \\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    user_id = uuid4()\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=user_id)\\n\\n    bus = InMemoryLiveBus()\\n\\n    # Subscribe BEFORE the run so we capture the live frames the client would see.\\n    live_frames: list[bytes] = []\\n    sub = bus.subscribe(str(job_id))\\n\\n    import asyncio\\n\\n    async def _collect() -> None:\\n        async for frame in sub:\\n            live_frames.append(frame.data)  # noqa: PERF401\\n\\n    collector = asyncio.create_task(_collect())\\n    await _run_token_flow(job_service, job_id, bus)\\n    await asyncio.wait_for(collector, timeout=5.0)\\n\\n    live_ids = _milestone_ids(live_frames)\\n\\n    # Durable seq order: build_start=1, vertices_sorted=2, end_vertex=3, end=4.\\n    rows = await job_service.read_events(job_id, after_seq=0)\\n    durable_seq = {r.event_type: r.seq for r in rows}\\n\\n    # The live id for each milestone MUST equal its durable seq (one namespace).\\n    for evt, seq in durable_seq.items():\\n        assert live_ids.get(evt) == seq, (\\n            f\\\"live id namespace mismatch for {evt}: live id={live_ids.get(evt)} durable seq={seq}\\\"\\n        )\\n\\n\\nasync def test_reattach_no_gap_no_dup_default(real_services_job_service):\\n    \\\"\\\"\\\"Mid-run Last-Event-ID resume starts exactly at the next milestone.\\n\\n    Captures the live id of the ``vertices_sorted`` milestone, reconnects with it\\n    as Last-Event-ID, and asserts the continuation replays exactly the milestones\\n    AFTER it (end_vertex, end) with no missing and no repeated milestone. Pre-fix\\n    the live id is a stream-seq (1) so read_events(after_seq=1) returns durable\\n    rows 2,3,4 (incl vertices_sorted again) -> duplicate.\\n    \\\"\\\"\\\"\\n    import asyncio\\n\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id = uuid4()\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=user_id)\\n\\n    bus = InMemoryLiveBus()\\n    live_frames: list[bytes] = []\\n    sub = bus.subscribe(str(job_id))\\n\\n    async def _collect() -> None:\\n        async for frame in sub:\\n            live_frames.append(frame.data)  # noqa: PERF401\\n\\n    collector = asyncio.create_task(_collect())\\n    await _run_token_flow(job_service, job_id, bus)\\n    await asyncio.wait_for(collector, timeout=5.0)\\n\\n    live_ids = _milestone_ids(live_frames)\\n    # Client disconnects right after seeing the vertices_sorted milestone live.\\n    last_event_id = str(live_ids[\\\"vertices_sorted\\\"])\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service())\\n    svc._bus = bus\\n    user = _StubUser(user_id)\\n\\n    async def _reattach() -> list[bytes]:\\n        return [frame async for frame in svc.events(job_id, last_event_id, user)]\\n\\n    cont_frames = await asyncio.wait_for(_reattach(), timeout=5.0)\\n    cont_ids = _milestone_ids(cont_frames)\\n\\n    # The continuation must contain end_vertex and end (the milestones AFTER the\\n    # disconnect) and must NOT re-deliver vertices_sorted (already seen live).\\n    assert \\\"vertices_sorted\\\" not in cont_ids, f\\\"duplicate milestone on reattach: {cont_ids}\\\"\\n    assert \\\"end_vertex\\\" in cont_ids, f\\\"missing milestone on reattach: {cont_ids}\\\"\\n    assert \\\"end\\\" in cont_ids, f\\\"missing milestone on reattach: {cont_ids}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_multi_worker_boot_real_services.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fc62ed48e165ab585c988e0323b0aeb953caf725fce8110b43bf23380ac5fdef\",\"content\":\"\\\"\\\"\\\"Crown jewel: a booting worker's sweep must not touch a sibling's live job.\\n\\nReproduces the BLOCKER/HIGH where ``sweep_orphans`` marked EVERY IN_PROGRESS row\\nFAILED(worker_lost). Under ``gunicorn -w N`` a booting worker B would flip worker\\nA's just-claimed, actively-running, freshly-heartbeated job FAILED mid-run,\\ninject a phantom terminal event into A's live durable log, and race A's real\\nterminal write. With lease+heartbeat liveness the sweep only reconciles\\nGENUINELY orphaned rows (stale/absent heartbeat), so B leaves A's live job alone.\\n\\nReal SQLite AND real Postgres via the real-service fixture.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nfrom typing import TYPE_CHECKING\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\nif TYPE_CHECKING:\\n    from collections.abc import AsyncIterator\\n\\npytestmark = pytest.mark.real_services\\n\\n\\ndef _frame(event_type: str, data: dict) -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(\\\"utf-8\\\"), event_type)\\n\\n\\nasync def test_booting_worker_sweep_spares_live_heartbeated_job(real_services_job_service):\\n    job_service = real_services_job_service\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    # Gate that holds worker A \\\"mid-run\\\" while worker B boots and sweeps.\\n    release = asyncio.Event()\\n    side_effect_runs = 0\\n\\n    async def source(**_kwargs) -> AsyncIterator[tuple[bytes, str]]:\\n        nonlocal side_effect_runs\\n        side_effect_runs += 1\\n        yield _frame(\\\"build_start\\\", {})\\n        # Park here (job is IN_PROGRESS + heartbeating) until the test releases it.\\n        await release.wait()\\n        yield _frame(\\\"end\\\", {})\\n\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    bus = InMemoryLiveBus()\\n    # Worker A: a fast heartbeat so the row is demonstrably fresh by the time B sweeps.\\n    runner_a = JobRunner(\\n        job_service=job_service,\\n        live_bus=bus,\\n        adapter=adapter,\\n        frame_source=source,\\n        owner=\\\"worker-A\\\",\\n        heartbeat_interval_s=0.1,\\n    )\\n    run_a = asyncio.create_task(runner_a.run(job_id=job_id, source_kwargs={}))\\n\\n    try:\\n        # Wait until A is IN_PROGRESS and has stamped at least one heartbeat.\\n        for _ in range(100):\\n            job = await job_service.get_job_by_job_id(job_id)\\n            meta = job.job_metadata or {}\\n            if job.status == JobStatus.IN_PROGRESS and meta.get(\\\"heartbeat_at\\\"):\\n                break\\n            await asyncio.sleep(0.05)\\n        else:\\n            pytest.fail(\\\"worker A never reached IN_PROGRESS with a heartbeat\\\")\\n\\n        # Worker B boots and runs the liveness-aware sweep. A's heartbeat is fresh\\n        # (well under the lease TTL), so B must NOT reconcile A's job.\\n        swept = await job_service.sweep_orphans(lease_ttl_s=30.0)\\n        assert job_id not in swept\\n\\n        job = await job_service.get_job_by_job_id(job_id)\\n        assert job.status == JobStatus.IN_PROGRESS  # not flipped FAILED mid-run\\n        # No phantom terminal event injected into A's live durable log.\\n        events = await job_service.read_events(job_id)\\n        assert all(e.event_type != \\\"run_failed\\\" for e in events)\\n    finally:\\n        release.set()\\n        await asyncio.wait_for(run_a, timeout=10)\\n\\n    # A finished cleanly; the flow ran exactly once (no second run from B).\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.COMPLETED\\n    assert side_effect_runs == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_real_services_ci_wiring.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d3a4f609ba469cecde55e00ef71ed783a709a4851c2b0eb8037c0868b31f5f8d\",\"content\":\"\\\"\\\"\\\"Verify CI wires a real redis:7 service and runs the real-service tier.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\n\\nimport pytest\\nimport yaml\\n\\n_REPO_ROOT = Path(__file__).resolve().parents[5]\\n_WORKFLOW = _REPO_ROOT / \\\".github\\\" / \\\"workflows\\\" / \\\"migration-validation.yml\\\"\\n\\n\\n@pytest.fixture\\ndef workflow() -> dict:\\n    assert _WORKFLOW.exists(), f\\\"workflow not found at {_WORKFLOW}\\\"\\n    return yaml.safe_load(_WORKFLOW.read_text(encoding=\\\"utf-8\\\"))\\n\\n\\ndef _real_services_job(workflow: dict) -> dict | None:\\n    return next((j for name, j in workflow[\\\"jobs\\\"].items() if \\\"real\\\" in name and \\\"service\\\" in name), None)\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_real_services_job_exists(workflow: dict) -> None:\\n    assert _real_services_job(workflow) is not None, f\\\"no real-service job; jobs: {list(workflow['jobs'])}\\\"\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_real_services_job_has_postgres_and_redis_services(workflow: dict) -> None:\\n    real_services = _real_services_job(workflow)\\n    assert real_services is not None\\n    images = {svc[\\\"image\\\"] for svc in real_services[\\\"services\\\"].values()}\\n    assert any(img.startswith(\\\"postgres:\\\") for img in images), images\\n    assert any(img.startswith(\\\"redis:\\\") for img in images), images\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_real_services_job_sets_both_test_uris() -> None:\\n    text = _WORKFLOW.read_text(encoding=\\\"utf-8\\\")\\n    assert \\\"LANGFLOW_TEST_DATABASE_URI\\\" in text\\n    assert \\\"LANGFLOW_TEST_REDIS_URL\\\" in text\\n    assert \\\"-m real_services\\\" in text or \\\"real_services_tests\\\" in text\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_real_services_harness.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fee35a7839e58f226c39f3dc034fd1a182ac5325c3661625c9e972ba1c59cfd7\",\"content\":\"\\\"\\\"\\\"Phase 0 harness tests: the real_services marker + real-instance fixtures.\\n\\nThese prove the harness itself works before any background-execution code exists:\\nthe marker is registered, the DB fixture backs a real engine on sqlite and\\npostgres, and the redis fixture pings a real server.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\n\\nimport pytest\\nfrom sqlalchemy import text\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_real_services_marker_is_registered(request: pytest.FixtureRequest) -> None:\\n    \\\"\\\"\\\"The real_services marker must be registered so --strict-markers accepts it.\\\"\\\"\\\"\\n    ini_markers = request.config.getini(\\\"markers\\\")\\n    names = {line.split(\\\":\\\", 1)[0].strip() for line in ini_markers}\\n    assert \\\"real_services\\\" in names, f\\\"real_services not registered; have: {sorted(names)}\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_real_services_db_url_yields_real_engine(real_services_db_url: str) -> None:\\n    \\\"\\\"\\\"real_services_db_url must produce a URL backing a real, queryable engine.\\\"\\\"\\\"\\n    if \\\"postgresql\\\" in real_services_db_url:\\n        assert os.environ.get(\\\"LANGFLOW_TEST_DATABASE_URI\\\"), \\\"postgres param ran without URI set\\\"\\n    engine = create_async_engine(real_services_db_url)\\n    try:\\n        async with engine.connect() as conn:\\n            result = await conn.execute(text(\\\"SELECT 1\\\"))\\n            assert result.scalar_one() == 1\\n    finally:\\n        await engine.dispose()\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_real_services_redis_url_pings_real_server(real_services_redis_url: str) -> None:\\n    \\\"\\\"\\\"real_services_redis_url must back a reachable, real Redis server.\\\"\\\"\\\"\\n    from redis.asyncio import StrictRedis\\n\\n    assert os.environ.get(\\\"LANGFLOW_TEST_REDIS_URL\\\"), \\\"redis fixture ran without URL set\\\"\\n    client = StrictRedis.from_url(real_services_redis_url)\\n    try:\\n        assert await client.ping() is True\\n        await client.set(\\\"real_services:probe\\\", \\\"1\\\")\\n        assert await client.get(\\\"real_services:probe\\\") == b\\\"1\\\"\\n    finally:\\n        await client.aclose()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_real_services_make_target.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"38f39c9739a1b4a17f51e984ca6ad2a640cb73d412b1184ff4fed701b22aacae\",\"content\":\"\\\"\\\"\\\"Verify the Makefile exposes a real_services_tests target wired to -m real_services.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n_REPO_ROOT = Path(__file__).resolve().parents[5]\\n_MAKEFILE = _REPO_ROOT / \\\"Makefile\\\"\\n\\n\\n@pytest.mark.no_blockbuster\\ndef test_makefile_has_real_services_target() -> None:\\n    assert _MAKEFILE.exists(), f\\\"Makefile not found at {_MAKEFILE}\\\"\\n    text = _MAKEFILE.read_text(encoding=\\\"utf-8\\\")\\n    assert \\\"real_services_tests:\\\" in text, \\\"missing real_services_tests make target\\\"\\n    target_block = text.split(\\\"real_services_tests:\\\", 1)[1].split(\\\"\\\\n\\\\n\\\", 1)[0]\\n    assert \\\"-m real_services\\\" in target_block, \\\"real_services_tests target must select the real_services marker\\\"\\n    assert \\\"src/backend/tests/unit\\\" in target_block, \\\"target must run the backend unit tree\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_resume.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"53db635a9d08334bfcc710a444f3ca387d677d0145921e5b0cf8e9c605abe9eb\",\"content\":\"\\\"\\\"\\\"Resume-by-re-enqueue (LE-1446) against a real JobService + facade.\\n\\nSlice 1 \u2014 the service-layer ``resume_job``: validate SUSPENDED, atomic single-flight\\nflip, write a RESUME signal carrying the human decision, re-enqueue. Staleness and\\nnon-SUSPENDED resumes are rejected before any signal/re-enqueue.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import HUMAN_INPUT_REQUIRED_EVENT, JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus, SignalType\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\n\\ndef _frame(event_type: str, data: dict) -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(), event_type)\\n\\n\\ndef _pause_source(payload: dict):\\n    async def _source(**_kwargs):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"working\u2026\\\"})\\n        yield (json.dumps(payload).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n    return _source\\n\\n\\ndef _noop_factory(**_kwargs):\\n    async def _source(**_kw):\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\nclass _StubUser:\\n    def __init__(self, user_id):\\n        self.id = user_id\\n\\n\\nclass _RecordingBackend:\\n    def __init__(self) -> None:\\n        self.enqueued: list[str] = []\\n\\n    async def enqueue(self, job_id: str) -> None:\\n        self.enqueued.append(job_id)\\n\\n\\ndef _runner(job_service, job_id, source):\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    return JobRunner(job_service=job_service, live_bus=InMemoryLiveBus(), adapter=adapter, frame_source=source)\\n\\n\\nasync def _suspend_a_job(job_service, *, request_id=\\\"req-1\\\"):\\n    user_id, flow_id, job_id = uuid4(), uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    await job_service.update_job_metadata(job_id, {\\\"request\\\": {\\\"flow_id\\\": str(flow_id), \\\"stream_protocol\\\": \\\"langflow\\\"}})\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": request_id, \\\"options\\\": [\\\"approve\\\", \\\"reject\\\"]}\\n    await _runner(job_service, job_id, _pause_source(payload)).run(job_id=job_id, source_kwargs={})\\n    return user_id, job_id\\n\\n\\nasync def _facade():\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service(), frame_source_factory=_noop_factory)\\n    await svc.start()\\n    return svc\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_pending_request_unwraps_agui_custom_event_envelope(real_services_job_service) -> None:\\n    \\\"\\\"\\\"get_pending unwraps the AG-UI CustomEvent wire frame to the raw request (top-level fields).\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    user_id, flow_id, job_id = uuid4(), uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    raw = {\\n        \\\"request_id\\\": \\\"node:run\\\",\\n        \\\"kind\\\": \\\"node_input\\\",\\n        \\\"timeout_seconds\\\": 60,\\n        \\\"fallback_action\\\": \\\"fallback\\\",\\n        \\\"paused_at\\\": \\\"2026-06-22T00:00:00+00:00\\\",\\n        \\\"allowed_decisions\\\": [\\\"approve\\\", \\\"reject\\\", \\\"fallback\\\"],\\n    }\\n    envelope = {\\\"type\\\": \\\"CUSTOM\\\", \\\"name\\\": \\\"langflow.human_input_required\\\", \\\"value\\\": raw}\\n    await _runner(job_service, job_id, _pause_source(envelope)).run(job_id=job_id, source_kwargs={})\\n\\n    pending = await job_service.get_pending_human_request(job_id)\\n    assert pending[\\\"request_id\\\"] == \\\"node:run\\\"\\n    assert pending[\\\"timeout_seconds\\\"] == 60\\n    assert pending[\\\"fallback_action\\\"] == \\\"fallback\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_job_writes_resume_signal_with_decision(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-a\\\")\\n\\n    svc = await _facade()\\n    try:\\n        decision = {\\\"choice\\\": \\\"approve\\\", \\\"note\\\": \\\"looks good\\\"}\\n        accepted = await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-a\\\", decision=decision)\\n        assert accepted is True\\n    finally:\\n        await svc.stop()\\n\\n    signals = await job_service.unconsumed_signals(job_id)\\n    resume = [s for s in signals if s.signal_type == SignalType.RESUME]\\n    assert len(resume) == 1\\n    assert resume[0].data[\\\"decision\\\"] == decision\\n    assert resume[0].data[\\\"request_id\\\"] == \\\"req-a\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_flips_out_of_suspended(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-b\\\")\\n\\n    svc = await _facade()\\n    try:\\n        await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-b\\\", decision={\\\"choice\\\": \\\"x\\\"})\\n    finally:\\n        await svc.stop()\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status != JobStatus.SUSPENDED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_second_resume_for_same_request_is_rejected(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-c\\\")\\n\\n    svc = await _facade()\\n    try:\\n        first = await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-c\\\", decision={\\\"choice\\\": \\\"a\\\"})\\n        second = await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-c\\\", decision={\\\"choice\\\": \\\"b\\\"})\\n        assert first is True\\n        assert second is False  # no longer SUSPENDED \u2192 rejected\\n    finally:\\n        await svc.stop()\\n\\n    signals = await job_service.unconsumed_signals(job_id)\\n    assert len([s for s in signals if s.signal_type == SignalType.RESUME]) == 1  # only one RESUME row\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_stale_request_id_is_rejected(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-real\\\")\\n\\n    svc = await _facade()\\n    try:\\n        accepted = await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-WRONG\\\", decision={\\\"choice\\\": \\\"a\\\"})\\n        assert accepted is False\\n    finally:\\n        await svc.stop()\\n\\n    signals = await job_service.unconsumed_signals(job_id)\\n    assert not [s for s in signals if s.signal_type == SignalType.RESUME]  # no signal written for a stale id\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED  # untouched\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\n@pytest.mark.parametrize(\\\"damage\\\", [\\\"wrong-key\\\", \\\"null-token\\\"])\\nasync def test_resume_checks_encrypted_overrides_before_claiming_or_writing_decision(\\n    real_services_job_service,\\n    damage,\\n) -> None:\\n    \\\"\\\"\\\"Unavailable ciphertext leaves the paused run and its decision seam untouched.\\\"\\\"\\\"\\n    from cryptography.fernet import Fernet\\n    from langflow.services.background_execution.service import (\\n        BackgroundExecutionService,\\n        RequestOverridesUnavailableError,\\n    )\\n    from langflow.services.deps import get_settings_service\\n    from pydantic import SecretStr\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    backend = _RecordingBackend()\\n    user_id, flow_id = uuid4(), uuid4()\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_noop_factory,\\n        backend=backend,\\n    )\\n    job_id = await submitter.submit(\\n        flow_id=flow_id,\\n        request={\\n            \\\"flow_id\\\": str(flow_id),\\n            \\\"mode\\\": \\\"background\\\",\\n            \\\"stream_protocol\\\": \\\"langflow\\\",\\n            \\\"input_value\\\": \\\"pause\\\",\\n            \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"resume-secret\\\"}},  # pragma: allowlist secret\\n        },\\n        user=_StubUser(user_id),\\n    )\\n    await job_service.update_job_metadata(job_id, {\\\"pending_request_id\\\": \\\"req-encrypted\\\"})\\n    await job_service.update_job_status(job_id, JobStatus.SUSPENDED)\\n\\n    resume_settings = settings_service\\n    if damage == \\\"wrong-key\\\":\\n        wrong_auth = settings_service.auth_settings.model_copy(\\n            update={\\\"SECRET_KEY\\\": SecretStr(Fernet.generate_key().decode())}\\n        )\\n        resume_settings = SimpleNamespace(settings=settings_service.settings, auth_settings=wrong_auth)\\n    else:\\n        job = await job_service.get_job_by_job_id(job_id)\\n        null_metadata = dict(job.job_metadata)\\n        null_metadata[\\\"request_overrides\\\"] = None\\n        await job_service.update_job_metadata(job_id, null_metadata, replace=True)\\n\\n    resume_service = BackgroundExecutionService(\\n        settings_service=resume_settings,\\n        frame_source_factory=_noop_factory,\\n    )\\n    with pytest.raises(RequestOverridesUnavailableError, match=\\\"Background request overrides are unavailable\\\"):\\n        await resume_service.resume_job(\\n            job_id,\\n            _StubUser(user_id),\\n            request_id=\\\"req-encrypted\\\",\\n            decision={  # pragma: allowlist secret\\n                \\\"choice\\\": \\\"approve\\\",\\n                \\\"secret\\\": \\\"decision-must-not-be-written\\\",  # pragma: allowlist secret\\n            },\\n        )\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") == \\\"req-encrypted\\\"\\n    assert await job_service.unconsumed_signals(job_id) == []\\n    assert \\\"decision-must-not-be-written\\\" not in json.dumps(job.job_metadata)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_rehydrates_original_encrypted_overrides(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A successful HITL resume receives the same overrides as the initial run.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    settings_service = get_settings_service()\\n    backend = _RecordingBackend()\\n    user_id, flow_id = uuid4(), uuid4()\\n    request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"resume-with-overrides\\\",\\n        \\\"tweaks\\\": {\\\"Node-x\\\": {\\\"api_key\\\": \\\"resume-replay-secret\\\"}},  # pragma: allowlist secret\\n    }\\n    submitter = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_noop_factory,\\n        backend=backend,\\n    )\\n    job_id = await submitter.submit(flow_id=flow_id, request=request, user=_StubUser(user_id))\\n    await job_service.update_job_metadata(job_id, {\\\"pending_request_id\\\": \\\"req-replay\\\"})\\n    await job_service.update_job_status(job_id, JobStatus.SUSPENDED)\\n\\n    captured: list[dict] = []\\n\\n    def _capture_factory(*, request, **_kwargs):\\n        captured.append(request)\\n        return _noop_factory()\\n\\n    resume_service = BackgroundExecutionService(\\n        settings_service=settings_service,\\n        frame_source_factory=_capture_factory,\\n    )\\n    try:\\n        accepted = await resume_service.resume_job(\\n            job_id,\\n            _StubUser(user_id),\\n            request_id=\\\"req-replay\\\",\\n            decision={\\\"choice\\\": \\\"approve\\\"},\\n        )\\n        assert accepted is True\\n        # The factory is called synchronously while building the re-enqueued\\n        # runner, before the executor starts consuming the resume checkpoint.\\n        assert captured == [request]\\n    finally:\\n        await resume_service.stop()\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_accepts_legacy_empty_overrides(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A suspended pre-fix v2 row drops empty override defaults and resumes safely.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id, flow_id, job_id = uuid4(), uuid4(), uuid4()\\n    safe_request = {\\n        \\\"flow_id\\\": str(flow_id),\\n        \\\"mode\\\": \\\"background\\\",\\n        \\\"stream_protocol\\\": \\\"langflow\\\",\\n        \\\"input_value\\\": \\\"legacy-empty-resume\\\",\\n    }\\n    await job_service.create_job(\\n        job_id=job_id,\\n        flow_id=flow_id,\\n        user_id=user_id,\\n        initial_metadata={\\n            \\\"request\\\": {**safe_request, \\\"globals\\\": {}, \\\"tweaks\\\": {}},\\n            \\\"pending_request_id\\\": \\\"req-legacy-empty\\\",\\n        },\\n    )\\n    await job_service.update_job_status(job_id, JobStatus.SUSPENDED)\\n\\n    captured: list[dict] = []\\n\\n    def _capture_factory(*, request, **_kwargs):\\n        captured.append(request)\\n        return _noop_factory()\\n\\n    resume_service = BackgroundExecutionService(\\n        settings_service=get_settings_service(),\\n        frame_source_factory=_capture_factory,\\n    )\\n    try:\\n        accepted = await resume_service.resume_job(\\n            job_id,\\n            _StubUser(user_id),\\n            request_id=\\\"req-legacy-empty\\\",\\n            decision={\\\"choice\\\": \\\"approve\\\"},\\n        )\\n        assert accepted is True\\n        assert captured == [safe_request]\\n    finally:\\n        await resume_service.stop()\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Slice 3 \u2014 runner RESUME consume + checkpoint load + injected resume hook.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _durable_store(job_service):\\n    from langflow.services.checkpoint.store import JobScopedCheckpointStore\\n\\n    return JobScopedCheckpointStore(job_service)\\n\\n\\ndef _graph_checkpoint(job_id):\\n    from lfx.graph.checkpoint.schema import GraphCheckpoint\\n\\n    return GraphCheckpoint(\\n        run_id=str(job_id),\\n        job_id=str(job_id),\\n        flow_id=\\\"flow-1\\\",\\n        session_id=\\\"sess-1\\\",\\n        flow_payload={\\\"nodes\\\": [], \\\"edges\\\": []},\\n        vertices_to_run={\\\"a\\\"},\\n    )\\n\\n\\ndef _post_resume_source():\\n    async def _source(**_kwargs):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"resumed\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\ndef _resume_runner(job_service, job_id, *, resume_hook, store, source=None):\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    return JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=adapter,\\n        frame_source=source or _post_resume_source(),\\n        resume_hook=resume_hook,\\n        checkpoint_store=store,\\n    )\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_runner_consumes_resume_and_hands_checkpoint_and_decision_to_hook(real_services_job_service) -> None:\\n    from langflow.services.database.models.jobs.model import SignalType\\n\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n    store = _durable_store(job_service)\\n    await store.save(_graph_checkpoint(job_id))\\n    decision = {\\\"choice\\\": \\\"approve\\\"}\\n    await job_service.write_signal(job_id, SignalType.RESUME, {\\\"decision\\\": decision, \\\"request_id\\\": \\\"req-h\\\"})\\n\\n    received: list[tuple] = []\\n\\n    async def hook(checkpoint, decision_arg):\\n        received.append((checkpoint, decision_arg))\\n\\n    await _resume_runner(job_service, job_id, resume_hook=hook, store=store).run(job_id=job_id, source_kwargs={})\\n\\n    assert len(received) == 1\\n    checkpoint, decision_arg = received[0]\\n    assert checkpoint is not None\\n    assert str(checkpoint.job_id) == str(job_id)  # loaded by job_id (run_id carries it)\\n    assert decision_arg == decision\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_signal_consumed_exactly_once(real_services_job_service) -> None:\\n    from langflow.services.database.models.jobs.model import SignalType\\n\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n    store = _durable_store(job_service)\\n    await store.save(_graph_checkpoint(job_id))\\n    await job_service.write_signal(job_id, SignalType.RESUME, {\\\"decision\\\": {\\\"x\\\": 1}, \\\"request_id\\\": \\\"req-once\\\"})\\n\\n    async def hook(_checkpoint, _decision):\\n        pass\\n\\n    await _resume_runner(job_service, job_id, resume_hook=hook, store=store).run(job_id=job_id, source_kwargs={})\\n\\n    unconsumed = await job_service.unconsumed_signals(job_id)\\n    assert not [s for s in unconsumed if s.signal_type == SignalType.RESUME]\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_fresh_run_does_not_call_resume_hook(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n    store = _durable_store(job_service)\\n\\n    called = []\\n\\n    async def hook(_checkpoint, _decision):\\n        called.append(1)\\n\\n    await _resume_runner(job_service, job_id, resume_hook=hook, store=store).run(job_id=job_id, source_kwargs={})\\n\\n    assert called == []\\n\\n\\n# --------------------------------------------------------------------------- #\\n# Slice 4 \u2014 same-stream seq continuation + no orphan-sweep double-run.\\n# --------------------------------------------------------------------------- #\\n\\n\\ndef _resumed_add_message_factory(**_kwargs):\\n    async def _source(**_kw):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"post-resume\\\"})\\n        yield _frame(\\\"end\\\", {})\\n\\n    return _source\\n\\n\\nasync def _facade_with(factory):\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service(), frame_source_factory=factory)\\n    await svc.start()\\n    return svc\\n\\n\\nasync def _wait_for_seq_gt(job_service, job_id, threshold, *, attempts=100):\\n    import asyncio\\n\\n    for _ in range(attempts):\\n        events = await job_service.read_events(job_id, after_seq=0)\\n        if events and max(e.seq for e in events) > threshold:\\n            return events\\n        await asyncio.sleep(0.05)\\n    return await job_service.read_events(job_id, after_seq=0)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_continues_same_event_stream(real_services_job_service) -> None:\\n    \\\"\\\"\\\"Post-resume frames extend the same (job_id, seq) sequence: strictly greater, no reset.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-seq\\\")\\n    pre = await job_service.read_events(job_id, after_seq=0)\\n    pre_max = max(e.seq for e in pre)\\n\\n    svc = await _facade_with(_resumed_add_message_factory)\\n    try:\\n        await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-seq\\\", decision={\\\"choice\\\": \\\"go\\\"})\\n        events = await _wait_for_seq_gt(job_service, job_id, pre_max)\\n    finally:\\n        await svc.stop()\\n\\n    seqs = sorted(e.seq for e in events)\\n    assert seqs == list(range(1, len(seqs) + 1))  # gap-free, no reset\\n    assert max(seqs) > pre_max  # post-resume frames strictly extend the stream\\n    post = [e for e in events if e.seq > pre_max and e.event_type == \\\"add_message\\\"]\\n    assert post\\n    assert post[0].payload[\\\"data\\\"][\\\"text\\\"] == \\\"post-resume\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_resume_does_not_leave_a_queued_row_for_the_sweep(real_services_job_service) -> None:\\n    \\\"\\\"\\\"Resume flips SUSPENDED->IN_PROGRESS, so the startup QUEUED re-enqueue can't double-run it.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-nosweep\\\")\\n\\n    svc = await _facade_with(_noop_factory)\\n    try:\\n        await svc.resume_job(job_id, _StubUser(user_id), request_id=\\\"req-nosweep\\\", decision={\\\"choice\\\": \\\"go\\\"})\\n        # The sweep only re-enqueues QUEUED workflow rows; a resumed row must not appear there.\\n        queued_ids = await job_service.queued_workflow_job_ids()\\n        assert job_id not in queued_ids\\n    finally:\\n        await svc.stop()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_runner_suspend.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"134b2b6460f1b5b70ddd780ff36c85ce4e6f4f3184a6c8983a412945eb69544d\",\"content\":\"\\\"\\\"\\\"Runner suspend mechanics (LE-1442) against a real JobService + live bus.\\n\\nWhen a producer pauses for human input, the runner must exit WITHOUT finalizing\\nto a terminal status: it writes SUSPENDED (no finished_timestamp), appends a\\ndurable ``human_input_required`` event, and leaves result/error untouched.\\nThe scripted frame source emits the pause sentinel the real build path raises.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport contextlib\\nimport json\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import HUMAN_INPUT_REQUIRED_EVENT, JobRunner\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\n\\ndef _frame(event_type: str, data: dict) -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(), event_type)\\n\\n\\ndef _pause_source(payload: dict):\\n    async def _source(**_kwargs):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"working\u2026\\\"})\\n        yield (json.dumps(payload).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n    return _source\\n\\n\\ndef _runner(job_service, job_id, source):\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    return JobRunner(job_service=job_service, live_bus=InMemoryLiveBus(), adapter=adapter, frame_source=source)\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_runner_suspends_without_terminalizing(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-1\\\", \\\"options\\\": [\\\"approve\\\", \\\"reject\\\"]}\\n    runner = _runner(job_service, job_id, _pause_source(payload))\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    assert job.result is None\\n    assert job.error is None\\n    assert job.finished_timestamp is None\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_appends_durable_human_input_event(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-2\\\", \\\"options\\\": [\\\"yes\\\", \\\"no\\\"]}\\n    runner = _runner(job_service, job_id, _pause_source(payload))\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    events = await job_service.read_events(job_id, after_seq=0)\\n    types = [e.event_type for e in events]\\n    assert HUMAN_INPUT_REQUIRED_EVENT in types\\n    assert \\\"add_message\\\" in types\\n    # No terminal event was appended.\\n    assert not ({\\\"run_cancelled\\\", \\\"run_timed_out\\\", \\\"end\\\"} & set(types))\\n    human = next(e for e in events if e.event_type == HUMAN_INPUT_REQUIRED_EVENT)\\n    assert human.payload[\\\"request_id\\\"] == \\\"req-2\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_records_pending_request_id(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-3\\\"}\\n    runner = _runner(job_service, job_id, _pause_source(payload))\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") == \\\"req-3\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_status_and_metadata_commit_atomically(real_services_job_service, monkeypatch) -> None:\\n    \\\"\\\"\\\"SUSPENDED is never visible without its resume-critical metadata.\\\"\\\"\\\"\\n    import langflow.services.jobs.service as jobs_service_module\\n    from langflow.services.database.models.jobs.model import Job\\n    from langflow.services.deps import session_scope as real_session_scope\\n\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n    await job_service.update_job_metadata(job_id, {\\\"existing\\\": \\\"preserved\\\"})\\n\\n    writer_flushed: asyncio.Queue[None] = asyncio.Queue()\\n    allow_commit: asyncio.Queue[None] = asyncio.Queue()\\n    writer_committed: asyncio.Queue[None] = asyncio.Queue()\\n\\n    @contextlib.asynccontextmanager\\n    async def _session_scope_with_commit_barrier():\\n        async with real_session_scope() as session:\\n            yield session\\n            writer_flushed.put_nowait(None)\\n            await allow_commit.get()\\n        writer_committed.put_nowait(None)\\n\\n    monkeypatch.setattr(jobs_service_module, \\\"session_scope\\\", _session_scope_with_commit_barrier)\\n    metadata = {\\n        \\\"pending_request_id\\\": \\\"req-atomic\\\",\\n        \\\"pre_pause_outputs\\\": [{\\\"component_id\\\": \\\"comp-A\\\", \\\"value\\\": \\\"before pause\\\"}],\\n    }\\n    suspend_task = asyncio.create_task(job_service.suspend_job(job_id, metadata))\\n\\n    try:\\n        # The writer has flushed both mutations but is still behind the commit barrier.\\n        await asyncio.wait_for(writer_flushed.get(), timeout=5)\\n        async with real_session_scope() as observer_session:\\n            before_commit = await observer_session.get(Job, job_id)\\n            assert before_commit is not None\\n            assert before_commit.status == JobStatus.QUEUED\\n            assert before_commit.job_metadata == {\\\"existing\\\": \\\"preserved\\\"}\\n\\n        allow_commit.put_nowait(None)\\n        await asyncio.wait_for(writer_committed.get(), timeout=5)\\n        # If suspend_job ever splits this into two transactions, its second\\n        # transaction stops at the same barrier and this read exposes the gap.\\n        await asyncio.sleep(0)\\n        async with real_session_scope() as observer_session:\\n            after_commit = await observer_session.get(Job, job_id)\\n            assert after_commit is not None\\n            assert after_commit.status == JobStatus.SUSPENDED\\n            assert after_commit.job_metadata == {\\\"existing\\\": \\\"preserved\\\", **metadata}\\n    finally:\\n        if not suspend_task.done():\\n            suspend_task.cancel()\\n        with contextlib.suppress(asyncio.CancelledError):\\n            await suspend_task\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_racing_resume_cannot_claim_before_suspend_metadata_is_ready(\\n    real_services_job_service, monkeypatch\\n) -> None:\\n    \\\"\\\"\\\"A resume arriving while suspend is staged cannot run without the output stash.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n    from lfx.workflow.adapters.langflow import WORKFLOW_OUTPUT_CAPTURE_EVENT\\n\\n    job_service = real_services_job_service\\n    job_id, flow_id, user_id = uuid4(), uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n\\n    entered_suspend = asyncio.Event()\\n    allow_suspend = asyncio.Event()\\n    original_suspend = job_service.suspend_job\\n\\n    async def _gated_suspend(gated_job_id, metadata):\\n        entered_suspend.set()\\n        await allow_suspend.wait()\\n        return await original_suspend(gated_job_id, metadata)\\n\\n    monkeypatch.setattr(job_service, \\\"suspend_job\\\", _gated_suspend)\\n    output = {\\n        \\\"component_id\\\": \\\"comp-A\\\",\\n        \\\"type\\\": \\\"message\\\",\\n        \\\"status\\\": \\\"completed\\\",\\n        \\\"content\\\": \\\"before pause\\\",\\n    }\\n    pause = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-race\\\"}\\n\\n    async def _source(**_kwargs):\\n        yield (json.dumps({\\\"data\\\": output}).encode(), WORKFLOW_OUTPUT_CAPTURE_EVENT)\\n        yield (json.dumps(pause).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n    run_task = asyncio.create_task(_runner(job_service, job_id, _source).run(job_id=job_id, source_kwargs={}))\\n    try:\\n        await asyncio.wait_for(entered_suspend.wait(), timeout=5)\\n        service = BackgroundExecutionService(settings_service=get_settings_service())\\n        accepted = await service.resume_job(\\n            job_id,\\n            _StubUser(user_id),\\n            request_id=\\\"req-race\\\",\\n            decision={\\\"action_id\\\": \\\"approve\\\"},\\n        )\\n        assert accepted is False\\n\\n        allow_suspend.set()\\n        await asyncio.wait_for(run_task, timeout=5)\\n        job = await job_service.get_job_by_job_id(job_id)\\n        assert job.status == JobStatus.SUSPENDED\\n        assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") == \\\"req-race\\\"\\n        assert (job.job_metadata or {}).get(\\\"pre_pause_outputs\\\") == [output]\\n    finally:\\n        allow_suspend.set()\\n        if not run_task.done():\\n            run_task.cancel()\\n        with contextlib.suppress(asyncio.CancelledError):\\n            await run_task\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspend_records_pending_request_id_from_wrapped_wire_frame(real_services_job_service) -> None:\\n    \\\"\\\"\\\"The real build seam emits the pause wrapped in the adapter envelope.\\n\\n    The langflow adapter nests the request under ``data`` (AG-UI under ``value``);\\n    the runner must still record ``pending_request_id`` or the resume staleness\\n    guard never engages and any request_id \u2014 even another job's \u2014 is accepted.\\n    \\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    request = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-wire\\\", \\\"options\\\": [\\\"approve\\\"]}\\n\\n    async def _source(**_kwargs):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"working\u2026\\\"})\\n        yield _frame(HUMAN_INPUT_REQUIRED_EVENT, request)\\n\\n    runner = _runner(job_service, job_id, _source)\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") == \\\"req-wire\\\"\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_get_pending_human_request_returns_last_payload(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-9\\\", \\\"options\\\": [\\\"a\\\", \\\"b\\\"]}\\n    runner = _runner(job_service, job_id, _pause_source(payload))\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    pending = await job_service.get_pending_human_request(job_id)\\n    assert pending is not None\\n    assert pending[\\\"request_id\\\"] == \\\"req-9\\\"\\n    assert pending[\\\"options\\\"] == [\\\"a\\\", \\\"b\\\"]\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_get_pending_human_request_none_when_not_suspended(real_services_job_service) -> None:\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    assert await job_service.get_pending_human_request(job_id) is None\\n\\n\\nclass _StubUser:\\n    def __init__(self, user_id):\\n        self.id = user_id\\n\\n\\nasync def _suspend_a_job(job_service, *, request_id=\\\"req-evt\\\"):\\n    user_id, flow_id, job_id = uuid4(), uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    await job_service.update_job_metadata(job_id, {\\\"request\\\": {\\\"stream_protocol\\\": \\\"langflow\\\"}})\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": request_id, \\\"options\\\": [\\\"x\\\"]}\\n    await _runner(job_service, job_id, _pause_source(payload)).run(job_id=job_id, source_kwargs={})\\n    return user_id, job_id\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_events_replays_suspended_job_and_returns(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A fresh facade (empty live bus) replays the suspended job's durable rows and RETURNS.\\\"\\\"\\\"\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service)\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service())\\n    user = _StubUser(user_id)\\n\\n    async def _collect() -> list[bytes]:\\n        return [frame async for frame in svc.events(job_id, None, user)]\\n\\n    # A hang (live-tail block) is caught by wait_for instead of stalling the suite.\\n    frames = await asyncio.wait_for(_collect(), timeout=5.0)\\n    joined = b\\\"\\\".join(frames).decode()\\n    assert HUMAN_INPUT_REQUIRED_EVENT in joined\\n    assert \\\"add_message\\\" in joined\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_status_includes_pending_human_request(real_services_job_service) -> None:\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-status\\\")\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service())\\n    status = await svc.status(job_id, _StubUser(user_id))\\n\\n    assert status[\\\"status\\\"] == JobStatus.SUSPENDED\\n    assert status[\\\"pending_request\\\"][\\\"request_id\\\"] == \\\"req-status\\\"\\n\\n\\ndef _stop_then_pause_source(payload: dict):\\n    async def _source(**_kwargs):\\n        yield _frame(\\\"add_message\\\", {\\\"text\\\": \\\"working\u2026\\\"})\\n        yield (json.dumps(payload).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n    return _source\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_stop_beats_pause_in_drive(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A STOP pending when the pause frame arrives wins: the run ends CANCELLED, not SUSPENDED.\\\"\\\"\\\"\\n    from langflow.services.database.models.jobs.model import SignalType\\n\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n    await job_service.write_signal(job_id, SignalType.STOP)  # stop already requested before the pause\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-sp\\\"}\\n    runner = _runner(job_service, job_id, _stop_then_pause_source(payload))\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.CANCELLED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_stop_while_suspended_cancels_and_cleans_up(real_services_job_service) -> None:\\n    from langflow.services.background_execution.service import BackgroundExecutionService\\n    from langflow.services.database.models.jobs.model import SignalType\\n    from langflow.services.deps import get_settings_service\\n\\n    job_service = real_services_job_service\\n    user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-stopsusp\\\")\\n    await job_service.save_checkpoint(job_id, \\\"graph\\\", '{\\\"checkpoint\\\":\\\"data\\\"}')\\n\\n    svc = BackgroundExecutionService(settings_service=get_settings_service())\\n    await svc.stop_job(job_id, _StubUser(user_id))\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.CANCELLED\\n    assert job.finished_timestamp is not None\\n    assert await job_service.load_checkpoint(job_id, \\\"graph\\\") is None  # checkpoint deleted\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") is None  # request cleared\\n    events = await job_service.read_events(job_id, after_seq=0)\\n    assert \\\"run_cancelled\\\" in [e.event_type for e in events]\\n    unconsumed = await job_service.unconsumed_signals(job_id)\\n    assert not [s for s in unconsumed if s.signal_type == SignalType.STOP]  # no STOP left on a resumable row\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_suspended_job_survives_orphan_sweep(real_services_job_service) -> None:\\n    \\\"\\\"\\\"The startup sweep only reconciles IN_PROGRESS rows, so SUSPENDED is left alone.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    _user_id, job_id = await _suspend_a_job(job_service, request_id=\\\"req-sweep\\\")\\n\\n    reconciled = await job_service.sweep_orphans(lease_ttl_s=0.0)  # everything stale\\n\\n    assert job_id not in reconciled\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_pause_signal_left_unconsumed(real_services_job_service) -> None:\\n    \\\"\\\"\\\"A polled PAUSE signal is a seam for a future API button \u2014 the runner must not consume it.\\\"\\\"\\\"\\n    from langflow.services.database.models.jobs.model import SignalType\\n\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n    await job_service.write_signal(job_id, SignalType.PAUSE)\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-pause\\\"}\\n    await _runner(job_service, job_id, _pause_source(payload)).run(job_id=job_id, source_kwargs={})\\n\\n    unconsumed = await job_service.unconsumed_signals(job_id)\\n    assert [s.signal_type for s in unconsumed] == [SignalType.PAUSE]\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_heartbeat_stopped_before_suspend_preserves_request_id(real_services_job_service) -> None:\\n    \\\"\\\"\\\"With the heartbeat running, suspend still records the request id (no clobber race).\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    job_id, flow_id = uuid4(), uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=uuid4())\\n\\n    payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": \\\"req-hb\\\"}\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=adapter,\\n        frame_source=_pause_source(payload),\\n        owner=\\\"worker-1\\\",\\n        heartbeat_interval_s=0.01,  # beat aggressively to expose a clobber race\\n    )\\n    await runner.run(job_id=job_id, source_kwargs={})\\n\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") == \\\"req-hb\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_store_real_services.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6243aea2fa5375ec5ab2eb17bfa1b92fc70a70490f82ff2792e3d47d3e09dba9\",\"content\":\"\\\"\\\"\\\"Real-service store tests: JobService methods against REAL SQLite and REAL Postgres.\\n\\nThese bind ``session_scope()`` to a real, migrated database (via the\\n``real_services_job_service`` fixture) so every store method is exercised on both\\nengines, not just the temp-file SQLite the ``client`` fixture provides. Running\\nthe real Alembic migrations against both engines here also re-proves the schema\\napplies on Postgres (JSONB columns, the execution_signal_type_enum, the\\nuq_job_events_job_id_seq unique constraint).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.jobs.model import JobStatus, SignalType\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_set_result_and_error_persist(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    await service.set_result(job_id, {\\\"output_text\\\": \\\"hi\\\", \\\"session_id\\\": \\\"s1\\\"})\\n    await service.set_error(job_id, {\\\"type\\\": \\\"boom\\\", \\\"message\\\": \\\"x\\\"})\\n\\n    fetched = await service.get_job_by_job_id(job_id)\\n    assert fetched.result == {\\\"output_text\\\": \\\"hi\\\", \\\"session_id\\\": \\\"s1\\\"}\\n    assert fetched.error == {\\\"type\\\": \\\"boom\\\", \\\"message\\\": \\\"x\\\"}\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_append_and_read_events_ordered(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.append_event(job_id, \\\"e1\\\", {\\\"i\\\": 1}) == 1\\n    assert await service.append_event(job_id, \\\"e2\\\", {\\\"i\\\": 2}) == 2\\n    assert await service.append_event(job_id, \\\"e3\\\", {\\\"i\\\": 3}) == 3\\n\\n    tail = await service.read_events(job_id, after_seq=1)\\n    assert [e.seq for e in tail] == [2, 3]\\n    assert tail[0].payload == {\\\"i\\\": 2}\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_append_event_seq_is_per_job(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_a = uuid4()\\n    job_b = uuid4()\\n    await service.create_job(job_id=job_a, flow_id=uuid4(), user_id=uuid4())\\n    await service.create_job(job_id=job_b, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.append_event(job_a, \\\"x\\\", {}) == 1\\n    assert await service.append_event(job_b, \\\"x\\\", {}) == 1\\n    assert await service.append_event(job_a, \\\"x\\\", {}) == 2\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_append_event_concurrent_appends_all_land_gap_free(real_services_job_service) -> None:\\n    \\\"\\\"\\\"Concurrent appends to one job must ALL land, gap-free (retry on UNIQUE collision).\\n\\n    Regression for the seq race: SELECT max(seq)+1 then INSERT collides under\\n    contention; without retry the losers' events were silently dropped.\\n    \\\"\\\"\\\"\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    n = 12\\n    seqs = await asyncio.gather(*(service.append_event(job_id, f\\\"e{i}\\\", {\\\"i\\\": i}) for i in range(n)))\\n\\n    # Every append returned a distinct seq and the set is exactly 1..n (no loss, no gaps).\\n    assert sorted(seqs) == list(range(1, n + 1)), f\\\"returned seqs not gap-free: {sorted(seqs)}\\\"\\n    events = await service.read_events(job_id)\\n    assert [e.seq for e in events] == list(range(1, n + 1)), \\\"persisted events not gap-free\\\"\\n    assert len(events) == n\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_write_and_read_signals(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    job_id = uuid4()\\n    await service.create_job(job_id=job_id, flow_id=uuid4(), user_id=uuid4())\\n\\n    assert await service.unconsumed_signals(job_id) == []\\n    signal = await service.write_signal(job_id, SignalType.STOP)\\n    assert signal.signal_type == SignalType.STOP\\n    assert signal.consumed_at is None\\n\\n    pending = await service.unconsumed_signals(job_id)\\n    assert len(pending) == 1\\n    assert pending[0].signal_type == SignalType.STOP\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_sweep_orphans_reconciles_in_progress(real_services_job_service) -> None:\\n    service = real_services_job_service\\n    orphan = uuid4()\\n    queued = uuid4()\\n    await service.create_job(job_id=orphan, flow_id=uuid4(), user_id=uuid4())\\n    await service.update_job_status(orphan, JobStatus.IN_PROGRESS)\\n    await service.create_job(job_id=queued, flow_id=uuid4(), user_id=uuid4())\\n\\n    swept = await service.sweep_orphans()\\n    assert orphan in swept\\n    assert queued not in swept\\n\\n    orphan_job = await service.get_job_by_job_id(orphan)\\n    assert orphan_job.status == JobStatus.FAILED\\n    assert orphan_job.error == {\\\"type\\\": \\\"worker_lost\\\"}\\n    assert orphan_job.finished_timestamp is not None\\n\\n    events = await service.read_events(orphan)\\n    assert [e.event_type for e in events] == [\\\"run_failed\\\"]\\n    assert events[0].payload == {\\\"type\\\": \\\"worker_lost\\\"}\\n\\n    queued_job = await service.get_job_by_job_id(queued)\\n    assert queued_job.status == JobStatus.QUEUED\\n\\n\\n@pytest.mark.real_services\\n@pytest.mark.no_blockbuster\\nasync def test_get_jobs_by_flow_id_orders_by_created_timestamp(real_services_job_service) -> None:\\n    \\\"\\\"\\\"Regression on real engines: ordering by created_timestamp must not raise.\\\"\\\"\\\"\\n    service = real_services_job_service\\n    flow_id = uuid4()\\n    user_id = uuid4()\\n    first = uuid4()\\n    second = uuid4()\\n    await service.create_job(job_id=first, flow_id=flow_id, user_id=user_id)\\n    await service.create_job(job_id=second, flow_id=flow_id, user_id=user_id)\\n\\n    jobs = await service.get_jobs_by_flow_id(flow_id, user_id)\\n    returned = {job.job_id for job in jobs}\\n    assert {first, second} <= returned\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/background_execution/test_supersede_suspended.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"59ca8c6ae23103eba912969e646e01a0ffc7ee4a4de8ac2963c5e99444fcc333\",\"content\":\"\\\"\\\"\\\"A new background run supersedes the flow's stale suspended pause.\\n\\nRe-running a flow while a previous run sits SUSPENDED left both pauses alive: the\\npending list piled up, every surface (badge, cards, trace bar) kept offering a\\ndecision nobody could meaningfully answer, and the old checkpoint lingered forever.\\nSubmitting a new run for the same flow + user + effective session now cancels the\\nstale suspended runs first \u2014 running jobs are untouched (parallel runs stay\\nsupported), and other flows, users, or SESSIONS are never affected (#14599: a\\nsecond caller's background run must not cancel the first caller's pause).\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.background_execution.live_bus import InMemoryLiveBus\\nfrom langflow.services.background_execution.runner import HUMAN_INPUT_REQUIRED_EVENT, JobRunner\\nfrom langflow.services.background_execution.service import BackgroundExecutionService\\nfrom langflow.services.database.models.jobs.model import JobStatus\\nfrom langflow.services.deps import get_settings_service\\nfrom lfx.workflow.adapters import StreamAdapterContext, get_stream_adapter\\n\\npytestmark = [pytest.mark.real_services, pytest.mark.no_blockbuster]\\n\\n\\ndef _frame(event_type: str, data: dict) -> tuple[bytes, str]:\\n    return (json.dumps({\\\"event\\\": event_type, \\\"data\\\": data}).encode(), event_type)\\n\\n\\ndef _pause_source(request_id: str):\\n    async def _source(**_kwargs):\\n        payload = {\\\"reason\\\": \\\"human_input_required\\\", \\\"request_id\\\": request_id, \\\"options\\\": [\\\"approve\\\"]}\\n        yield (json.dumps(payload).encode(), HUMAN_INPUT_REQUIRED_EVENT)\\n\\n    return _source\\n\\n\\nasync def _suspend_a_job(job_service, *, flow_id, user_id, request_id=\\\"req-1\\\", session_id=None, legacy_session_id=None):\\n    job_id = uuid4()\\n    await job_service.create_job(job_id=job_id, flow_id=flow_id, user_id=user_id)\\n    if legacy_session_id is not None:\\n        # Row shape from before ``submit`` persisted the request: no ``request`` blob,\\n        # just the flat session key ``_reconstruct_request`` falls back to.\\n        await job_service.update_job_metadata(job_id, {\\\"session_id\\\": legacy_session_id}, replace=True)\\n    else:\\n        request = {\\\"flow_id\\\": str(flow_id), \\\"stream_protocol\\\": \\\"langflow\\\"}\\n        if session_id is not None:\\n            request[\\\"session_id\\\"] = session_id\\n        await job_service.update_job_metadata(job_id, {\\\"request\\\": request})\\n    adapter = get_stream_adapter(\\\"langflow\\\", StreamAdapterContext(run_id=str(job_id), thread_id=\\\"t\\\"))\\n    runner = JobRunner(\\n        job_service=job_service,\\n        live_bus=InMemoryLiveBus(),\\n        adapter=adapter,\\n        frame_source=_pause_source(request_id),\\n    )\\n    await runner.run(job_id=job_id, source_kwargs={})\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.SUSPENDED\\n    return job_id\\n\\n\\ndef _service() -> BackgroundExecutionService:\\n    def _end_source(**_kwargs):\\n        async def _source(**_inner):\\n            yield _frame(\\\"end\\\", {})\\n\\n        return _source\\n\\n    return BackgroundExecutionService(get_settings_service(), frame_source_factory=_end_source)\\n\\n\\nasync def _wait_for_completed(job_service, job_id):\\n    for _ in range(100):\\n        job = await job_service.get_job_by_job_id(job_id)\\n        if job.status == JobStatus.COMPLETED:\\n            return job\\n        await asyncio.sleep(0.05)\\n    return job\\n\\n\\nasync def test_supersede_cancels_suspended_runs_of_same_flow_and_user(real_services_job_service):\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n\\n    superseded = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=str(flow_id))\\n\\n    assert stale_job_id in superseded\\n    job = await job_service.get_job_by_job_id(stale_job_id)\\n    assert job.status == JobStatus.CANCELLED\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") is None\\n\\n\\nasync def test_supersede_leaves_other_flows_and_users_alone(real_services_job_service):\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    other_flow_job = await _suspend_a_job(job_service, flow_id=uuid4(), user_id=user_id)\\n    other_user_job = await _suspend_a_job(job_service, flow_id=flow_id, user_id=uuid4())\\n\\n    superseded = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=str(flow_id))\\n\\n    assert superseded == []\\n    for untouched in (other_flow_job, other_user_job):\\n        job = await job_service.get_job_by_job_id(untouched)\\n        assert job.status == JobStatus.SUSPENDED\\n\\n\\nasync def test_supersede_does_not_clobber_a_run_claimed_for_resume(real_services_job_service):\\n    \\\"\\\"\\\"A resume that wins the flip between supersede's select and cancel keeps its run.\\n\\n    No CANCELLED write, no checkpoint delete, no metadata clear, no run_cancelled event.\\n    \\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n    await job_service.update_job_metadata(job_id, {\\\"pending_request_id\\\": \\\"req-1\\\"})\\n    await job_service.save_checkpoint(job_id, \\\"graph\\\", \\\"{}\\\")\\n\\n    assert await job_service.claim_suspended_for_resume(job_id) is True\\n\\n    cancelled = await _service()._cancel_suspended(job_id, job_service)\\n\\n    assert cancelled is False\\n    job = await job_service.get_job_by_job_id(job_id)\\n    assert job.status == JobStatus.IN_PROGRESS\\n    assert (job.job_metadata or {}).get(\\\"pending_request_id\\\") == \\\"req-1\\\"\\n    assert await job_service.load_checkpoint(job_id, \\\"graph\\\") is not None\\n    events = await job_service.read_events(job_id)\\n    assert all(e.event_type != \\\"run_cancelled\\\" for e in events)\\n\\n\\nasync def test_supersede_returns_only_jobs_it_actually_cancelled(real_services_job_service):\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n    resumed_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id, request_id=\\\"req-2\\\")\\n    assert await job_service.claim_suspended_for_resume(resumed_job_id) is True\\n\\n    superseded = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=str(flow_id))\\n\\n    assert superseded == [stale_job_id]\\n    resumed = await job_service.get_job_by_job_id(resumed_job_id)\\n    assert resumed.status == JobStatus.IN_PROGRESS\\n\\n\\nasync def test_supersede_resolves_the_persisted_human_input_card(real_services_job_service):\\n    \\\"\\\"\\\"The chat card persisted for the pause must close when its run is superseded.\\n\\n    Cancellation used to clear only ``pending_request_id``; after a history reload\\n    the card (no ``submitted_action``) turned interactive again and every click\\n    409'd against the cancelled job.\\n    \\\"\\\"\\\"\\n    from langflow.services.database.models.message.model import MessageTable\\n    from lfx.services.deps import session_scope\\n\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n\\n    card = MessageTable(\\n        text=\\\"\\\",\\n        sender=\\\"Machine\\\",\\n        sender_name=\\\"AI\\\",\\n        session_id=\\\"session-1\\\",\\n        flow_id=flow_id,\\n        files=[],\\n        content_blocks=[\\n            {\\n                \\\"title\\\": \\\"Human input required\\\",\\n                \\\"contents\\\": [{\\\"type\\\": \\\"human_input\\\", \\\"request_id\\\": \\\"req-1\\\", \\\"options\\\": [], \\\"allowed_decisions\\\": []}],\\n            }\\n        ],\\n    )\\n    async with session_scope() as session:\\n        session.add(card)\\n        await session.flush()\\n        card_id = card.id\\n    await job_service.update_job_metadata(job_id, {\\\"card_message_id\\\": str(card_id)})\\n\\n    superseded = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=str(flow_id))\\n    assert job_id in superseded\\n\\n    async with session_scope() as session:\\n        reloaded = await session.get(MessageTable, card_id)\\n        content = reloaded.content_blocks[0][\\\"contents\\\"][0]\\n        assert content.get(\\\"superseded\\\") is True\\n        assert content.get(\\\"submitted_action\\\") is None\\n\\n\\nasync def test_submit_supersedes_the_previous_suspended_run(real_services_job_service):\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n\\n    service = _service()\\n    new_job_id = await service.submit(\\n        flow_id=flow_id,\\n        request={\\\"flow_id\\\": str(flow_id), \\\"stream_protocol\\\": \\\"langflow\\\"},\\n        user=SimpleNamespace(id=user_id),\\n    )\\n\\n    stale = await job_service.get_job_by_job_id(stale_job_id)\\n    assert stale.status == JobStatus.CANCELLED\\n    for _ in range(100):\\n        new = await job_service.get_job_by_job_id(new_job_id)\\n        if new.status == JobStatus.COMPLETED:\\n            break\\n        await asyncio.sleep(0.05)\\n    assert new.status == JobStatus.COMPLETED\\n\\n\\nasync def test_submit_does_not_supersede_suspended_run_of_a_different_session(real_services_job_service):\\n    \\\"\\\"\\\"Submitting for session-b must leave a SUSPENDED run of session-a alone (issue #14599).\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id, session_id=\\\"session-a\\\")\\n\\n    service = _service()\\n    new_job_id = await service.submit(\\n        flow_id=flow_id,\\n        request={\\\"flow_id\\\": str(flow_id), \\\"session_id\\\": \\\"session-b\\\", \\\"stream_protocol\\\": \\\"langflow\\\"},\\n        user=SimpleNamespace(id=user_id),\\n    )\\n\\n    stale = await job_service.get_job_by_job_id(stale_job_id)\\n    assert stale.status == JobStatus.SUSPENDED\\n    assert (stale.job_metadata or {}).get(\\\"pending_request_id\\\") is not None\\n    new = await _wait_for_completed(job_service, new_job_id)\\n    assert new.status == JobStatus.COMPLETED\\n\\n\\nasync def test_submit_supersedes_suspended_run_of_same_session(real_services_job_service):\\n    \\\"\\\"\\\"Re-running the SAME session replaces its own stale pause, as before.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id, session_id=\\\"session-a\\\")\\n\\n    new_job_id = await _service().submit(\\n        flow_id=flow_id,\\n        request={\\\"flow_id\\\": str(flow_id), \\\"session_id\\\": \\\"session-a\\\", \\\"stream_protocol\\\": \\\"langflow\\\"},\\n        user=SimpleNamespace(id=user_id),\\n    )\\n\\n    stale = await job_service.get_job_by_job_id(stale_job_id)\\n    assert stale.status == JobStatus.CANCELLED\\n    assert (await _wait_for_completed(job_service, new_job_id)).status == JobStatus.COMPLETED\\n\\n\\nasync def test_submit_supersedes_suspended_run_when_both_have_no_session(real_services_job_service):\\n    \\\"\\\"\\\"Canvas reruns (no session on either side) fall back to flow_id and still replace.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n\\n    new_job_id = await _service().submit(\\n        flow_id=flow_id,\\n        request={\\\"flow_id\\\": str(flow_id), \\\"stream_protocol\\\": \\\"langflow\\\"},\\n        user=SimpleNamespace(id=user_id),\\n    )\\n\\n    stale = await job_service.get_job_by_job_id(stale_job_id)\\n    assert stale.status == JobStatus.CANCELLED\\n    assert (await _wait_for_completed(job_service, new_job_id)).status == JobStatus.COMPLETED\\n\\n\\nasync def test_supersede_only_targets_matching_session(real_services_job_service):\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    job_a = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id, session_id=\\\"session-a\\\")\\n    job_b = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id, session_id=\\\"session-b\\\")\\n\\n    superseded = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=\\\"session-b\\\")\\n\\n    assert superseded == [job_b]\\n    job_a_after = await job_service.get_job_by_job_id(job_a)\\n    assert job_a_after.status == JobStatus.SUSPENDED\\n    job_b_after = await job_service.get_job_by_job_id(job_b)\\n    assert job_b_after.status == JobStatus.CANCELLED\\n\\n\\nasync def test_supersede_suspended_run_of_different_session_not_cancelled_when_legacy(real_services_job_service):\\n    \\\"\\\"\\\"A legacy suspended run (no session, effective flow_id) is not cancelled by a sessioned submit.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id)\\n\\n    new_job_id = await _service().submit(\\n        flow_id=flow_id,\\n        request={\\\"flow_id\\\": str(flow_id), \\\"session_id\\\": \\\"session-b\\\", \\\"stream_protocol\\\": \\\"langflow\\\"},\\n        user=SimpleNamespace(id=user_id),\\n    )\\n\\n    stale = await job_service.get_job_by_job_id(stale_job_id)\\n    assert stale.status == JobStatus.SUSPENDED\\n    assert (await _wait_for_completed(job_service, new_job_id)).status == JobStatus.COMPLETED\\n\\n\\nasync def test_supersede_reads_the_session_off_legacy_flat_metadata(real_services_job_service):\\n    \\\"\\\"\\\"A legacy row carrying a flat ``job_metadata['session_id']`` is scoped by that session.\\\"\\\"\\\"\\n    job_service = real_services_job_service\\n    flow_id, user_id = uuid4(), uuid4()\\n    stale_job_id = await _suspend_a_job(job_service, flow_id=flow_id, user_id=user_id, legacy_session_id=\\\"session-a\\\")\\n\\n    untouched = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=\\\"session-b\\\")\\n    assert untouched == []\\n    assert (await job_service.get_job_by_job_id(stale_job_id)).status == JobStatus.SUSPENDED\\n\\n    superseded = await _service().supersede_suspended_runs(flow_id=flow_id, user_id=user_id, session_id=\\\"session-a\\\")\\n    assert superseded == [stale_job_id]\\n    assert (await job_service.get_job_by_job_id(stale_job_id)).status == JobStatus.CANCELLED\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/data/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/base/data/test_kb_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b7e0445be2a8f0154884b62ab498683fb3359bd8976588e8053c1458ef0b9f10\",\"content\":\"import pytest\\nfrom langflow.base.knowledge_bases.knowledge_base_utils import compute_bm25, compute_tfidf\\n\\n\\nclass TestKBUtils:\\n    \\\"\\\"\\\"Test suite for knowledge base utility functions.\\\"\\\"\\\"\\n\\n    # Test data for TF-IDF and BM25 tests\\n    @pytest.fixture\\n    def sample_documents(self):\\n        \\\"\\\"\\\"Sample documents for testing.\\\"\\\"\\\"\\n        return [\\\"the cat sat on the mat\\\", \\\"the dog ran in the park\\\", \\\"cats and dogs are pets\\\", \\\"birds fly in the sky\\\"]\\n\\n    @pytest.fixture\\n    def query_terms(self):\\n        \\\"\\\"\\\"Sample query terms for testing.\\\"\\\"\\\"\\n        return [\\\"cat\\\", \\\"dog\\\"]\\n\\n    @pytest.fixture\\n    def empty_documents(self):\\n        \\\"\\\"\\\"Empty documents for edge case testing.\\\"\\\"\\\"\\n        return [\\\"\\\", \\\"\\\", \\\"\\\"]\\n\\n    @pytest.fixture\\n    def single_document(self):\\n        \\\"\\\"\\\"Single document for testing.\\\"\\\"\\\"\\n        return [\\\"hello world\\\"]\\n\\n    def test_compute_tfidf_basic(self, sample_documents, query_terms):\\n        \\\"\\\"\\\"Test basic TF-IDF computation.\\\"\\\"\\\"\\n        scores = compute_tfidf(sample_documents, query_terms)\\n\\n        # Should return a score for each document\\n        assert len(scores) == len(sample_documents)\\n\\n        # All scores should be floats\\n        assert all(isinstance(score, float) for score in scores)\\n\\n        # First document contains \\\"cat\\\", should have non-zero score\\n        assert scores[0] > 0.0\\n\\n        # Second document contains \\\"dog\\\", should have non-zero score\\n        assert scores[1] > 0.0\\n\\n        # Third document contains both \\\"cats\\\" and \\\"dogs\\\", but case-insensitive matching should work\\n        # Note: \\\"cats\\\" != \\\"cat\\\" exactly, so this tests the term matching behavior\\n        assert scores[2] >= 0.0\\n\\n        # Fourth document contains neither term, should have zero score\\n        assert scores[3] == 0.0\\n\\n    def test_compute_tfidf_case_insensitive(self):\\n        \\\"\\\"\\\"Test that TF-IDF computation is case insensitive.\\\"\\\"\\\"\\n        documents = [\\\"The CAT sat\\\", \\\"the dog RAN\\\", \\\"CATS and DOGS\\\"]\\n        query_terms = [\\\"cat\\\", \\\"DOG\\\"]\\n\\n        scores = compute_tfidf(documents, query_terms)\\n\\n        # First document should match \\\"cat\\\" (case insensitive)\\n        assert scores[0] > 0.0\\n\\n        # Second document should match \\\"dog\\\" (case insensitive)\\n        assert scores[1] > 0.0\\n\\n    def test_compute_tfidf_empty_documents(self, empty_documents, query_terms):\\n        \\\"\\\"\\\"Test TF-IDF with empty documents.\\\"\\\"\\\"\\n        scores = compute_tfidf(empty_documents, query_terms)\\n\\n        # Should return scores for all documents\\n        assert len(scores) == len(empty_documents)\\n\\n        # All scores should be zero since documents are empty\\n        assert all(score == 0.0 for score in scores)\\n\\n    def test_compute_tfidf_empty_query_terms(self, sample_documents):\\n        \\\"\\\"\\\"Test TF-IDF with empty query terms.\\\"\\\"\\\"\\n        scores = compute_tfidf(sample_documents, [])\\n\\n        # Should return scores for all documents\\n        assert len(scores) == len(sample_documents)\\n\\n        # All scores should be zero since no query terms\\n        assert all(score == 0.0 for score in scores)\\n\\n    def test_compute_tfidf_single_document(self, single_document):\\n        \\\"\\\"\\\"Test TF-IDF with single document.\\\"\\\"\\\"\\n        query_terms = [\\\"hello\\\", \\\"world\\\"]\\n        scores = compute_tfidf(single_document, query_terms)\\n\\n        assert len(scores) == 1\\n        # With only one document, IDF = log(1/1) = 0, so TF-IDF score is always 0\\n        # This is correct mathematical behavior - TF-IDF is designed to discriminate between documents\\n        assert scores[0] == 0.0\\n\\n    def test_compute_tfidf_two_documents_positive_scores(self):\\n        \\\"\\\"\\\"Test TF-IDF with two documents to ensure positive scores are possible.\\\"\\\"\\\"\\n        documents = [\\\"hello world\\\", \\\"goodbye earth\\\"]\\n        query_terms = [\\\"hello\\\", \\\"world\\\"]\\n        scores = compute_tfidf(documents, query_terms)\\n\\n        assert len(scores) == 2\\n        # First document contains both terms, should have positive score\\n        assert scores[0] > 0.0\\n        # Second document contains neither term, should have zero score\\n        assert scores[1] == 0.0\\n\\n    def test_compute_tfidf_no_documents(self):\\n        \\\"\\\"\\\"Test TF-IDF with no documents.\\\"\\\"\\\"\\n        scores = compute_tfidf([], [\\\"cat\\\", \\\"dog\\\"])\\n\\n        assert scores == []\\n\\n    def test_compute_tfidf_term_frequency_calculation(self):\\n        \\\"\\\"\\\"Test TF-IDF term frequency calculation.\\\"\\\"\\\"\\n        # Documents with different term frequencies for the same term\\n        documents = [\\\"rare word text\\\", \\\"rare rare word\\\", \\\"other content\\\"]\\n        query_terms = [\\\"rare\\\"]\\n\\n        scores = compute_tfidf(documents, query_terms)\\n\\n        # \\\"rare\\\" appears in documents 0 and 1, but with different frequencies\\n        # Document 1 has higher TF (2/3 vs 1/3), so should score higher\\n        assert scores[0] > 0.0  # Contains \\\"rare\\\" once\\n        assert scores[1] > scores[0]  # Contains \\\"rare\\\" twice, should score higher\\n        assert scores[2] == 0.0  # Doesn't contain \\\"rare\\\"\\n\\n    def test_compute_tfidf_idf_calculation(self):\\n        \\\"\\\"\\\"Test TF-IDF inverse document frequency calculation.\\\"\\\"\\\"\\n        # \\\"rare\\\" appears in only one document, \\\"common\\\" appears in both\\n        documents = [\\\"rare term\\\", \\\"common term\\\", \\\"common word\\\"]\\n        query_terms = [\\\"rare\\\", \\\"common\\\"]\\n\\n        scores = compute_tfidf(documents, query_terms)\\n\\n        # First document should have higher score due to rare term having higher IDF\\n        assert scores[0] > scores[1]  # rare term gets higher IDF\\n        assert scores[0] > scores[2]\\n\\n    def test_compute_bm25_basic(self, sample_documents, query_terms):\\n        \\\"\\\"\\\"Test basic BM25 computation.\\\"\\\"\\\"\\n        scores = compute_bm25(sample_documents, query_terms)\\n\\n        # Should return a score for each document\\n        assert len(scores) == len(sample_documents)\\n\\n        # All scores should be floats\\n        assert all(isinstance(score, float) for score in scores)\\n\\n        # First document contains \\\"cat\\\", should have non-zero score\\n        assert scores[0] > 0.0\\n\\n        # Second document contains \\\"dog\\\", should have non-zero score\\n        assert scores[1] > 0.0\\n\\n        # Fourth document contains neither term, should have zero score\\n        assert scores[3] == 0.0\\n\\n    def test_compute_bm25_parameters(self, sample_documents, query_terms):\\n        \\\"\\\"\\\"Test BM25 with different k1 and b parameters.\\\"\\\"\\\"\\n        # Test with default parameters\\n        scores_default = compute_bm25(sample_documents, query_terms)\\n\\n        # Test with different k1\\n        scores_k1 = compute_bm25(sample_documents, query_terms, k1=2.0)\\n\\n        # Test with different b\\n        scores_b = compute_bm25(sample_documents, query_terms, b=0.5)\\n\\n        # Test with both different\\n        scores_both = compute_bm25(sample_documents, query_terms, k1=2.0, b=0.5)\\n\\n        # All should return valid scores\\n        assert len(scores_default) == len(sample_documents)\\n        assert len(scores_k1) == len(sample_documents)\\n        assert len(scores_b) == len(sample_documents)\\n        assert len(scores_both) == len(sample_documents)\\n\\n        # Scores should be different with different parameters\\n        assert scores_default != scores_k1\\n        assert scores_default != scores_b\\n\\n    def test_compute_bm25_case_insensitive(self):\\n        \\\"\\\"\\\"Test that BM25 computation is case insensitive.\\\"\\\"\\\"\\n        documents = [\\\"The CAT sat\\\", \\\"the dog RAN\\\", \\\"CATS and DOGS\\\"]\\n        query_terms = [\\\"cat\\\", \\\"DOG\\\"]\\n\\n        scores = compute_bm25(documents, query_terms)\\n\\n        # First document should match \\\"cat\\\" (case insensitive)\\n        assert scores[0] > 0.0\\n\\n        # Second document should match \\\"dog\\\" (case insensitive)\\n        assert scores[1] > 0.0\\n\\n    def test_compute_bm25_empty_documents(self, empty_documents, query_terms):\\n        \\\"\\\"\\\"Test BM25 with empty documents.\\\"\\\"\\\"\\n        scores = compute_bm25(empty_documents, query_terms)\\n\\n        # Should return scores for all documents\\n        assert len(scores) == len(empty_documents)\\n\\n        # All scores should be zero since documents are empty\\n        assert all(score == 0.0 for score in scores)\\n\\n    def test_compute_bm25_empty_query_terms(self, sample_documents):\\n        \\\"\\\"\\\"Test BM25 with empty query terms.\\\"\\\"\\\"\\n        scores = compute_bm25(sample_documents, [])\\n\\n        # Should return scores for all documents\\n        assert len(scores) == len(sample_documents)\\n\\n        # All scores should be zero since no query terms\\n        assert all(score == 0.0 for score in scores)\\n\\n    def test_compute_bm25_single_document(self, single_document):\\n        \\\"\\\"\\\"Test BM25 with single document.\\\"\\\"\\\"\\n        query_terms = [\\\"hello\\\", \\\"world\\\"]\\n        scores = compute_bm25(single_document, query_terms)\\n\\n        assert len(scores) == 1\\n        # With only one document, IDF = log(1/1) = 0, so BM25 score is always 0\\n        # This is correct mathematical behavior - both TF-IDF and BM25 are designed to discriminate between documents\\n        assert scores[0] == 0.0\\n\\n    def test_compute_bm25_two_documents_positive_scores(self):\\n        \\\"\\\"\\\"Test BM25 with two documents to ensure positive scores are possible.\\\"\\\"\\\"\\n        documents = [\\\"hello world\\\", \\\"goodbye earth\\\"]\\n        query_terms = [\\\"hello\\\", \\\"world\\\"]\\n        scores = compute_bm25(documents, query_terms)\\n\\n        assert len(scores) == 2\\n        # First document contains both terms, should have positive score\\n        assert scores[0] > 0.0\\n        # Second document contains neither term, should have zero score\\n        assert scores[1] == 0.0\\n\\n    def test_compute_bm25_no_documents(self):\\n        \\\"\\\"\\\"Test BM25 with no documents.\\\"\\\"\\\"\\n        scores = compute_bm25([], [\\\"cat\\\", \\\"dog\\\"])\\n\\n        assert scores == []\\n\\n    def test_compute_bm25_document_length_normalization(self):\\n        \\\"\\\"\\\"Test BM25 document length normalization.\\\"\\\"\\\"\\n        # Test with documents where some terms appear in subset of documents\\n        documents = [\\n            \\\"cat unique1\\\",  # Short document with unique term\\n            \\\"cat dog bird mouse elephant tiger lion bear wolf unique2\\\",  # Long document with unique term\\n            \\\"other content\\\",  # Document without query terms\\n        ]\\n        query_terms = [\\\"unique1\\\", \\\"unique2\\\"]\\n\\n        scores = compute_bm25(documents, query_terms)\\n\\n        # Documents with unique terms should have positive scores\\n        assert scores[0] > 0.0  # Contains \\\"unique1\\\"\\n        assert scores[1] > 0.0  # Contains \\\"unique2\\\"\\n        assert scores[2] == 0.0  # Contains neither term\\n\\n        # Document length normalization affects scores\\n        assert len(scores) == 3\\n\\n    def test_compute_bm25_term_frequency_saturation(self):\\n        \\\"\\\"\\\"Test BM25 term frequency saturation behavior.\\\"\\\"\\\"\\n        # Test with documents where term frequencies can be meaningfully compared\\n        documents = [\\n            \\\"rare word text\\\",  # TF = 1 for \\\"rare\\\"\\n            \\\"rare rare word\\\",  # TF = 2 for \\\"rare\\\"\\n            \\\"rare rare rare rare rare word\\\",  # TF = 5 for \\\"rare\\\"\\n            \\\"other content\\\",  # No \\\"rare\\\" term\\n        ]\\n        query_terms = [\\\"rare\\\"]\\n\\n        scores = compute_bm25(documents, query_terms)\\n\\n        # Documents with the term should have positive scores\\n        assert scores[0] > 0.0  # TF=1\\n        assert scores[1] > 0.0  # TF=2\\n        assert scores[2] > 0.0  # TF=5\\n        assert scores[3] == 0.0  # TF=0\\n\\n        # Scores should increase with term frequency, but with diminishing returns\\n        assert scores[1] > scores[0]  # TF=2 > TF=1\\n        assert scores[2] > scores[1]  # TF=5 > TF=2\\n\\n        # Check that increases demonstrate saturation effect\\n        increase_1_to_2 = scores[1] - scores[0]\\n        increase_2_to_5 = scores[2] - scores[1]\\n        assert increase_1_to_2 > 0\\n        assert increase_2_to_5 > 0\\n\\n    def test_compute_bm25_idf_calculation(self):\\n        \\\"\\\"\\\"Test BM25 inverse document frequency calculation.\\\"\\\"\\\"\\n        # \\\"rare\\\" appears in only one document, \\\"common\\\" appears in multiple\\n        documents = [\\\"rare term\\\", \\\"common term\\\", \\\"common word\\\"]\\n        query_terms = [\\\"rare\\\", \\\"common\\\"]\\n\\n        scores = compute_bm25(documents, query_terms)\\n\\n        # First document should have higher score due to rare term having higher IDF\\n        assert scores[0] > scores[1]  # rare term gets higher IDF\\n        assert scores[0] > scores[2]\\n\\n    def test_compute_bm25_zero_parameters(self, sample_documents, query_terms):\\n        \\\"\\\"\\\"Test BM25 with edge case parameters.\\\"\\\"\\\"\\n        # Test with k1=0 (no term frequency scaling)\\n        scores_k1_zero = compute_bm25(sample_documents, query_terms, k1=0.0)\\n        assert len(scores_k1_zero) == len(sample_documents)\\n\\n        # Test with b=0 (no document length normalization)\\n        scores_b_zero = compute_bm25(sample_documents, query_terms, b=0.0)\\n        assert len(scores_b_zero) == len(sample_documents)\\n\\n        # Test with b=1 (full document length normalization)\\n        scores_b_one = compute_bm25(sample_documents, query_terms, b=1.0)\\n        assert len(scores_b_one) == len(sample_documents)\\n\\n    def test_tfidf_vs_bm25_comparison(self, sample_documents, query_terms):\\n        \\\"\\\"\\\"Test that TF-IDF and BM25 produce different but related scores.\\\"\\\"\\\"\\n        tfidf_scores = compute_tfidf(sample_documents, query_terms)\\n        bm25_scores = compute_bm25(sample_documents, query_terms)\\n\\n        # Both should return same number of scores\\n        assert len(tfidf_scores) == len(bm25_scores) == len(sample_documents)\\n\\n        # For documents that match, both should be positive\\n        for i in range(len(sample_documents)):\\n            if tfidf_scores[i] > 0:\\n                assert bm25_scores[i] > 0, f\\\"Document {i} has TF-IDF score but zero BM25 score\\\"\\n            if bm25_scores[i] > 0:\\n                assert tfidf_scores[i] > 0, f\\\"Document {i} has BM25 score but zero TF-IDF score\\\"\\n\\n    def test_compute_tfidf_special_characters(self):\\n        \\\"\\\"\\\"Test TF-IDF with documents containing special characters.\\\"\\\"\\\"\\n        documents = [\\\"hello, world!\\\", \\\"world... hello?\\\", \\\"no match here\\\"]\\n        query_terms = [\\\"hello\\\", \\\"world\\\"]\\n\\n        scores = compute_tfidf(documents, query_terms)\\n\\n        # Should handle punctuation and still match terms\\n        assert len(scores) == 3\\n        # Note: Current implementation does simple split(), so punctuation stays attached\\n        # This tests the current behavior - may need updating if tokenization improves\\n\\n    def test_compute_bm25_special_characters(self):\\n        \\\"\\\"\\\"Test BM25 with documents containing special characters.\\\"\\\"\\\"\\n        documents = [\\\"hello, world!\\\", \\\"world... hello?\\\", \\\"no match here\\\"]\\n        query_terms = [\\\"hello\\\", \\\"world\\\"]\\n\\n        scores = compute_bm25(documents, query_terms)\\n\\n    ";
